window.__D("text/likkut-maanot-kodesh/c001",{"p":[[9200100134,"134\nליקוט מענות קודש – ה ' תשי \" ב - ה ' תשי \" ט\nקמ ה\nאור לי \" ט טבת , תשי \" ט ][\nממענה לר ' דובער בוימגארטען (\" כפר חב \" ד \" גליון 888 ע ' 124-127 :)\n[1 ] במכתבו כתב : \" כאן כולם מרגישים שיש חוסר בישיבה וכולם רוצים\nלייסד ישיבה , רק שחסר להם ר \" מ או מגיד - שיעור בגמרא . ולייסד מוסד\nכזה לא יעלה בקישויים ולדעתי יכולים לסדר ישיבה לפי דרכנו ורוחנו\nבכל הפרטים , והנני תאב לשום את השם \" אהלי יוסף יצחק \" באחד\nהמקומות בבואנ וס איירס מקום תעמולתי זה זמן רב .\"\nכ \" ק אדמו \" ר שליט \" א סימן קו תחת תיבת \" השם \", וכתב :\n(4 ) אפשר לדון רק לאחרי שיהי ' ענין של קיימא משך זמן . ויתברר אם\nתהי ' מחלוקת וכו .'\n[2 ] במכתבו כתב : \" בטח ירצה אד \" ש לשלוח שמורה לשובה ישראל בשנה\nזו כמו בשנים הקודמים , וכבר כתבתי לכ \" ק אד \" ש בתמוז כשנסענו\nלקצור החטים שאולי יהי ' יותר בזול שלוח החיטים לשם שיאפו שם ולא\nיעלה המחיר אפי ' חלק עשירית ממה שעולים המשלוח דהשמורה .\"?\nמענה כ \" ק אדמו \" ר שליט \" א :\n(5 ) בטח הרב עקשטיין שי ' יאפה גם השנה כמו מלפנים . ומהו ההכרח\nבשילוח זה .\n[3 ] במכתבו כתב : \" ישנה עיר בארגנטינה במחוז סענטא פע הנק ' משרוויל\nוזה יסד שם בארון הירש , וישנם הרבה יהודים ביהכנ \" ס נוסח אר \" י . .\nהי ' ראוי לבקר שם ולעורר היהודים דשם ואפשר יכולים למצוא איזה\nכתבים וכו '. ע \" כ כשייטב הביקור בעיניו הק ' אבקר שם . ברכבת נוסעים\nי \" ב שע ות , ובאווירון ב ' שעות .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(6 ) נכון במאוד והוצאות הנסיעה מב . א . לשם וחזרה ודהשהי ' שם כמובן\nעל המ . ל . ח .\n[4 ] במכתבו כתב : \" ישנו איש א ' שו \" ב יוסף מרדכי בן שרה פרוכטער\nשאומר ששימש הרבה כ \" ק אד \" ש בפאריז אחר המלחמה וביקש\nשאזכירו לטובה שיפקוד בזחו \" ק שזה כמה שנים אחרי חתונתו ועדיין\nלא נפקד .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(7 ) אולי כוונתו לגיסי שליט \" א אזכירו על הציון וכן ( 11 ) ( 8)"],[9200100135,"135\nליקוט מענות קודש – ה ' תשי \" ב - ה ' תשי \" ט\n[5 במכתבו כתב ע \" ד המשך לימודיהם של שניים מתלמידי הישיבה .]\nמענה כ \" ק אדמו \" ר שליט \" א :\n(9 להמשיך ככל האפשרי .)\nקמ ו\nלאחר ש \" פ משפטים , כ \" ט שבט , תשי \" ט ][\nמענה להמניחים על שאלתם במאמר ד \" ה ויראו את אלקי ישראל דש \" פ\nמשפטים ( מצילום כתי \" ק – ריש תו \" מ התועדויות חכ \" ה ( תשי \" ט ח \" ב :))\n[1 ] במכתבם כתבו : \" בד \" ה ויראו את אלקי ישראל נתבאר בענין הכלים\nדאצי ' אשר הם עצמם בל \" ג ורק שפועלים הגבלה בבי \" ע . ונתבאר משל\nמכח התנועה והכתיבה , אשר הוא כח בל \" ג , שיכול לכתוב אותיות עד אין\nקץ , אך המשכת האותיות בפועל , שכל אות ואות הוא מפורט ומוגבל , הרי\nזה מכח הגב ול דוקא . וא \" כ הרי גם כח הגבול הוא בל \" ג , והי ' לשון בזה :\nשכח הגבול עצמו הוא הבל \" ג , שהרי ענינו של כח התנועה אינו לכתוב\nסתם שרטוטים כ \" א אותיות מפורטים , שזהו ע \" י כח הגבול דוקא , וא \" כ\nהרי כח הגבול עצמו הוא הבל \" ג .\nמענה כ \" ק אדמו \" ר שליט \" א :\n[ בד \" ה ויראו את אלקי ישראל נתבאר בענין הכלים דאצי ' אשר הם עצמם\nבל \" ג ורק שפועלים הגבלה ב ] וג \" ז רק ב [ בי \" ע . ונתבאר משל מכח התנועה\nוהכתיבה , אשר הוא כח בל \" ג , שיכול ] להניע תנועות או [ לכתוב אותיות\nעד אין קץ , אך המשכת ה ] צורת והגבלת כל תנועה או [ אות יות בפועל , שכל\nאות ה וא מפורט\n] תנועה [ ואות ] ה ם באופן מסוים [ ומוגבל , הרי זה מכח\nהגבול דוקא . וא \" כ הרי גם כח הגבול הוא בל \" ג ] כיון שמגביל [ והי ' לשון\nבזה : שכח הגבול עצמו הוא הבל \" ג ] הוא בלי גבולי [ שהרי ענינו של כח\nהתנועה אינו ] או הכתיבה הבע \" ג הוא להניע או [ לכתוב סתם שרטוטים כ \" א ]\nתנועות או [ אותיות מפורטים ] מסוימות [ שזהו ע \" י כח הגבול דוקא , וא \" כ\n)*\nהרי כח הגבול עצמו הוא ה ] הוא בל \" ג ][ , אלא שהוא כח המגביל , דלא ככח\nהבע \" ג .\n*) כמדומה ברור – שהוזכר באמירת המאמר לעיין לקו \" ת שה \" ש ד \" ה\nמה יפו פעמיך – נמצא ג \" כ בסו \" ס דרמ \" צ ( בשינוים .))(\nועייג \" כ המשך מים רבים פ \" ל ואילך . דרוש ג ' שיטות .\n[2 ] במכתבם כתבו : \" מהו הכוונה שכח הגבול הוא בל \" ג . אם שהוא בל \" ג\nבכמות שהרי הוא כותב אותיות מפורטים ( שהוא מצד הגבול ) בלי גבול .\nאו שהוא בל \" ג בענינו היינו שאין ענינו ענין הגבול כ \" א ענין הבל \" ג ,,"],[9200100136,"136\nליקוט מענות קודש – ה ' תשי \" ב - ה ' תשי \" ט\nדמאחר שענינו של כח התנועה שהוא כח הבל \" ג הוא לכתוב אותיות\nמפורטים והוא ע \" י כח הגבול דוקא , א \" כ הרי כח הגבול הוא אחד מעניניו\nשל כח הבל \" ג . וכמו \" כ הוא גם בבחי ' הכלים שאין ענינם ענין לעצמו , כ \" א\nהוא בשביל ענין האור , אשר מציאות האור הוא ע \" י הכלים דוקא ,\nוכמשנת \" ל בע נין הג ' פעולות שבאור שנעשה ע \" י הכלים .\"\nכ \" ק אדמו \" ר שליט \" א מחק את התיבות \" או שהוא בל \" ג בענינו , היינו\nכו '\", והשאיר את התיבות \" אם שהוא בל \" ג בכמות כו .\"'\nקמ ז\nט \" ו אד \" ר , תשי \" ט ][\nמענה לר ' משה פינחס הכהן כ \" ץ ששאל במש \" כ במאמר ד \" ה איתא\nבמדרש תהלים ( סה \" מ תש \" ח ע ' 272 ואילך ): \" ולכן כתיב ויקץ כישן הוי '\nוכתיב עורה למה תישן הוי '\", והרי בפסוק נאמר בשם אדנות ( תשורה\nגראנער יו \" ד תמוז תשע \" א ע ' 16. אגרות - קודש חי \" ח ע ' רכב :)\nבזח \" ג רצג , ב ( ועוד בכ \" מ בזח \" ג ) איתא אשר בענין ויקץ כישן הוי ]'[ הוא\nבשם הוי ' ולא אד ' וכ \" מ בתניא פי \" ט ( מדבארו על חכ ' שבנפש )\nומפי ' הענינים בזח \" ג שם ומס ' הליקוטים להאריז \" ל לתהלים סי ' מד\nמוכח דגם בענין למה תישן הוי ]'[ הוא בשם הוי ' ( מדפרשו על דורמיטא\nדז \" א .)\nקמ ח\nאד \" ש , תשי \" ט ][\nמענה לר ' אוריאל צימער שכתב ע \" ד ביקור אנ \" ש דירושלים עיה \" ק –\nאצל הרב ישראל משה דושינסקי ראש ישיבת דושינסקיא , והרב אברהם\nיצחק קאהן האדמו \" ר דתולדות אהרן – בהמשך לביקורם ב \" יחידות \"\nאצל כ \" ק אדמו \" ר שליט \" א בעת שהותם בארצות הברית ( תשורה לאופר\nה ' אד \" ר תשע \" ד ע ' 63 :)\nהמסרו המדובר ע \" ד ההכרח , ועתה ביחוד , דלימוד החסידות בקביעות\nוכמובן גם בישיבותיהם ? אם הושמט או שקיצרו ( כי דובר באריכות )\nצריך ליצור הזדמנות שיוכלו לשאלם הדובר על זה , ומה , ובפרטיות , וכו '\nוכו .'"],[9200100137,"137\nליקוט מענות קודש – ה ' תשי \" ב - ה ' תשי \" ט\nק מט\nר \" ח ניסן , תשי \" ט ][\nמענה לר ' מאיר איטקין שכתב שמציעים לו דירה בשכונת קראונהייטס\nברחוב פרעזידענט ורא ד זש ע רס , \" ומבקש עצת וברכת כ \" ק שליט \" א בכל\nהפרטים בגו \" ר \". במכתבו כתב בין השאר ע \" ד גוי המתגורר בבנין\nבסמיכות לדירה המוצעת ( מצילום כתי \" ק – תשורה איטקין כ \" ו תשרי\nתשס \" ח ע ' 38 :)\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את מה שכתב ע \" ד הגוי המתגורר\nבסמיכות , וכתב :\nהיש לחשוש למהותו , לב \" ב ?\nקנ\nב ' אייר , תשי \" ט ][\nמענה לר ' דובער בוימגארטען (\" כפר חב \" ד \" גליון 888 ע ' 127-128 :)\n[1 ] במכתבו כתב : \" בנוגע למסיבת שבת שעבר בכי טוב , אם כי רוצים\nלהזמין יותר קטנים כי גדולים קשה צו האלטן . גב ' . . רצתה שבעד\nהממתקים ישלמו שם במקום לשלם מהסענטראל אפיס , ואמרתי דעתי\nשבאם היא בעצמה תתן הכל יכול להיות , משא \" כ כמו שהיא חפצה לסדר\nשבכל שבוע תתן אם אחר ת זה לא יתכן כי הרי אחרים לא יחפצו ליתן\nועי \" ז יבטלו את בניהם מלבא עוד , וגם אותן שיתנו יבואו ויתערבו בעניני\nחינוך וכו ' – הנכון .\"?\nעל מה שכתב : \" הנכון \"? – כ \" ק אדמו \" ר שליט \" א מחק את האות \" ה \"\nוסימן - השאלה , והשאיר תיבת \" נכון \"; ועל כללות השאלה כתב :\n?\n[2 ] במכתבו כתב : \" הרב . . עודנו מתענין בלימוד הדא \" ח כמקודם , למדנו\nיחד ג ' שעות המאמר ונקדשתי דפ ' אמור בטוב ובהסבר ולא גמרנוהו ( ולא\nעלה על דעתי שיהי ' התוועדות ביום ש \" ק זה והנחתי חיי עולם ועסקתי\nבחיי שעה ) . .\".\nכ \" ק אדמו \" ר שליט \" א מחק את התיבות \" עולם . . שעה \", וכתב :\nוהנחתי חיי ][ ם פרטים ועסקתי בחיי ][ ם כללים\n[3 ] במכתבו כתב : \" על מכתביי הקודמים לא השיב לי כלל כ \" ק אד \" ש . .\nלפי דעתי לרכוש זה ענין גדול שבו ועל ידו יוכל הענין של צא \" ח להתפשט"],[9200100138,"138\nליקוט מענות קודש – ה ' תשי \" ב - ה ' תשי \" ט\nשהוא אינו מחזיק זה בסוד כלל . . ואמר בפירוש שזה למדנו היום\nבחסידות והראה באצבעו עלי וכן אולי יגיע גם לתלמידותיו ב \" שטערן\nקאלעדזש \" שהרי הוא זעהר אן ערנסטער . . אבל מכיון שראיתי שכ \" ק\nאד \" ש לא ענה ע \" ז כלום וגם בשבת זו העבר עי \" ז אריינגעפאלען וחסרתי\nלהיות נוכח בה תוועדות , אולי אין זה הכוונה .\"\nכ \" ק אדמו \" ר שליט \" א סימן חץ מהתיבות \" לרכוש זה ענין גדול \"\nלהתיבות \" יגיע גם לתלמידותיו \"; ועל מה שכתב \" וגם בשבת זו העבר\nעי \" ז אריינגעפאלען וחסרתי להיות נוכח בהתוועדות \", כתב :\nמפיתויי היצר .\nקנ א\nאור לי \" ז אייר , תשי \" ט ][\nמענה לר ' דובער בוימגארטען שכתב : \" ונא אל יחר לפני כ \" ק אד \" ש\nכשהנני שואל האם להיות ש \" ק זו בקראון הייטס לפי שאומרים שגם\nבש \" ק זו יצא להתוועד עם העולם ולהיות שיתכן התוועדות הרי זה\nלהוסיף בלימוד וכו ' און מיר ווילט זיך מערער להיות בחצרות קדשנו ,\nואולי להגיד לי במה וועל איך בעסער אויספירן כוונתו הק '\" (\" כפר\nחב \" ד \" גליון 888 ע ' 128 :)\nבש \" ק הבע \" ל בטח ימשיך בשיעוריו בקאנטרי ולפלא הספק בזה .\nקנ ב\nתמוז , תשי \" ט ][\nמענה לר ' דוד ראסקין ששאל – בהמשך לפטירת גיסו ר ' דוד בראוומאן\nע \" ה , שלא השאיר אחריו בנים – האם תאמרנה הבנות קדיש ( תשורה\nמונדשיין י \" ד מנ \" א תשע \" ג ע ' 7 :)\nכבר עניתי\nראה מכתב ד ' תמוז תשי \" ט ( לר ' יעקב יוסף ראסקין )[ – תשורה שם .]"],[9200100139,"139\nליקוט מענות קודש – ה ' תשי \" ב - ה ' תשי \" ט\nקנ ג\nו ' מנ \" א , תשי \" ט ][\nמענה להרב מרדכי מענטליק על שאלתו בהמדובר בהתועדות י \" ג תמוז :\n\" בשיחת שמח \" ת תשח \" י . . כל המעל \" ע דשבת וגם תוספות שבת הוא\nגדר נקודה אחת . . ראי ' על זה מדברי המכילתא . . אמנם בהשיחה די \" ג\nתמוז השתא נתבאר ג \" כ בענין הנ \" ל בשם הראגאטשאווער והובא ג \" כ\nהמכילתא ונתבאר אשר אם לא הי ' לימוד מהפסוק היינו חושבים שהוא\nגדר נקודה ועל זה מגלה לנו הפסוק שהוא ג דר מצורף \" –\nראה אגרות - קודש חי \" ח ע ' תפב .\nקנ ד\nו ' אלול , תשי \" ט ][\nמענה לא ' התמימים שנסע במשך זמן הקייץ בשליחות המל \" ח – שכתב\nע \" ד הספקות שלו בתכלית ההשפעה על יחידים , בהתאם למיעוט\nהמתעסקים בהשפעה , ובמילא למיעוט המושפעים ( תשורה חדקוב כ \" ט\nסיון תשס \" א ע ' 59 :)\nכמה אפשריות – וכלן אמתיות – ישנן בהנ \" ל . ואחדות מהן : א ) לפעמים\nמצליחים לעורר את השומע באופן – שיעשה טופח על מנת להטפיח\nויעורר הנק ' reaction chain . ב ) מצליחים יותר שפוגשים איש שהוא\nבעל כחות נעלים ביותר , וכשפועלים עליו שינוי – עושה בכחות שלו .\nבדוגמת ניצוץ קטן שמספיק להבעיר אש גדולה ביותר באם מגישים\nאותו לחבית של אבק - שריפה ( powder וראה יבמות סב , ב .) 24,000\nתלמידים כו ' והי ' העולם שמם עד שבא כו ' והם כו '. ג ) מלבד כהנ \" ל\nהפס \" ד רמב \" ם תשובה פ \" ג ה \" ד ): עשה מצוה א ' הרי הכריע כו '( כל\nהעולם כלו כו .'\nקנ ה\nאלול , תשי \" ט ][\nמענה להת ' נפתלי הכהן ראטה ( מצילום כתי \" ק – קונטרס \" מכתבים\nומענות \" ע ' 5 . \" בית משיח \" גליון 985 ע ' 23 :)\n[1 ] במכתבו כתב ע \" ד הצלחת \" ישיבת הערב \" בירושלים עיה \" ק , וע \" ד\nהפצת ספרי החסידות ."],[9200100140,"140\nליקוט מענות קודש – ה ' תשי \" ב - ה ' תשי \" ט\nמענה כ \" ק אדמו \" ר שליט \" א :\n(1 ת \" ח על הבשו \" ט . המתכוננים שם כדבעי למבצע ד \" מ ?)\n[2 במכתבו כתב ע \" ד השתתפותו בשיעורי הר \" מ בנגלה .]\nמענה כ \" ק אדמו \" ר שליט \" א :\n(2 ) בטח משתתף גם בלימודי החסידות – שהרי תורה תמימה צ \" ל .\n[3 ] במכתבו כתב שמנצל את זמנו הפנוי לכתיבת מכתבים לתלמידיו\nשבירושלים עיה \" ק .\nמענה כ \" ק אדמו \" ר שליט \" א :\nבודאי לא יקמץ בזה . ויכלול – נקודות עכ \" פ – מהשיחות ומאמרים .\n[4 ] במכתבו שאל האם לכתוב לא ' מראשי ישיבת \" חברון \" בירושלים\nעיה \" ק ע \" ד הנעשה בחצרות קדשנו .\nמענה כ \" ק אדמו \" ר שליט \" א :\n(4) פשוט שנכון הוא . וכנ \" ל [ ויכלול – נקודות עכ \" פ – מהשיחות\nומאמרים . ]\n[5 על כללות המכתב , כתב כ \" ק אדמו \" ר שליט \" א :]\n(5 אזכיר עה \" צ .)\nקנ ו\nקייץ , תשי \" ט ][\nמענה להחתן הת ' נחמן סודאק על מכתבו – בהמשך למענה שקיבל ,\nשהסתדרותו אחר החתונה תהי ' באירופא , והחתונה תהי ' בלונדון .\nבמכתבו כתב , שהוא והכלה ומשפחתה נמצאים כולם בניו יארק , ורוצים\nשכ \" ק אדמו \" ר שליט \" א יסדר קידושין (\" כפר חב \" ד \" גליון 535 ע ' 26 :)\nמנהג ישראל לעשות החתונה במקום דירת הורי הכלה , ז . א . בלונדון ,\nוגם עליהם לעשות כן ."],[9200100141,"141\nליקוט מענות קודש – ה ' תשי \" ב - ה ' תשי \" ט\nקנ ז\nקייץ , תשי \" ט ][\nמענה להנהלת מוסד חינוך \" אהלי תורה \" בשכונת קראונהייטס שכתבו\nע \" ד פתיחת \" דיי קעמפ \" בזמן הקייץ ( תשורה ישיבת \" אהלי תורה \" ח \" י\nמרחשון תשנ \" ט ע ' 19 :)\nנכון הדבר במאד מאד . יעוין בלקו \" ת בענין טובה הארץ מאד מאד .\nקנ ח\nתשי \" ט ][\nממענה לר ' דובער בוימגארטען (\" כפר חב \" ד \" גליון 910 ע ' 104 :)\n[1 ] במכתבו כתב – בקשר לאחת הקהילות בבואנוס איירס : \" בפעמים\nהראשונות הייתי מתארח אצלם , אבל עכשיו עלי לברר האם להתעסק\nעמהם ועי \" ז להיות מוגבל מלהתעסק עם אחרים או לכתחילה לא\nאתקשר עמהם ואשתדל להסתדר עם ספרדים אחרים .\"?\nמענה כ \" ק אדמו \" ר שליט \" א :\n(2 ) לא יגביל א \" ע – עד שיברר המצב שם על אתר בהווה .\n[2 ] במכתבו כתב : \" בתי . . תי ' עוסקת במעוננו בקירוב בנות גילה לתומ \" צ\nוהי ' הצלחה וקירבה איזה נערות . אך הנערות כמנהג העולם מתהלכות\nעם בחורים בני יד - טו - טז והדומה , ואמה תי ' בראותה שבתי תי ' הולכת\nעם חברותי ' והן עם הבחורים אמרה שזה לא נראה בעיני ' . . בתי פסקה\nלהתה לך עם חברותי ' לגמרי .\"\nכ \" ק אדמו \" ר שליט \" א סימן קו תחת התיבות \" לא נראה בעיני '\", וכתב :\nזהו עפ \" י שו \" ע .\n[3 ] במכתבו כתב : \" וא \" כ שאלה לי אמה מה תעשה אולי אסור להגיד לה\nככה ועי \" ז מונעים אותה מלהשפיע על חברותי ' ולאידך גיסא מי יודע\nאפשר שעי \" ז תוכל להתקלקל .\"?\nכ \" ק אדמו \" ר שליט \" א מחק את התיבות : \" וא \" כ שאלה . . אולי אסור\nלהגיד לה ככה ועי \" ז מונעים אותה מלהשפיע על חברותי '\", וכתב :\nבזמן שאינן הולכות עם בחורים ."],[9200100142,"142\nליקוט מענות קודש – ה ' תשי \" ב - ה ' תשי \" ט\nק נט\nתשי \" ט ][\nמענה להת ' משה לאזאר שכתב ( באמצעות המזכיר ): \" ביקש למסור שיש\nלו הזדמנות לקנות קאר מש . א . שי ' פאפאק עבור $1100 . הקאר הוא\nבמצב טוב Ford Door 4 ’51 . צריך לקאר לסייע בעבודתו עבור גן ישראל\nואהלי תורה , ושואל אם לקנות הקאר הנ \" ל \" ( תשורה אבערלאנדער ח '\nתמוז תשע \" ו ע ' יח :)\nבאם הנ \" ל מקח פחות מעט עכ \" פ ממקח השווה .\nקס\nתשי \" ט ][\nמענה בקשר להגהת השיחות ( מהעתקה . המענה מתפרסם בזה לראשונה\nבאדיבות א ' מאנ \" ש שי ' וזכות הרבים תלוי ' בו :)\n.[ ]. ג ) הוכחה עד כמה אנ \" ש הם \" פאַרקאכט \" ונוגע להם כל ענין הו \" ל\nדהנ \" ל – שבמשך כל השנה , לא הי ' מי שיתעסק בבחירת החומר\nובהערכת הרשימות – לבד ג ' - ד ' אברכים – בחורים , ולולא ג ' - ד ' אלו –\nוואלט דער גאַנצער ענין געשמאק געשלאפען .\nד ) לברר לעצמי ולאנ \" ש יותר ברור את כהנ \" ל , יחס אנ \" ש – הזהרתי\nלפני כו \" כ חדשים שבאם לא ישופר הסגנון – תומשך ההופעה רק עד\nגמר השנה ( שכבר אין לי ברירה בזה , ובעצמי משתדל לשפר הסגנון ,\nעכ \" פ במקצת ), ולא נוסף אף אחד שע \" י אזהרה זו עכ \" פ , יעזור לג ' - ד '\nהנ \" ל בהנ \" ל .\nה ) לשנה הבע \" ל – יכולים להשתמש בהחוברות דאשתקד במקצת .\nוהעיקר – במאמרי ( ושיחות ) רבותינו שכתבים ( ולא מהנחות ). ואז אין\nמקום לכהנ \" ל .\nכי ו ) אין ענינם של ג - ד אלו להתחנן אצל אחרים – כ \" א אדרבה . ובאם\nאלו האחרים אין מכירים מה טובתם באמת – אין זכין לאדם בעל כרחו ."],[9200100143,"143\nליקוט מענות קודש – ה ' תשי \" ב - ה ' תשי \" ט"],[9200100144,"144\nליקוט מענות קודש – ה ' תשי \" ב - ה ' תשי \" ט\nלזכות\nכ \" ק אדמו \" ר שליט \" א"],[9200110001,"ליקוט ליקוט\nקובץ\nליקוט\nכתבי יד קודש\nכתבי תורת יד אשכנז קודש\n• יום הבהיר י ” ד כסלו •\nפראנקפורט , גרמני '\nיום הבהיר י “ א ניסן\nמענות קודש\n• •\nה ' • תש \" כ - תש ” ה ' נ • תשכ \" ג\n•\nקובץ א ' [ ט ]\nתשורה\nתשורה\nמשמחת הנישואין\nמשמחת הבר מצוה של\nשל\nי\nהת ' שניאור זלמן שי '\nשניאור זלמן וחנה שיחיו\nנמירובסקי\nרביסקי\nכ \" ט חשון , ערב ראש חודש כסלו תשע \" ט\nו ‘ ניסן ה ‘ תשע “ ח\n◆\nיום הבהיר יו \" ד שבט תשע \" ח\nיחי יחי אדוננו אדוננו מורנו מורנו ורבינו ורבינו מלך מלך המשיח המשיח לעולם לעולם ועד ועד\nחיים שנה לנשיאות כ \" ק אדמו \" ר שליט \" א"],[9200110002,""],[9200110003,"ב \" ה .\nפתח דבר\nלקראת כ \" ף מנחם - אב , יום ההילולא של הרה \" ג הרה \" ח וכו ' הרב לוי יצחק\nז \" ל , אביו של כ \" ק אדמו \" ר שליט \" א –\nהננו מוציאים לאור בזה \" ליקוט מענות קודש – תש \" כ - תשכ \" ג ,\" הכולל\nאת מענות קודש כ \" ק אדמו \" ר שליט \" א שכתבם במשך השנים תש \" כ -\nתשכ \" ג .\n*\n\" פון איין תורת נשיא דורנו גייט מען צו נאך א תורת נשיא דורנו \" ( שיחת\nש \" פ תזו \" מ תנש \" א – בלתי מוגה ). כמה \" חלקים \" ישנם לתורת נשיא דורנו\nכ \" ק אדמו \" ר שליט \" א .\nבין החלקים השונים בתורת כ \" ק אדמו \" ר שליט \" א , \" חלק \" מיוחד ישנו ,\nוהוא : \" מענות קודש \", הם אלפי המענות אשר כתב כ \" ק אדמו \" ר שליט \" א\nבמענה להשואלים :\nהחל מהשנים הראשונות לנשיאות כ \" ק אדמו \" ר שליט \" א , הנה לצד\nה \" אגרות \" ששלח להפונים אליו , נענו רבים מהמכתבים ע \" י כ \" ק אדמו \" ר\nשליט \" א בכתב יד קדשו על מכתב השואל , כאשר לאחר מכן נמסרים\nהדברים להנמען .\nבשנים הראשונות הי ' זה באופן מצומצם לפי - ערך , כאשר אלו שהיו\nנמצאים בסמיכות מקו ם קיבלו את מענה קדשו על גליון מכתבם .\nו ככל שעברו השנים – הלך הדבר והתרחב יותר ויותר , עד שהי ' לאופן\nהעיקרי בו עונה כ \" ק אדמו \" ר שליט \" א להכותבים אליו .\nעל אף היותו של \" חלק \" זה בתורת כ \" ק אדמו \" ר שליט \" א – חלק עיקרי ,\nנדמה , כי חלק זה אין מוסבת תשומת הלב אליו ככל הדרוש .\nטעם העיקרי לדבר הוא , ככל הנראה , כיון שמפוזרים מענות הקודש על\nפני כמה וכמה מקומות שונים , ועד עתה לא נמצא להם גואל שילקטם\nלפונדק אחד .\nצורך זה באנו למלאות בליקוטים אלו ."],[9200110004,"4\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nעד עתה הופיעו חוברות \" ליקוט מענות קודש \" דשנים : ה ' תשי \" ב –\n1\nה ' תשי \" ט ; ה ' תש \" מ – ה ' תשנ \" ב ,\nובתכניתנו להוציא ליקוטים נוספים בסדרה זה , להרוות צמאון אנ \" ש\nוהתמימים .\n*\nתודתנו נתונה לכל אלו שהואילו למסור את מענות הקודש שבידם\nלפרסום בליקוט זה , וזכות הרבים תלוי ' בהם .\nבמיוחד תודתנו נתונה למערכת אפליקציית \" מפתח \" על עזרתם .\nוכאן המקום לבקש בבקשה כפולה ומכופלת מכל מי שיש בידו מענות\nקודש שטרם פורסמו , למוסרם לידי המערכת על מנת לפרסמם , ויהיו בזה\nממזכי הרבים .\nכתובת הדוא \" ל של המערכת : likkutkatyak@gmail.com .\n*\n_________\n1 ) \" ליקוט מענות קודש – ה ' תשי \" ב - ה ' תשי \" ט ( יום הבהיר כ \" ח סיון ,\"\nה ' תשפ \" א ;) \" ליקוט מענות קודש – ה ' תש \" מ ( יום הבהיר יו \" ד שבט , ה ' תשפ \" א ;)\"\n\" ליקוט מענות קודש – ה ' תשמ \" א ( יום הבהיר ר \" ח כסלו , ה ' תשפ \" א ;)\" \" ליקוט\nמענות קודש – ה ' תשמ \" ב ( וא \" ו תשרי , ה ' תשפ \" א ;)\" \" ליקוט מענות קודש –\nה ' תשמ \" ג \" ( כ \" ף מנחם - אב , ה ' תש \" פ ;) \" ליקוט מענות קודש – ה ' תשד \" מ \" ( יום\nהבהיר כ \" ח סיון , ה ' תש \" פ ;) \" ליקוט מענות קודש – ה ' תשמ \" ה ( י \" ג אייר , ה ' תש \" פ ;)\"\n\" ליקוט מענות קודש – ה ' תשמ \" ו ( יום הבהיר י \" א ניסן , ה ' תש \" פ ;)\" \" ליקוט מענות\nקודש – ה ' תשמ \" ז ( יום הבהיר יו \" ד שבט , ה ' תש \" פ ;)\" \" ליקוט מענות קודש –\nה ' תשמ \" ח ( יום הבהיר ר \" ח כסלו , ה ' תש \" פ ;)\" \" ליקוט מענות קודש – ה ' תשמ \" ט \"\n( הוצאה ראשונה – כ \" ג סיון ה ' תשע \" ח ; הוצאה שני ' – יום הבהיר יו \" ד שבט\nה ' תשע \" ט ;) \" ליקוט מענות קודש – ה ' תש \" נ ( יום הבהיר י \" א ניסן , ה ' תשע \" ט ;)\"\n\" ליקוט מענות קודש – ה ' תנש \" א ( יום הבהיר כ \" ח סיון , ה ' תשע \" ט ;)\" \" ליקוט מענות\nקודש – תשנ \" ב ( וא \" ו תשרי , ה ' תש \" פ ;)\" \" ליקוט מענות קודש מילואים ח \" א\n( ה ' תשמ \" ט - ה ' תנש \" א ) \" ( ה אלול , ה ' תשע \" ט .)' \" ליקוט מענות קודש מילואים ח \" ב\n( ה ' תש \" מ - ה ' תשנ \" ב ) ( יום הבהיר י \" א ניסן , ה ' תשפ \" א .)\""],[9200110005,"5\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nויהי רצון שיחוס וירחם השי \" ת עלינו , ונזכה להתראות עם כ \" ק אדמו \" ר\nשליט \" א תיכף ומיד ממש , ותחזינה עינינו בהתפשטות מלכותו על כל באי\nעולם , תיכף ומיד ממש !\nמערכת \" ליקוט כתבי יד קודש \"\nערב כ \" ף מנ \" א , ה ' תש פ \" א\nברוקלין , נ . י ."],[9200110006,"6\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג"],[9200110007,"7\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nצילו מי כתי \" ק\n– פרסום ראשון –\nלקמן מענה י"],[9200110008,"8\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג"],[9200110009,"9\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nלקמן מענה נ"],[9200110010,"10\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nלקמן מענה קי"],[9200110011,"11\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nלקמן מענה קנג"],[9200110012,"12\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nלקמן מענה קנד"],[9200110013,"13\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nלקמן מענה קפה"],[9200110014,"14\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nלקמן מענה קפו"],[9200110015,"15\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nליקוט מענות קודש\n– ה ' תש \" כ - ה ' תש כ \" ג –\n–––––––– ––––––––\n•\nליקוט מענות קודש\n– תש \" כ –\nא\nג ' תשרי , צום גדלי ', תש \" כ ][\nמענה לר ' יוסף מנחם מענדל טענענבוים שכת ב – בהמשך לשיחת ליל ערב\nראש השנה ע \" ד ניצול ימים שמער \" ה ועד יוהכ \" פ ללימוד התורה באופן\nד \" ופרצת \" : \" הנני ב זה להודיע לכ \" ק כי בהתאם עם דברי כ \" ק בליל ער \" ה\nדבר ופרצת מר \" ה עד יוהכ \" פ הי ' היום אסיפה מכל הרמי \" ם דבעדפארד\nעוו . והוחלט לעורר את התלמידים על דבר \" ופרצת \" ללמוד בשקידה\nיתירה ולחדש את הלימוד של ופרצת משעה 8-7 ביתר שאת וביתר עז .\nמקום הלימוד יהי ' על 770 בהשאלאש . מחר אי \" ה נדבר ע ם כל\nהתלמידים השייכים לזה שיבואו ללמוד בשעה זו . כל הרמי \" ם ישתתפו\nבההשגחה על התלמידים . ויתן השי \" ת שנפעול ופרצת בעצמו ובהזולת\nכרצון וברכת כ \" ק אדמו \" ר שליט \" א \" ( ס ' \" תולדות התמימים בארצות\nהברית \" ע ' 552 :)\nיה \" ר שירצו בהנ \" ל ככל הדרוש ואז הרי הובטח יגעת ומצאת ובפרט\nבזמן דקירוב המאור ( למע ' וממילא גם שבנפש האלקית ) אל הניצוץ .\nוכמחז \" ל : כאן ( בעשי \" ת ) ביחיד תשובה דיחידה יחידו של עולם ( בזה \" ל\nשמענו בלאדי . חנה אריאל האזינו מד , ב .)\n[ וראה לקמן מענות : ב , ה .]"],[9200110016,"16\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nב\nה ' תשרי , תש \" כ ][\nמענה לר ' יוסף מנחם מענדל טענענבוים שכתב : \" הנני בזה להודיע לכ \" ק\nכי אתמול באו להלימוד ד \" ופרצת \" משעה 8-7 יותר משבעים תלמידים\nכ \" י , למדו בחיות גדול ובקול שנשמע גם ברחוב מרחוק , שעשתה רושם\nגדול ביותר . אחר הלימוד התפללו תפלת ערבית בציבור . כמה\nמהתלמידים שאין יכולים לבוא מצד ריחוק מקום הבטיחו שילמדו\nבביתם בזמן הנ \" ל , כן התלמידים ממחלקות הגבוהות דמתיבתא אשר\nהסדר שלהם הוא עד שעה 7 בערך הבטיחו להוסיף בלימוד בזמנים\nהפנוים שלהם . מהרמי \" ם השתתפו אתמול : הרב לרנר , הרב פאפאק ,\nהרב פאגעלמאן , הרב מרלא , הרב שרגא ואני \" ( ס ' \" תולדות ה תמימים\nבארצות הברית \" ע ' 553 :)\nת \" ח על הבשוה \" ט , ויה \" ר שיעלו בקדש הולך והוסיף ואור .\nג\nלפני חג הסוכות , תש \" כ ][\nמענה להת ' משה שלמה סלונים שכתב : \" אינני יודע איך עלי לנהוג ביו \" ט\nשני של גלויות , לתשובתו הק ' אחכה אם עלי לחוג את היום השני \" (\" בית\nמשיח \" גליון 108 ע ' 48 :)\nבאם ( וכיון ) שבא לכאן על דעתי – צ \" ל כמנהגי .\nד\nכ \" ו תשרי , תש \" כ ][\nמענה להנהלת ישיבת תו \" ת המרכזית על מכתבם \" בדבר הקבוצה ביחוד\nללימוד החסידות \" ( מצילום כתי \" ק – קובץ הערות וביאורים אהלי תורה\nחג הסוכות תשע \" ט ע ' 7 :)\n[1 ] במכתבם כתבו : \" בשנה שעברה למדו בזמן ההוספה ספר המאמרים\nתרכ \" ט , וכפי הסדר שהורה כ \" ק אדמו \" ר שליט \" א אשר הענינים\nשאומרים הוא בהענינים שלומדים בזמן ההוספה [ ראה ליקוט מענות\nקודש תשי \" ט מענה קמא ], ולזאת התאוננו אשר להיות שמאמרי אדמו \" ר\nמהר \" ש נ \" ע הם בקיצור , קשה לה ם להכין מה לדבר בזה . ולבד זאת , הנה"],[9200110017,"17\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nמצד הקיצור , אין להם חיות בהלימוד ואין זוכרים כ \" כ את המאמרים .\nולזאת הציעו – רובם – ללמוד בזמן ההוספה מאמרי אדמו \" ר ( מהורש \" ב )\nנ \" ע , ולבחור באיזה המשך שאפשר להשיגו . – אם נכון הדבר .\"?\nמענה כ \" ק אדמו \" ר שליט \" א :\nא ) סימן בעיגול קטע זה , וכתב :(\nכבר אמחז \" ל במקום שלבו חפץ\nב ) על מה שכתבו : \" אם נכון הדבר \"?( – מחק תיבת \" אם \" וסימן - השאלה ,\nוהשאיר את התיבות \" נכון הדבר .\"\n[2 ] במכתבם כתבו : \" בשנה שעברה למדו בכמות לא הרבה , ולזאת אם\nכדאי להגביל להם כמה צריכים ללמוד בכל שבוע .\"?\nכ \" ק אדמו \" ר שליט \" א מחק תיבת \" אם \" וסימן - השאלה , וכתב :\nאין כדאי להגביל להם כמה צריכים ללמוד בכל שבוע ][ כיון שבא בתור\nהתנדבות .\n[3 במכתבם כתבו :]\n\" כמו שהי ' הסדר עד עכשיו , הנה בשעה שהיו אומרים הענינים , לא היו\nמתערבים השומעים , ורק אח \" כ , לפעמים , היו שואלים ובשקו \" ט בהענין\nשדובר . אך להיות שזה הי ' אחרי האמירה , הי ' זאת רק לפעמים . – בנגלה\nסודר אשר גם באמצע שואלים . אך בחסידות לא סידרנו כן , כי חששנו\nשלהיות שישנם עוד תלמידים בהישיבה – יותר מבוגרים – שיודעים יותר\nדא \" ח מתלמידי הקבוצה , לזאת ע \" י השאלות אפשר שהמדברים\nיתבלבלו באמצע אמירתם , וגם אפשר שלפעמים יכנס הויכוח בענין של\nמדות וכו .'\nהצעתינו : א ) טרם שמדברים ברבים , יתאספו ביניהם כל הקבוצה\nויתפלפלו ביניהם בהענינים שצריכים לומר ברבים , כי מצד מיעוט\nהמתפלפלים תהי ' השקו \" ט יותר בגוף הענין . ב ) אחרי השקו \" ט שביניהם ,\nאולי כדאי שיהי ' שקו \" ט גם ברבים , כי אחרי השקו \" ט שביניהם יהי '\nאצלם הענין יותר ברור ובתוקף ולא יתבלבלו . אם ההצעות נכונות\nובאיזה מהם לבחור .\"?\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את מה שכתבו : \" ב ) אחרי השקו \" ט\nשביניהם , אולי כדאי שיהי ' שקו \" ט גם ברבים כו '\", וכתב :\nינסו באופן זה ויחליטו – לאחר ב ' ג ' פעמים בהתאם להתוצאות ."],[9200110018,"18\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nה\nכ \" ח תשרי , תש \" כ ][\nמענה לר ' יוסף מנחם מענדל טענענבוים ( ס ' \" תולדות התמימים בארצות\nהברית \" ע ' 554 :)\n[1 במכתבו כתב : \" רצו \" פ הנני שולח לכ \" ק רשימה מהתלמידים שי ']\nשבאו להלימוד ד \" ופרצת \" בין כסה לעשור משעה 8-7 ( הובטח להם\nמקודם שנמסור שמותיהם לכ \" ק .\")\nמענה כ \" ק אדמו \" ר שליט \" א :\nואזכיר עה \" צ לופרצת בכל השנה הבע \" ל\n[ וראה לקמן מענות : ז , כה , כז .]\n[2 ] במכתבו כתב : \" והנני שולח ח \" י דאלר בעד הפסוק ופרצת , שקניתי\nעבור התלמידים שיחי ' דבעדפארד עוו . בצירוף עם התמימים והאנ \" ש שי '\nהמעות נאסף מהתלמידים שי .\")'(\nכ \" ק אדמו \" ר שליט \" א ציין ( להמזכירות ) שיתנו לו קבלה .\n[3 ] במכתבו כתב : \" קודם חג הסוכות הי ' אסיפת הרמי \" ם מיוחדה ע \" ד\nהשגחה על התלמידים בעת ההתועדויות , הוחלט אשר בכל ההתוועדות\nישגיחו ב ' רמי \" ם מהישיבה , ולדבר עם המנהלים דאהלי תורה שגם א '\nמהרמי \" ם שלהם ישגיח על תלמידיהם , והנני למסור לכ \" ק שמות\nהרמי \" ם שמשתתפים בזה עפ \" י הגורל : בההתועדות שמחת בית השואבה\n– הרב פוקס והרב פאגעלמאן . בההתועדות ליל שמח \" ת – הרב לערנער\nוהרב קאלאדני . בההתועדות שמח \" ת – הרב גורפינקעל והרב מארלא .\nבההתועדות שבת בראשית – הרב גאלדמאן והרב וויינגארטן .\nבההתועדות י \" ט כסלו – הרב פאפאק והרב בזשיסקי . מאהלי תורה\nהשגיח הרב לאזאר שי .\"'\nמענה כ \" ק אדמו \" ר שליט \" א :\nויה \" ר שתכה \" י יבש \" ט בטוב לשמים וטוב לבריות"],[9200110019,"19\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nו\nבדר \" ח מרחשון , תש \" כ ][\nמענה לר ' רפאל ווילשאנסקי – מזכיר \" לשכת ליובאוויטש האירופאית \"\n– על מכתבו ( להמזכיר הר \" נ מינדל ) בו כתב : \" בהזדמנות זאת הנני\nמבקשו ג \" כ להבהיר בפרטיות מה שכתב במאמר \" פלאות הטבע \"\nבה \" שמועסן \" של חודש ניסן תש \" י : \" אשר לפי שיטת איינשטיין אפשר\nאשר הארץ במקומה עומדת והשמש הולך סביבה \". אחד המתרגמים\nשלנו צועק ע \" ז ואומר שאין זה מתאים לגמרי \" ( מצילום כתי \" ק – \" כפר\nחב \" ד \" גליון 947 ע ' 57-58 :)\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות \" מתאים לגמרי \", וסימן\nשני קווים תחת תיבת \" לגמרי \", וכתב :\nוהוא תוצאה מוכרחת משיטת היחסיות\nאלא שאיינשטיין מוסיף בשיטתו\nא ) שמהשקפת עולם מדעית אין תוכן לאימרה תנועה או עמידה – מבלי\nלהוסיף תומ \" י ביחס לפ .'\nב ) לעולם א \" א יהי ' להוכיח מהי המציאות האמתית : א ) הארץ עומדת\nוהשמש סובבתה . ב ) הארץ סובבת את השמש . ג ) שניהם סובבים נקודה\nשביניהם .\nז\nכ \" ד מרחשון , תש \" כ ][\nמענה לר ' יוסף מנחם מענדל טענענבוים שכתב : \" הנני בזה להודיע לכ \" ק\nכי בהתאם לברכת כ \" ק להתל ' לופרצת על כל השנה [ לעיל מענה ה ], אנו\nחושבים להמשיך את הסדר של ופרצת – החל משבוע זו – בכל יום ה ,'\nמשעה 8-7 , בבימד \" ר על 770 , דברתי עם ר \" י שי ' גארדאן ומסכים\nשהבע \" ב ילמדו אז בחדר השני . הרמי \" ם המשתתפים בזה ( בכל שבוע\nישגיחו ב ' רמי \" ם ): הרבנים : גאלדמאן , בערינשטיין , וויינגארטען , לרנר ,\nמארלא , פוקס , פאגעלמאן , ופאפאק שי '. הרב גארפינקעל והרב אלטהויז\nא מרו שגם הם ישתתפו אם יהי ' להם האפשריות . הב ' שרגא שי ' יוביל\nאת הספרים הנחוצים ויחזירם . מובן שגם אני אשתתף בזה בע \" ה \" ( ס '\nתולדות התמימים בארצות הברית \" ע '\" 555-556 :)"],[9200110020,"20\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nויה \" ר שתהי ' א געזונטער און הצלחהדיקער ווינטער בגו \" ר גם יחד\nובפרט בתשב \" ר ובני ישיבות שבהם התחילה עבוה \" ק של הבעש \" ט .\nח\nט ' כסלו , תש \" כ ][\nמענה לר ' מאיר שארף שכתב : \" הנני עתה באבלות \" שלושים \" על אחי\nחיים גרשון ( נפ ' כ \" ה מרחשון ) ובקשתי בשאלתי – אם יכול אני להשתתף\nבסעודת המצוה לאור כ \" א כסלו ? ( כבסעודת מרעים כו '). מסי ' שצ \" א\nביו \" ד אין בידי להכריע \" ( מצילום כתי \" ק – קונטרס ועד הנחות בלה \" ק\nש \" פ וישב תשע \" ד ע ' 13 :)\nבאם יחלק משקה ומזונות וכיו \" ב למתועדים שי ' – הלכה כדברי\nהמקיל .\nט\nכ \" ד כסלו , תש \" כ ][\nמענה להת ' ירחמיאל בנימין הלוי קליין שכתב : \" היות שהנהלת צאגו \" ח\nהציעו לי למלאות מקומו של ליב שי ' ראסקין , דהיינו להביא לפועל\nהפעולות של צאגו \" ח בפועל , ז \" א להשתדל אצל רבנים בעיירות שיסדרו\nאצלם מלוה מלכה וכו ' וכן אודות מחלקת חזרת דא \" ח בביהכנ \" ס , והיות\nשזה יפריע ל י בסדרי הישיבה . לכן הנני שואל אם לקבל הנ \" ל , או להשאר\nבישיבה כמקודם \" ( תשורה שייקביץ ז ' אלול תש \" פ ע ' 14 :)\nתלוי בהנהלת הישיבה , כמובן .\n[ וראה לקמן מענה יג .]\nי\nכ \" ז כסלו , ג ' דחנוכה , תש \" כ ][\nמענה להנהלת \" צעירי אגודת חב \" ד \" שכתבו : \" הננו להודיע שר ' אוריאל\nשי ' צימער הכין את \" תוכן ענינים \" של שיחות כ \" ק אדמו \" ר שליט \" א על\nחומש בראשית , וגם ר ' שמואל שי ' זלמנוב כבר עבר על זה , ויש בדעתנו\nלמסרו לבית הדפוס להתחיל בסידורו , והננו שואלים באיזה צורה"],[9200110021,"21\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nלסדרו , ואולי נכון לסדרו בדוגמת ספר השיחות – תורת שלום \" ( מצילום\nכתי \" ק – נדפס לעיל . המענה מתפרסם בזה לראשונה באדיבות ר ' שניאור\nזלמן יצחק יהושע שי ' חאנין וזכות הרבים תלוי ' בו :)\nיתייעצו ביניהם ויחליטו בטוב .\nבקשר להדפסת ספרי \" לקוטי שיחות \"[ – ראה גם ליקוט מענות קודש\nתשי \" ט מענות קכט , קמ , קמב . תשכ \" ב מענות קנג , קנד .]\nיא\nכסלו , תש \" כ ][\nמענה לר ' שניאור זלמן הלוי דוכמאן על מכתבו בו סיפורים וזכרונות ( ס '\nלשמע אוזן \" ( הוצאת תש \" נ ) ע ' טז :)\"\nת \" ח בעד הר \" ד ובטח יוסיף כהנה וכהנה .\nיב\nאדר \" ח טבת , ו ' דחנוכה , תש \" כ ][\nמענה לר ' יעקב בן ציון יורקוביץ על מכתבו בקשר להולדת הבן\n( מהעתקה . המענה מתפרסם בזה לראשונה באדיבות משפחת הנמען ע \" ה\nוזכות הרבים תלוי ' בהם :)\nת \" ח על הבשו \" ט\nאזכיר עה \" צ\nיג\nה ' טבת , תש \" כ ][\nמענה להת ' ירחמיאל בנימין הלוי קליין שכתב : \" הנני להודיע בהתאם\nלתשובתו של כ \" ק אד \" ש על הצעת צאגו \" ח שאמלא מקומו של ליב שי '\nראסקין \" שתלוי בהנהלת הישיבה \" [ לעיל מענה ט ] הנה דברתי עם הנ \" ל\nוהסכימו לזה . וכפי ההצעה יהי ' העבודה רק לכמה שעות ביום והשאר\nאהי ' אי \" ה בישיבה . והנני לבקש ברכת כ \" ק אד \" ש להנ \" ל \" ( מצילום\nכתי \" ק – תשורה שייקביץ ז ' אלול תש \" פ ע ' 14 :)\nויהא בהצלחה בכה \" ע"],[9200110022,"22\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nיד\nי \" א שבט , תש \" כ ][\nמענה להת ' ירחמיאל בנימין הלוי קליין שכתב \" פרטי כל מהקביעות\nבדא \" ח בישיבת תורה - ודעת :\"\n\" הנני להודיע שהנני לומד שיעור בתניא בישיבת תורה ודעת בכל יום\nחמישי משעה 9.45 ונמשך לפעמים עד שעה 12 . וכהיום יש לי חמשה\nתלמידים , רובם לומדים בקאלעג '. התחלתי מהתחלת השנה ולמדתי\nח \" ב עד פרק י \" א .\nאחרי הקביעות הנני נפגש עם תלמידים אחרים מבני ארץ ישראל ומדרום\nאמריקה ומדבר עמם אודות חסידות , והנני מקוה להקים קביעות\nמיוחדת עבור התלמידים מארץ ישראל שהכרתי אותם כאן , ובכלל\nהכרתי בזמן האחרון הרבה תלמידים ויש לי קשר עמהם שהנני נפגש\nעמם ואדרבה הם מחכים לי בכל יום ה ' אחרי הקביעות ומדברים אודות\nליובאוויטש בכלל .\nבההתועדות דיו \" ד שבט השתתפו כ - 15 תלמידים מישיבה הנ \" ל .\nוהנני לבקש ברכת כ \" ק אדמו \" ר שליט \" א .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – תשורה גארדאן י \" א אלול\nתשע \" ח ע ' טז :)\nויה \" ר שיבש \" ט שנתקיים בכהנ \" ל לימוד ( ודיבור ) המביא לידי מעשה\nבפועל בעניני תומ \" צ .\n[ וראה לקמן מענות לג , לד . ליקוט מענות קודש תשכ \" א מענות עד , עה .]\nטו\nלפני ח ' אדר , תש \" כ ][\nמענה להת ' שמואל לו על מכתבו – בקשר ליום הולדתו העשרים – בו\nכתב : \" ולכן הנני שואל מכ \" ק אדמו \" ר שליט \" א אם הוא ענין להניח\nתפלין דר \" ת לכה \" פ מתחיל מיום הולדת הכ '; ואם אתחיל אני להניחם \"\n( מהעתקת המזכיר . המענה מתפרסם בזה לראשונה באדיבות ר ' פינחס\nשי ' לו וזכות הרבים תלוי ' בו :)\nבטח שומר , בל \" נ חת \" ת .\nונכון וטוב ש אתחיל אני להניחם ]["],[9200110023,"23\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nטז\nי \" א אדר , תש \" כ ][\nמענה לר ' יוסף הלוי וויינבערג שכתב – בקשר לשיעורים בס ' התניא\nשמוסר מדי מוצש \" ק ברדיו : \" בפרק ב ' בתניא , מסופקני אם ללמוד\nההגהה או לאו \" ( קונטרס ועד הנחות בלה \" ק י \" ט כסלו תשע \" ו ע ' 9 :)\nכ \" ק אדמו \" ר שליט \" א מחק את התיבות : \" מסופקני אם \", \" או לא ;\"\nהשאיר את התיבות : \" בפרק ב ' בתניא , ללמוד ההגהה \", וכתב :\n– כיון שאין מקום לדילוגים . ובמקום הקשה – להוסיף שזה יובן במשך\nהלימודים , ובפרט כשיגיעו להגהת פ \" ט דשער היחוה \" א .\nיז\n[ לפני כ \" ב אדר , תש \" כ ( 1 ])\nמענה להחתן הת ' משה לאזאר על מכתבו בקשר לרצונו אשר כ \" ק\nאדמו \" ר שליט \" א יסדר קידושין בחתונתו (\" התקשרות \" גליון תשפב ע '\n10 תשורה זלמנוב אדר \" ח אדר תשע \" ג ע '. 118 . קונטרס ועד הנחות\nבלה \" ק ש \" פ קרח תשע \" ד ע ' 13 :)\nסידור קידושין תלוי ושייך לצד הכלה תי ' ובמילא אל יתערב יותר בזה .\nופשיטא ופשיטא שילך על החתונה והחופה וכו ' בשמחה אמתית ותהא\nבשטומ \" צ .\n[ וראה לקמן מענה יח . ליקוט מענות קודש תשכ \" א מענה פו .]\nיח\n[ לפני כ \" ב אדר , תש \" כ ( 2 ])\nמענה לר ' צבי מאיר שטיינמעץ על מכתבו בקשר להשקלא - וטריא בנוגע\nלסידור קידושין ע \" י כ \" ק אדמו \" ר שליט \" א בעת החופה של בתו העניא\nיהודית עב \" ג הת ' משה לאזאר (\" התקשרות \" גליון תשפב ע ' 11 . תשורה\nזלמנוב אדר \" ח אדר תשע \" ג ע ' 118 . קונטרס ועד הנחות בלה \" ק ש \" פ קרח\nתשע \" ד ע ' 13-14 :)"],[9200110024,"24\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nלאחר בקשת סליחתו – רבות נפלאתי על כל השקו \" ט בהנ \" ל .\nוהרי ברור אמרתי – בעת שנוכחו כולם החו \" כ וכל המחותנים שליט \" א\nשסידור קידושין אינו מעניני וממעשה רב – החתונה שהיתה לפני איזה\nשבועות . וקודם שביררו הנ \" ל הדפיסו בההזמנות \" שתהי ' החופה בחצר\nכו '\" ואח \" כ כשנודע להם הנ \" ל – היתה בשטומ \" צ במק \" א ובסידור\nקידושין ע \" י מומחה וכו '\nוכידוע לכל ותו לא מידי .\nופשיטא ופשיטא – שאין כל מקום לחשדני שרצוני לשלול ח \" ו , או\nאפילו למעט ח \" ו – השתתפות הורים בחתונת יו \" ח שי .'\nנוסף על הענין – שההשתתפות וההשתדלות הנ \" ל יסודתה בתוה \" ק\nתורת חיים . והמדובר בחו \" כ – בעלי מדות ומעלות נעלות ביותר מקור\nלנחת רב בכל הפרטים . וישתדלו – הוא וזוג ' שתליט \" א – בכהנ \" ל מתוך\nשמחה ובריאות טובה וטוב לבב באמת , ותהא החתונה בשטומ \" צ בגו \" ר .\nיט\nכ \" ה אדר , תש \" כ ][\nמענה להרב ישראל יצחק פיעקארסקי ( ריש ס ' \" חקרי הלכות \" ח \" ג .\nאגרות - קודש חי \" ט ע ' רלו - רלח :)\n[1 במכתבו כתב : \" הנה בשו \" ע רבינו ז \" ל בהלכות שבת סימן שנ \" ז סעי ']\nא ' וז \" ל שם חצר שהיא פחותה מד \" א על ד \" א וסמוכה לרה \" ר אין שופכין\nלתוכה מים בשבת בימות החמה שכיון שאין בה ד \" א אין סאתים מים\nשאדם רגיל להשתמש בכל יום ראויים ליבלע בה וה \" ז כאילו שופכן\nלרה \" ר , ואע \" פ שא ין בשפיכה זו שמחצר לרה \" ר איסור של תורה ( אם\n( עיין סימן קנ \" ט ס \" ו ובמ \" א סימן שכ \" ח ס \" ק נ \" ג ובסנהדרין ס \" ז ע \" ב\nודו \" ק וכן משמע בריטב \" א שבבית יוסף ), אינו שופכן לרה \" ר ממש אלא\nברחוק מעט בענין יציאתן לרה \" ר היא מאליהן ואיננה כוח שפיכתו ממש\nאלא כוחו הוא גורם בלבד .)\nעל התיבות : \" בענין יציאתן \", כתב כ \" ק אדמו \" ר שליט \" א :\nכנראה צ \" ל : דיציאתן .\n[2 ] במכתבו כתב : \" הנה בפשוט כוונתו של רבינו ז \" ל לתרץ הא דאמרינן\nבעירובין ד ' פ \" ח דאם שופך מים ברה \" י והם נשפכין הלאה לרה \" ר אין בו\nרק איסור דררבנן , ולכאורה תמוי ' דהרי המים הולכים מכוחו ממש כמו"],[9200110025,"25\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nזורק מרה \" י לרה \" ר ולמה יהי ' מותר מה \" ת . ע \" ז אמר רבינו ז \" ל דהא\nדליכא איסור דאורייתא כששופך ברה \" י היי \" ד כששופך רחוק מרה \" ר\nבאופן שאין המים יוצאין מכוחו ממש . משא \" כ כששופך סמוך לרה \" ר\nויוצאין מיד דומה למגלגל חפץ מרה \" י לרה \" ר .\"\nעל התיבות : \" בפשוט כוונתו של רבינו ז \" ל \", כתב כ \" ק אדמו \" ר שליט \" א :\nבשו \" ע אדה \" ז חאו \" ח ר \" ס שנ \" ז בהמוסגרים ( ל ' רבים ) – כותב דין\nשאינו מובא לא בשו \" ע המחבר ולא בש \" ס עירובין על אתר . והיינו שיש\nבשפיכת מים בחצר – אופן האסור מה \" ת . ואדרבה – דין זה הוא היפך\nמסתימת ל ' שו \" ע המחבר – בכל הדינים שהביאם אדה \" ז בסעיפים א ' -\nה ' ( וגם מסתימת ל ' הש \" ס בכל הסוגיא ). ועד כדי כך – שבכאו \" א\nמחמשת הסעיפים מדייק אדה \" ז להוסיף , וג \" כ במוסגר , הנפק \" מ\nמחידושו בנוגע לסעיף זה .\nמזה פשוט , שכדרכו , יציין המקור לחידושו – לאופן האסור מה \" ת ( ולא\nשממקומות שמציין מוכיח דהאיסור מד \" ס – דע \" ז מציין לאח \" ז לרש \" י\nפ \" ח סע \" א ד \" ה שופכין . הובא בצ \" צ משניות ( לה , ע \" ג ) כמצויין עה \" ג .(\nדמזה ג \" כ קשה על חידוש אדה \" ז הנ \" ל . וכמרומז בסגנון הצ \" צ שם : י \" ל\nעוד בע \" א עפמש \" כ רש \" י כו ' מיהו אדמ \" ו נ \" ע כו .)'\n[3 ] במכתבו כתב : \" רק מה שציין בצדו עי ' ש \" ס סנהדרין ד ' ס \" ז שם לא\nנמצא כלל מענין זה .\"\nעל התיבות : \" לא נמצא כלל מענין זה \", כתב כ \" ק אדמו \" ר שליט \" א :\nבהקדים : 1 ) שבציון זה דוקא הוסיף אדה \" ז ודו \" ק . 2 ) ביחוד בהל ' שבת\nשרבו גזירות חז \" ל – לכאורה לא מצינו דבשינוי קל ביותר מאופן האסור\nמה \" ת – יהי ' מותר לכתחילה וכמו שהוא ע \" פ חידוש אדה \" ז הנ \" ל .,\nוהנה בסנה ' ( סז , ב ): הל ' כשפים כהל ' שבת יש מהן בסקילה כו ' פטור\nאבל אסור כו ' מותר לכתחילה . ולכאורה מאי קמ \" ל – הרי כו \" כ איסורין\nשיש בהם כנ \" ל . וכמו בע \" ז : דמותר לקרות בספריהם לכתחילה – באם\nלהתלמד , ואדרבה תנאי הוא בסנהדרין .\nועכצ \" ל דהרבותא היא דאותה מעשה ממש יש שהוא בסקילה כו ' או\nמותר לכתחילה . ומביא מהל ' כשפים דמיברו להו עגלא תלתא ממש –\nלכתחילה . ומתורץ ב ' דיוקים הנ \" ל . כן מובן מה שהוזקק אדה \" ז לכל\nהמקורות : סי ' קנט ס \" ז ( ודלא כנדפס ס \" ו ) – ענין דשפיכת מים כנדו \" ד\nחשיב כחו ממש . מג \" א כו ' – דאפ \" ל בשבת אב מלאכה , אף דלכאורה\nהוא לא עביד מידי בעת המלאכת איסור . סנה ' – לתרץ דיוק השני הנ \" ל ."],[9200110026,"26\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n[4 ] במכתבו כתב : \" ולפי דעתי הוא טעות הדפוס וצ \" ל ד ' ע \" ז ע \" ב דאמרינן\nהתם גבי אשקיל אחברי ' בידקא דמיא דמחלקינן בין כח ראשון לכוח שני\nופירש \" י בפי ' דיש חילוק בין קרוב לרחוק עיי \" ש .\"\nעל התיבות : \" דאמרינן התם \", כתב כ \" ק אדמו \" ר שליט \" א :\nאת \" ל שצ \" ל סנה ' עז , ב , לא נ \" ל שכוונתו לאשקיל אחברי ' כו ': א ) דא \" כ\nהי ' מציין לרש \" י שם , וכרגיל במ \" מ השו \" ע שלו . ב ) הרי ברש \" י מדייק\nשהשפה מדרון משא \" כ בנדו \" ד . ולפענ \" ד – באם הגירסא עז , ב הכוונה\nל \" הכא במאי עסקינן בשותת \" – דמוכח מזה דבניתז בכח – מקודש .\nומיושב קצת מש \" כ ע \" ז ודו \" ק .\n[5 ] במכתבו כתב : \" וגם מה שציין רבינו ז \" ל על הא דבעינן שיהי ' רחוק\nמרה \" ר שהוא מהריטב \" א בעניי לא מצאתי .\"\nעל התיבות : \" שהוא מהריטב \" א \", כתב כ \" ק אדמו \" ר שליט \" א :\nז \" ל הריטב \" א שבב \" י : וכי זריק התם ( בחצר ) ה \" ה שופך מרה \" י\nלכרמלית או לר \" ה באם נפחת מג )'( – דמדחלקם לשנים – משמע\nדחלוקין באיסורם . ובנפחת מג ' – ה \" ז הוצאה מרה \" י לר \" ה ממש .\n[6 ] במכתבו כתב : \" והנה מלשון הר ' יונתן המובא ביתה יוסף רסי ' שנ \" ז\nנראה בעליל דאפילו במקום רחוק מעט מרה \" ר נמי לא סגי רק צריך\nשינוחו מעט בטרם יצאו החוצה . ונראה שדעתו ז \" ל כדעת הרמ \" ה\nסנהדרין ד ' ע \" ז בהא דמפליג גבי אשקיל בידקא דמיא בין כוח א ' לב ', וכ '\nשם דהמחוור ש בפירושים דכוח ב ' היינו שנפסק מעט כהא דאמרינן\nבהבית ועלי ' ד ' קי \" ז דפסקו מיא והדר נפלו ל \" ח גירי דילי ', והמפרשים\nדיש חילוק בין מקום קרוב לרחוק דחה שם . ולדבריו צ \" ל כפי ' ה \" ר יונתן\nדכל ההיתרים דכאן אינם רק כשנחו מעט בטרם יצאו לרה \" ר . אך מרבינו\nז \" ל משמע דנקט העיקר החילוק בין קרוב לרחוק . ויש להביא ראי '\nלרבינו ז \" ל דיש חילוק בין קרוב לרחוק דרחוק הוי כוח שני ולכן מותר\nמה \" ת מש \" ס חולין ד ' ק \" ז ע \" ב גבי אריתא דדלאי דאי לא מקריב ידי '\nלגבי דוולא ל \" ח כוח השופך הרי דהריחוק משוי ' לי כוח שני , אח \" כ\nמצאתי ראי ' זו בספר שיח השדה .\"\nעל התיבות : \" ויש להביא ראי ' לרבינו ז \" ל \", כתב כ \" ק אדמו \" ר שליט \" א :\nהרי זהו הציון לסקנ \" ט ס \" ז . – ובציונו לשו \" ע ולא לש \" ס – שולל הפי '\nהראשון דבתוד \" ה דלא שם ."],[9200110027,"27\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nכ\nאדר , תש \" כ ][\nמענה להת ' שרגא פייביש וואגעל שכתב :\n\" ביום ג ' פ ' תרומה הלכתי לישיבה - יוניווערסיטי \" היי סקול \". למדתי עם\nהרב . . שיחי ' עוד בשער היחוד והאמונה וגם שוחחנו אודות ענינים של\nחינוך . חזרתי ג \" כ שיחות מכ \" ק אד \" ש . אחר כך למדתי עם שלשה\nבחורים באגרת התשובה . אמרתי להם שכיון שהם לומדים תניא עלה\nבדעתי שיזכו ליכ נס לכ \" ק אד \" ש . הם רוצים בכל תוקף .\nביום ג ' פ ' תצוה הלכתי שמה וחזרתי להרב . . השיחות של כ \" ק אד \" ש של\nיום ראשון קודם ה \" סטודענטס \". נהנה עד מאד מזה . אבל במשך הזמן\nנתעורר שאלה שלא יכלתי לקבל דעתו עלי '. והוא : בין הדיבורים אמרתי\nשכל דבר גשמי בעולם הזה הוא מורכב מארבע יסודות , ואין יותר מארבע\nיסודות כמבואר בחסידות . ואמר שכן מבואר ברמב \" ם אבל היום מוסכם\nמכל Science שיש תשעים וששה יסודות , ובכל אופן , הרמב \" ם אמר זה\nע \" פ השיטות בזמנו ואין זה מינות לומר שהרמב \" ם טעה . עניתי לו שכיון\nשזה נזכר בהלכות של הרמב \" ם , קשה לומר שזה טעות .\nהרב . . ענה שיש לו ראיות על זה , והם :\nא ) מה שפוסק הרמב \" ם בהלכות איסורי ביאה פרק ה ' הלכה ד ' אודות\nענין Tubes Phallopian , מה שמוזכר ברמב \" ם \" למעלה \" ועכשיו מוסכם\nב \" Biology שהם שוים . ופשוט , טען , שזה ראי ' שהרמב \" ם לא ידע מזה .\"\nב ) בספר המצות של הרמב \" ם מצות ל \" ת קע \" ט – בשיטה של הרמב \" ם\nאם הוזכר הלאו יותר מפעם א ' ולא הוסיף אין לוקין אלא אחת . ומבואר\nבין דבריו בענין צרעה לוקה שש . ואמר – שהרמב \" ם אמר שזה שיטתו\nבענין Spontaneous generation, ועכשיו ב - Biology מוסכם שזה אינו\nאמת .\nעניתי לו שאיני יודע מזה כלל , ואם ירצה יוכל לכתוב שאלות אלו לכ \" ק\nאד \" ש . לא רצה ואמרתי לו שאני אשאל את זה והסכים שאשאל מכ \" ק\nאד \" ש דבר א ' והוא – אם ענין זה של ד ' יסודות חלק מן התורה ואם אין\nמאמין בו – מה דינו .\nחזרתי קצת מהשיחות אצל הבחורים וגם למדתי עם ארבעה בחורים\nאגרת התשובה .\""],[9200110028,"28\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – תשורה גראסבוים\nאדר \" ח כסלו תשע \" ט ע ' 3-5. אגרות - קודש חי \" ט ע ' רלט - רמ . צדי \" ק\nלמלך חוברת ז ע ' 214-216 :)\n[1 ] על מה שכתב : \" בין הדיבורים אמרתי שכל דבר גשמי בעולם הזה הוא\nמורכב מארבע יסודות \", כתב :\nיסודות ][ שבדברי רז \" ל אין פי ' שאי אפשר לחלקם ולפוצצם , אלא שהם\nהחלקים \" היסודים \" שכל דבר מורכב מהם .\nואין זה שייך למספר של elements אשר ב chemistry .\nויש מפרשים קדמונים בדרז \" ל \" יסודות \" – שהכוונה לתכונות שלהם :\nקור ולח , חם ויבש וכו '. ואכ \" מ . ולכן נק ' במדרש טבעים .\n[2 ] על מה שכתב : \" ואמר שכן מבואר ברמב \" ם אבל היום מוסכם מכל\nScience שיש תשעים וששה יסודות \" – סימן בעיגול תיבת \" מוסכם ,\"\nוכתב :\nזה הי ' מוסכם לפני 50 שנה אבל עתה \" מוסכם \", – שכל אחד מהם\nמורכב מכמה חלקים . וכמה מיני חלקים ישנם – אין יודעים עדיין כלל .\nויש משערים שהם ארבעה יסודות : positive, antimatter, matter,\nnegative\nוסימן תיבת \" ארבעה \" בשלשה חיצים .\n[3 על מה שכתב : \" מה שפוסק הרמב \" ם בהלכות איסורי ביאה כו ,\"']\nכתב :\n– לאחרי החתונה יעסוק בהל ' אלו .\n[4 ] על מה שכתב : \" ואמר שהרמב \" ם אמר שזה שיטתו בענין\ngeneration Spontaneous כתב :\",\nוזוהי \" שיטת \" התורה והובאה בכ \" מ מתנאים ( תו \" כ שמיני יא , מד\nועוד ) ואמוראים ( שבת קז , ב ), וזהו יסוד לכמה הלכות\n[5] על מה שכתב : \" ועכשיו ב - Biology מוסכם שזה אינו אמת \", כתב :\n– כל ההסכמה היא בדרך השערה וז \" ל \" כיון שבמקום העפוש מצאו\n( ע \" י microscope ביצים קטנים , י \" ל שמהם נתהוו מינים אלו .) ואין\nראי ' אשר נתהוו מן העפוש , כדרז \" ל , וא \" כ אין לומר אשר חלוקים הם\nמשאר בע \" ח ."],[9200110029,"29\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n[6 על מה שכתב : \" אם ענין זה של ד ' יסודות חלק מן התורה \"] – סימן\nבעיגול תיבת \" התורה \", וכתב :\nכי נמצא בבמדבר רבה פי \" ד , יב . בזוהר במקומות רבו מלספור ועוד .\nכא\nאור לז ' ניסן , תש \" כ ][\nמענה להת ' שמואל פסח באגאמילסקי שכתב : \" בשבוע העברה שלחתי\nלכל איי הקאריביען שבקרתי בקיץ העבר , שטרי הרשאה על שמי , עבור\nמכירת חמץ . . אבל נתעוררתי בשאלה , כי יש אצלי ספק הקרוב לודאי\nשכמה יאכלו ר \" ל חמץ בפסח , האם זה מבטל המכירה למפרע . בשדה\nחמד מערכת חו \" מ כלל ט ' ס ימן ל \" ה כותב שדעתו , וכן דעת המהר \" ם\nשיק , שאם מכר חמצו – שמכר קודם הפסח – בחוה \" פ לנכרי , אזי נתבטל\nהמכירה למפרע . ושאלתי זה לכמה רבנים , וחוו \" ד כדלהלן . .\" ( קובץ\nשאלות פירושים וביאורים \" חוברת ב ע '\" 20-23. אגרות - קודש חי \" ט ע '\nרמו - רמז :)\nפשוט שצריך לסדר שם מכירת חמץ .\nהתועלת – ודאית . נוסף על העיקר ( הענין דב \" י וב \" י ) גם ההתעוררות\nוזכרון ע \" ד איסור חמץ , מנהג אבות וכו ' וכו .'\nהחשש – דשמא יטול מן החמץ באמצע חה \" פ וכו :' 1 ) פשיטא שכמה\nמהנ \" ל לא יעשו הנ \" ל . 2 ) גם בהנוגע להנחשדים – ודאי כודאית התיקון\n– לא הוי . 3 ) אפילו בהנוגע להנוטל – לכמה דעות לא בטלה המכירה [ כן\nמשמע דעת אדה \" ז סתמ \" ח סע ' יג - יד ], כ \" א גוזל הוא מה שנוטל ותו\nל \" מ . 4 ) אפילו להאומר דבטלה המכירה – י \" ל דזהו מכאן ולהבא – וניצל\nמאיסור ב \" י וב \" י עד שעה זו . ולאו שאין בו מעשה – לכמה דיעות אין\nלוקין עליו אף בעשה מעשה . 5 ) אפילו למ \" ד דלוקין עליו – צ \" ע מה\nמכריע : כל ח ' ימי חה \" פ באיסור דב \" י וב \" י אלא באופן שאין לוקין – או\nזמן יותר קצר אלא שרגע אחד – רגע ביטל הקני ' – קאי בלאו דלוקין\nעליו . 6 ) אפי ' את \" ל דבטלה המכירה למפרע – הנה אדרבה לפי זה י \" ל\nשאין כאן מעשה ואין לוקין ע \" ז , כי מעולם לא הייתה מכירה , ואין מקום\nלקני ' בתוך חה \" פ .\n___\nיברר אצל הרבנים דשקו \" ט עמהם : הַאפשר להוסיף והתועלת בהוספה\nבשטר הנ \" ל : א ) דישראל המוכר או בא כחו יהי ' באם ירצה – מורשה"],[9200110030,"30\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nמהנכרי הקונה ושלא עמלק \" פ , למכור בשבילו או לתת במתנה\nמהענינים הנמכרים .\nאו ב ) שמוכר לו כו ' עד למדידה בעחה \" פ , ולבד מה שילקח מהדברים\nבשטר גם בימים שלאח \" ז .\nומובן שיזהירו את המוכרים שאסור להם לעשות הנ \" ל , אבל גם אם\nיעברו על איסור זה – אין כאן חשש ביטול מכירה כיון דאדעתא דהכי\nכו .'\nוראה לקמן מענות :[ כג , כד .]\nכב\nז ' ניסן , תש \" כ ][\nמענה לר ' יוסף הלוי וויינבערג שכתב – בקשר לשיעורים בס ' התניא\nשמוסר מדי מוצש \" ק ברדיו : \" במה שהואיל כ \" ק שליט \" א לרשום ולבאר\nהענין המובא בסוף פרק ב ' מהזוהר והזו \" ח שהעיקר תלוי שיקדש וכו '\nשהכוונה בזה להוסיף הדגשה בזה שהנשמה היא וכו ' ממעל , ואף\nהחילוקי מדריגות הם מצד ההשתל ' שכ \" ז למע ' מעוה \" ז , והמטה\n( שהאו \" א בכלל המטה ) אין פועל בזה עד שמ \" ש בזוהר וכו ', הנה אשאל\nבזה אם אינני טועה בזה שאני חושב שהמבואר בפרק י \" ח שהמשכת נפש\nדקדושה הוא לכאו \" א כפי מדרגתו וכפי מעשיו ( ורק לפעמים ממשיכים\nוכו ' מפני שהיו בעמקי וכו ' ואין מוציאים מהם בע \" כ לכן מזמינים להם\nוכו ' כדי שיוציאו ברצונם הנשמה , אבל על פי סדר הנה הוא לכאו \" א כפי\nמדרגתו וכו ') זה אין נקרא שהמטה אין פועל בהנשמה כי המטה אין פועל\nבהנשמה עצמה , כי אם שכפי מדריגתו וכו ' לפ \" ע כזה נמשך בזיווגו\nמדריגת נשמה ( או שבאם הוא במדיגה יותר גדולה הנשמה שממשיך\nעוברת רק דרך מעבר ההשתל ' ולא דרך התלבשות וכו '), משא \" כ אם\nהיינו מפרשים הזוהר והז \" ח שתלוי בקידוש בשעת וכו ' דוקא שקאי על\nהנשמה , אז הי ' מקום לחשוב שהמטה דהיינו איכות פעולת הזיווג פועל\nעל הנשמה עצמה שאם אינו מקדש וכו ' אז פועל זה על הנשמה , ואם\nמקדש וכו '\" ( מצילום כתי \" ק ; קובץ הערות וביאורים אהלי תורה ש \" פ\nמשפטים תשע \" א ( גליון א ' יב ) ע ' 47-51 :)\n[1 ] על מה שכתב : \" שהמבואר בפרק י \" ח שהמשכת נפש דקדושה הוא\nלכאו \" א כפי מדרגתו וכפי מעשיו \", כתב :\nבביאור תניא שבקופיר – להרה \" ח גרונם ע \" ה פי :'"],[9200110031,"31\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nשהמבואר בפרק י \" ח שהמשכת נפש דקדושה הוא לכאו \" א כפי מדרגתו ][\nשורש נשמתו וכפי מעשיו ][ שיזכה אח \" כ ( במשך ימי חייו ) להמשיך כו .'\n[2 על כללות המכתב , כתב :]\nדרך אגב בביאור הנ \" ל מפרש בספ \" ב כהקס \" ד שלו – אבל לא נ \" ל כלל\nוכלל דא \" כ הול \" ל בתניא שם ומ \" ש בזהר וז \" ח דבני ע \" ה ממשיכים נפש\nדסט \" א ונפהב היינו כו ' והענין \" שהעיקר כו '\" אינו שייך לכאן\nועיקר הראי ' והקושיא – ע \" פ פי ' זה – נרמז בתיבת \" כו !!\"'\nכג\nח ' ניסן , תש \" כ ][\nמענה להת ' שמואל פסח באגאמילסקי שכתב – בהמשך להמענה שקיבל\n( לעיל מענה כא ): \" דברתי עם כמה מהרבנים המתירים ואינם רואים\nאפשריות וגם נחיצות להוציא לפועל זה ( דלכאורה , בפרט אופן הב ', הוי\nגריעותא לפי שיטתם ). הרב . . אמר , שטוב לסדר ענין הב ', וגם בלי\nידיעתם כיון שנתנו לי כח הרשאה למכור חמצם כפי רצוני ( כמפורט\nבהשטר - הרשאה ). והרב . . אמר שאין לזה תקנה ואין למכור החמץ . והנני\nשואל עצת כ \" ק אד \" ש איך להתנהג בפועל בנוגע להצעת כ \" ק אד \" ש \"\nקובץ \" שאלות פירושים וביאורים \" חוברת ב ע '( 22-23 :)\n[1 על התיבות : \" אפשריות . . נחיצות . . תקנה \", כתב :]\n?\n[2 על מה שכתב : \" והנני שואל עצת כ \" ק אד \" ש איך להתנהג בפועל ,\"]\nכתב :\nצ \" ל פס \" ד של רב עוסק בהוראה למעשה בפועל\nכד\nח ' ניסן , תש \" כ ][\nמענה להת ' שמואל פסח באגאמילסקי שהכניס דוגמא משטר - ההרשאה\nלמכירת חמץ ששלח לקהילות בנ \" י שבאיים הקריביים ( קובץ \" שאלות\nפירושים וביאורים \" חוברת א ע ' 6 :)"],[9200110032,"32\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nציינתי רק חלק מהמקומות הצריכים תיקון לדעתי\nמובן שכיון שכבר שלח הנ \" ל – אין כדאי לבלבל המקבל ולשלוח אחר\nבמקומו\nיבקש מרבני אנ \" ש נוסח שטר הרשאה וכו ' שהשתמשו בו מדור לדור\n[ הגהות כ \" ק אדמו \" ר שליט \" א על נוסח שטר - ההרשאה – ראה קובץ\nשאלות פירושים וביאורים \" שם ע '\" 7-8 .]\nכה\nיום הבהיר י \" א ניסן , תש \" כ ][\nמענה לר ' יוסף מנחם מענדל טענענבוים שכתב : \" הנני בזה להודיע לכ \" ק\nכי בהתאם להוראת כ \" ק סדרנו התועדויות – מסבות יו \" ט – עבור\nהתלמידים שי ' ביום ב ' דחג בשעה 3 בשכונות . . כן הנני להודיע לכ \" ק כי\nנתחלק זיתי שמורה לכל התלמידים שאין להם זיתי שמורה בביתם , גם\nלכל המורים אנגלית דעלעמענטרי . . גם הנני שולח רשימה מהתלמידים\nשי ' שבאו להלימוד דופרצת בכל יום ה ' משעה 8-7 במשך החורף ,\nהרמי \" ם שהשגיחו על הלימוד הנ \" ל . .\" ( ס ' \" תולדות התמימים בארצות\nהברית \" ע ' 557-558 :)\nהזכרתים עה \" צ\nכו\nכ \" ה ניסן , תש \" כ ][\nמענה לר ' יוסף מנחם מענדל טענענבוים שכתב :\n\" הנני בזה למסור לכ \" ק דו \" ח פרטי מההתועדויות דמסבות יום טוב עבור\nהתלמידים הצעירים ביום ב ' דחג ( בכללות הודעתי תיכף ע \" י הרב חדקוב\nשי '), בכלל הנה תודה לה ' שהי ' בהצלחה הן מכמות המשתתפים והעיקר\nמהסדר והאופן של המסבות שהתלמידים וגם ההורים שהיו נוכחים היו\nשבעי רצון במאד . .\nביום ה ' א ' דחול המועד , הי ' התועדות עבור תלמידי המתיבתא , בבית\nמדרש כ \" ק אדמו \" ר שליט \" א , והר ' יואל כהן שי ' חזר לפניהם השיחות\nקודש מליל פסח ."],[9200110033,"33\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nליל ו ' הי ' התועדות הרמי \" ם והמשפיעים שי ' ( כדי שתהי ' באופן פרטי הי '\nהתועדות בחדרו של הרש \" ל שי ') השתתפו כמעט כל הרמי \" ם והמשפיעים\nהרי \" כ והרד \" ר שי ', הרש \" ל שי ' ישב משעה 11-9 . .\nלאחר שהרש \" ל שי ' הלך נשארו עוד כמה מהרמי \" ם והמשפיעים עד שעה\n12:30 בערך והוחלט לקבוע – לע \" ע – בכל ב ' שבועות בליל ג ' שיעור לימוד\nמכל הרמי \" ם והמשפיעים כדי לפעול עי \" ז קירוב הדעות והלבבות בין\nהרמי \" ם – אשר לע \" ע חסר זאת – . הלימוד יהי ' המאמרים של כ \" ק\nאדמו \" ר שליט \" א והלכות תלמוד תורה בשו \" ע אדמה \" ז , אתמול כבר היה\nהתחלה טובה בזה – משעה 9 עד שעה 11 בערך – הלומד היה הר \" י כהן\nשי ', בכל פעם ילמוד אחר ויתן השי \" ת בהצלחה עם תוצאות טובות .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( ס ' \" תולדות התמימים בארצות הברית \" ע '\n558-559 :)\nת \" ח ת \" ח על הבשו \" ט .\nכז\nח ' אייר , תש \" כ ][\nמענה לר ' יוסף מנחם מענדל טענענבוים שכתב :\nהנני בזה להודיע לכ \" ק ע \" ד הבחינה דאתמול ע \" י הרבנים טעלושקין ,\"\nביק , ויצחק בונין שי ' ( גם הרב סימפסאן שי ' הי ' נוכח בכמה מחלקות ,)\nת \" ל שהי ' בהצלחה והבוחנים היו שבעים רצון מאד , הן מידיעתם בכלל\nוהן מאופן ידיעתם בפנים . .\nדרך אגב הנני למסור לכ \" ק , כי בשיחה עם הרב טעלושקין שי ' שיבח לפני\nמאד את לימוד התניא ע \" י הראדיא , הן את עצם הלימוד והן את אופן\nהלימוד , ואמר \" ביי מיר אין שול קוויקט מען זיך מיט דעם \" ואשר כדאי\nלהוציא אח \" כ את הלימוד הזה בדפוס .\nביום ד ' הי ' אסעמבלי מכל התלמידים ( בהדזשים של הישיבה ) וחלקנו\nפרסים – חפצים שונים – לי \" ז תלמידים שהצטיינו בהתמדתם בהלימוד\nשל ופרצת בכל יום ה ' במשך ב ' חדשים האחרונים של ימי החורף . .\nונאמתי לפניהם ע \" ד לימוד הנ \" ל ואשר עכשיו בימי הקיץ בנקל יותר\nלבוא להלימוד וכל או \" א ישתדל להשתתף בזה ואשר ע \" י הופרצת\nדכאו \" א נזכה שהפורץ יעלה לפנינו כברכת כ \" ק בכמה ש \" ק .\""],[9200110034,"34\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nמענה כ \" ק אדמו \" ר שליט \" א ( ס ' \" תולדות התמימים בארצות הברית \" ע '\n560 :)\nת \" ח ת \" ח על הבשו \" ט\nכח\nי \" א אייר , תש \" כ ][\nמענה להת ' ירחמיאל בנימין הלוי קליין שכתב ע \" ד השידוך שהוצע לו ,\nוכתב : \" והנני לשאול אם להתענין בזה \" ( קובץ \" מיין גענעראל \" ח \" א ע '\n15 :)\nכ \" ק אדמו \" ר שליט \" א מחק את התיבות \" והנני לשאול אם \", וסימן בחץ\nאת התיבות \" להתענין בזה .\"\nכט\nל \" ג בעומר , תש \" כ ][\nמענה לר ' יוסף הלוי וויינבערג על מכתבו – בקשר לשיעורים בס ' התניא\nשמוסר מדי מוצש \" ק ברדיו ( מצילום כתי \" ק – תשורה וויינבערג ל \" ג\nבעומר תשע \" ט ע ' 47-48 :)\n[1 ] במכתבו כתב : \" במה שהואיל כ \" ק שליט \" א לרשום – על הענין שנכתב\nבביאור הדברים בתניא ובצירופי אותיות וכו ' בדיו על הספר וכו '\nשהכוונה אשר כשהאותיות נכתבים כדין בדיו על הקלף אז האותיות\nעצמם הם רצונו וחכמתו ית ' – \" ידונו בהועד אם כן הוא הפירוש \", הנה\nמאחר שכ \" ק הואיל להעיר בזה כמובן אשר לא נבאר כן בפועל , אמנם\nרציתי לשאול אם כוונת כ \" ק לדון אם הענין הוא כן אשר גשם האותיות\nעצמם הם חכמתו ורצונו וכו ', או שהכוונה הוא אם כאן בתניא הפירוש\nכן .\"?\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות : \" ידונו בהועד אם כן\nהוא \", וסימן בעיגול את מה שכתבו : \" אם הענין הוא כן אשר גשם\nהאותיות עצמם הם חכמתו ורצונו וכו ', או שהכוונה הוא אם כאן בתניא\nהפירוש כן \", וציין : (1 )\n[2 ] במכתבו כתב : \" אגב זה משך זמן אשר מפיסקא הנ \" ל קשה לי במה\nשמבארים תמיד בתניא פרק ה ', בענין מקיף ומוקף , אשר מה שהשכל"],[9200110035,"35\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nמקיף את המושכל ( ובהנמשל את דבר ד ') הוא כאשר כבר מבינו כאומרו\nשהשיגו והשכילו , ומה שהשכל מלובש בהמושכל הוא בשעה שמשתדל\nלהשיגו כאומרו בשעה שמשיגו ותופסו בשכלו ( וכן כתבתי במה שהכנסתי\nלכ \" ק אד \" ש על פרק ה ' שם ) וכן מבואר בביאור על התניא מהרה \" ח ר '\nאברהם אלי ', וכמדומני שראיתי כן במאמר של כ \" ק אדמו \" ר מהר \" ש\nזי \" ע , ולכאורה בהפיסקא הנ \" ל מהרשימה מבואר להיפך כי אומר שם\n\" ואשר בשכלו יקיף א ת דבר ד ,' ואח \" כ הנה שכלו מוקף מדבר ד '\", אשר\nלפי זה בהמשל הנה בתחלה השכל מקיף את המושכל , ואח \" כ השכל\nמלובש בהמושכל .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nסדר הבנת שכל – בתחלה תופס כללות הסברה והשכל , ואז [ השכל מקיף\nאת המושכל , ואח \" כ ] מתחיל לפַרט הכלל ע \" י שקו \" ט וכו ', ואז [ השכל\nמלובש בהמושכל ] וכאשר גמר זה כבר מבינו כאומרו שהשיגו והשכילו ][\nאז השכל מקיף את המושכל ][\n___\nולהעיר ג \" כ מהגהות הצ \" צ ( הנדפסות ) על הנ \" ל .\nל\nלאחר ל \" ג בעומר , תש \" כ ][\nמענה להת ' אברהם ארי ' סטאון שכתב ע \" ד מסיבת - הסיום שעורכים\nעבור הילדים שהשתתפו במשך השנה ב \" מיטוואך שעה \" ( תשורה סטאון\nכ \" ה אדר תשס \" א ע ' 23 :)\nאזכיר עה \" צ\nבטח יזכירו ע \" ד הבעש \" ט ז \" ל\nוע \" ד המדובר בל \" ג בעומר ."],[9200110036,"36\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nלא\nלאחר ל \" ג בעומר , תש \" כ ][\nמענה להת ' אברהם ארי ' סטאון על דו \" ח ממסיבת - הסיום של הילדים\nשהשתתפו במשך השנה ב \" מיטוואך שעה \", בו כתב : \" אנו חושבים שזה\nהי ' קידוש השם גדול \" ( תשורה סטאון כ \" ה אדר תשס \" א ע ' 23 :)\nכ \" ק אדמו \" ר שליט \" א סימן בחץ את התיבות : \" אנו חושבים שזה הי '\nקידוש השם גדול \", וכתב :\nת \" ח על הבשו \" ט הנ \" ל .\nלב\nי \" ט אייר , תש \" כ ][\nמענה לר ' דובער בוימגארטען (\" כפר חב \" ד \" גליון 888 ע ' 128. אגרות -\nק ודש חי \" ט ע ' שכב :)\n[1 ] במכתבו כתב : \" ממשיך הלימודים עם . . ובאים עוד איזה אנשים\nללמוד . . ולומדים אנו כעת שער היחוד והאמונה . והקשה הוא למה\nשבתחלת פרק ה ' מביא המד רש שבתחלה עלה במחשבה לברוא את\nהעולם במדת הדין וראה שאין העולם מתקיים ושיתף עמו מדת\nהרחמים , הרי כמבואר למעלה בפרק ד ' אדרבה הי ' מדת החסד מתחלה\nוזהו העיקר ורק מדת הגבורה היא הטפל , כמו שאומר שכשם שאי אפשר\nלהבין מדת חסדו והתפשטותו כך גם אי אפשר להבין מדת גבורתו ו כו .'\nובפרט שהרי גם יש מדרש להיפך שבתחלה עלה במחשבה במדה \" ר וראה\nשאין העולם מתקיים ושיתף עמו מדה \" ד ומד ' זה הי ' יותר נכון .\nוהתדברתי עם מענדל דריזין ועוד שהי ' להם שאלה כזו בלמדם\nבמקומותיהם ואינם יודעים לפתור , ואולי יואיל כ \" ק אד \" ש לבאר .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n( א ) על מה שכתב : \" למה שבתחלת פרק ה ' מביא המ \" ד שבתחלה עלה\nבמחשבה לברוא את העולם במדת הדין וראה שאין העולם מתקיים\nושיתף עמו מדת הרחמים \", כתב :\nכי צדיקים דומים לבוראם , וגם הקב \" ה עשה כן וכתב : בראשית ברא\nאלקים גו .' וכ \" ה בפירש \" י [ בדרך רמז ובדא \" פ : ר \" פ ה ' – העולם שנברא\nבה '], וראה זח \" ג לט , א ."],[9200110037,"37\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n( ב ) על מה שכתב : \" הרי כמבואר למעלה בפרק ד ' אדרבה הי ' מדת החסד\nמתחלה וזהו העיקר ורק מדת הגבורה היא הטפל , כמו שאומר שכשם\nשאי אפשר להבין מדת חסדו והתפשטותו כך גם אי אפשר להבין מדת\nגבורתו וכו '\", כתב :\nשם אינו מדבר בקדימה בבריאה , כ \" א בקדימה בהבנת האדם – שפשוט\nיותר בהבנה שא \" א להבין ההתפשטות דלמע ', מאשר שא \" א להבין\nהצמצום .\nהערה : אולי ניבאו ול \" י מה ניבאו – כי מבואר לפעמים ( ע \" ד הנ \" ל ) כי\nתחלת ז ' ימי הבנין – מדת החסד , כי עצם וסיבת הבריאה וכן סיבת\nהצמצום – מפני שטבע הטוב להיטיב וכו ' וגם רוצה שיהי ' בערך\nהנבראים ולכן מצמצם כו ', אבל זהו סיבת הענין ולא שבורא בזה וק \" ל .\n( ג ) על מה שכתב : \" ובפרט שהרי גם יש מדרש להיפך שבתחלה עלה\nבמחשבה במדה \" ר וראה שאין העולם מתקיים ושיתף עמו מדה \" ד ומד '\nזה הי ' יותר נכון \", כתב :\nאינו מדרש להיפך ][ . יש מדרש הכולל ב ' האפשריות וכמו ב \" ר ( ספי \" ב :)\nאם בורא במדה \" ר כו ' אם בורא במדה \" ד כו ' אבל לא להיפך .\n[2 ] במכתבו כתב : \" למדתי חסידות איתו והתחלנו תניא , ותחילה ניסיתי\nשרש מצות התפילה וכו ' ולא מצא חן בעיניו כי רצה \" פראקטישע\nחסידות \" עד \" מ המאמר אין הקב \" ה בא בטרוניא וזה לא מצא חן בעיניו\n. . וזה חשבתי שתניא יהי ' יותר טוב והתחלתי ההקדמה ותיכף נתעורר\nלשאול כמה שאלו ת ונראה שכבר נכנס בו הסם והרעל של . . ות \" ל שהיום\nבעת דפדפי בתניא הוצאות אונגארן מקאליש שבסופו יש קצת תולדות\nמצאתי שם בשבילו אוצר בלום ולא ממקור ליובאוויטש כ \" א אונגאר ;\nבהפאראד של היום עזר הוא וכן אחיו למרות שהי ' איסור מההנהלה ד .\nלהשתתף בפאראד .\".\nמענה כ \" ק אדמו \" ר שליט \" א :\n( א ) סימן קו תחת שם המדובר , ועל מה שכתב : \" בהפאראד של היום עזר\nהוא וכן אחיו \" – כתב :\nפרטים ?\n( ב ) על מה שכתב : \" למרות שהי ' איסור מההנהלה ד . . להשתתף\nבפאראד \" – כתב :\nהברור זה ?"],[9200110038,"38\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n[3 במכתבו כתב : \" כשהנני שובת כאן כל פעם מדבר בסעודה הג ']\nוהוספתי איזה סיפורים , וחזרתי עניני ל \" ג בעומר מתוכן השיחות , גם\nשהיו דורשים עה \" פ עלית למרום שבית שבי , ר \" ת שמעון בן יוחאי , יצחק\nבן שרה האריז \" ל , ישראל בן שרה הבעש \" ט .\"\nכ \" ק אדמו \" ר שליט \" א מחק את השם : \"( יצחק בן ) שרה \", וכתב :\nשלמה .\nלג\nכ \" ה אייר , תש \" כ ][\nמענה להת ' ירחמיאל בנימין הלוי קליין שכתב : \" דו \" ח מהקביעות של\nחסידות בישיבת תורה ודעת . ראשית הנני להודיע שכדי שיוכלו לגדל\nמספר המבקרים השתנו זמן הקביעות מיום חמישי בערב ליום א ' בערב\n. . עד עכשיו למדו הח \" ב מתניא , וכל פעם לאחרי התועדות חזרו תוכן\nהמאמר והשיחות מההתועדות . עכשיו הם רוצים ללמוד איזה קונטרסים\nוגם שיהי ' מענינא דיומא , אולם היות שלומדים רק פעם א ' בשבוע , לכן\nחשבו שיתחילו ללמוד מאמר מי \" ב תמוז שעד אז ילמדו המאמר , וא '\nהציע שאולי נלמוד קונט ' נ \" ט מספה \" מ תש \" ח . והנני לשאול אם נכון\nהדבר , או ללמוד קונט ' אחר \" ( תש ורה גארדאן י \" א אלול תשע \" ח ע ' יז :)\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את מה שכתב : \" עכשיו הם רוצים\nללמוד . . או ללמוד קונט ' אחר \", וכתב :\nפס \" ד חז \" ל במקום שלבו חפץ\nלד\nט \" ו סיון , תש \" כ ][\nמענה להת ' ירחמיאל בנימין הלוי קליין שכתב : \" הנני להודיע שאתמול\nהלכתי ללמוד חסידות בישיבת תורה ודעת , במקום יום א ' מפני שהי '\nלהם בחינות בקאלעדז , ובאו ב ' תל ' חדשים , ולמדו אות ד ' מקונטרס נ \" ט ,\nוחזרו השיחות מההתועדויות האחרונות , וב \" ה הי ' ניכר הצלחה בזה \"\n( תשורה גא רדאן י \" א אלול תשע \" ח ע ' יז :)\nויה \" ר שעוד תגדל כהנה וכהנה"],[9200110039,"39\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nלה\nסיון , תש \" כ ][\nמענה לר ' שניאור זלמן הלוי דוכמאן על מכתבו בו סיפורים וזכרונות .\nבמכתבו כתב גם דו \" ח בקשר לאמירת קדיש על ידו במשך שנת האבלות\nאחר הרב חיים משה יהושע שניאורסאהן - טווערסקי האדמו \" ר\nדטומשפול – ע \" פ הוראת כ \" ק אדמו \" ר שליט \" א אליו ( מצילום כתי \" ק –\nס ' \" לשמע אוזן \" ( הוצאת תשע \" ו ) ע ' 338 ס ' \" לשמע אוזן \" ( הוצאת תש \" נ );\nע ' טו :)\nת \" ח בעד סיפורים הנ \" ל ומסיים וחותמים בטוב , בטוב הנראה והנגלה\nת \" ח על כתבו הנ \" ל . ובטח ימשיך וגם לזה שייך ופרצת גו .'\nלו\nכ \" ז תמוז , תש \" כ ][\nמענה להת ' משה שלמה סלונים שכתב : \" ובזה אבקש את עצתו הק :'\nיתכן שיש לי עוד סיכויים לדחות את שובי לארץ עד אחרי תשרי – אם\nעל ידי מכתב מהמרכז , או מהנהלת הישיבה , או אפילו לקבל מכתב\nמרופא שעלי להשאר כאן עוד כמה חדשים . ולכן אבקש את הוראתו הק '\n. .\" (\" בית משיח \" גליון 108 ע ' 48-49 :)\nלהודיע תיכף לאביו שי '\nולהוסיף ג \" כ שבהדיבור עם מר שזר שי ' ע \" ד זה דובר שאני אחראי\nבעז \" ה שתיכף לאחרי החגים דתשרי הבע \" ל יחזור\n[ וראה ליקוט מענות קודש תשכ \" א מענה נד .]\nלז\nכ \" ז תמוז , תש \" כ ][\nמענה לר ' דובער בוימגארטען שכתב :\nכשהי ' הברית - מילה של בן הפאליסמאן שבבעדפורד נקראתי לשם\nוהשתתפנו ג ' פאגעלמאן , שרגא , ואני . הברית עצמה לא הי ' כ \" כ כדבעי\nומובן שהי ' בביה \" ח ע \" י המוהל דשם , אבל התנהגותו של אבי הבן הי '"],[9200110040,"40\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nבאופן נעלה מאוד , ולפי שכמדומני שטרם הודיע מישהו לכ \" ק אד \" ש\nמזה , הנני כעת מודיע מזה , אע \" פ אז עס איז שוין א ביסל לאחר הזמן .\nראשית כל ביקשו ממנו שיתן לביה \" ח ח \" י דולר שכן יש להם מנהג שכל\nאב נותן ח \" י דולר ורושמים את שם התינוק בספר הזהב אשר יש להם .\nוהוא הלך אלינו ויאמר שאם צריך ליתן כסף , יתן לכ \" ק אד \" ש ולא לשם .\nהמשקאות לא היו מאותן שאנו שותים , ע \" כ שלח להביא ממה שאנו\nשותים ונגיד לחיי ם לו וכו ' והשאר הגיש בהתוועדות די \" ב תמוז לכ \" ק\nאד \" ש .\nוהמוהל כתב איזה דאקומענט שכתוב שם איזה יום נולד ואיזה יום נימול\nויאמר לו שכאן כתוב שם הקודש , און כשיהי ' לו בר מצוה יצטרך לשם\nזה וכן לחופה . ויען הוא אשר : דאונט - ווארי , בני ילמוד בתו \" ת\nליובאוויטש ויצטרך לשם זה כל יום וישתמש רק בשם הקודש און וידע\nקרוא הספרים ה עברים ג \" כ , האם אינך רואה מי הם חברי ומראה\nבאצבעו עלינו , הם \" פיקסד מי אפ \" והרבה לדבר ככה , וגם אביו וחותנו\nסיפרו בהתפעלות שינויים הטובים שמקודם הי ' אוהב לשתות הרבה\nונשתנה ונעשה הרבה יותר איידל . וביקש ברכה שיוכל לשמור ש \" ק .\"\nמענה כ \" ק אדמו \" ר שליט \" א (\" כפר חב \" ד \" גליון 888 ע ' 128 :)\nת \" ח ת \" ח על הבשו \" ט בטח אנ \" ש מחזקים אותו ( ואת זוג ' תי .)'\nלח\nתמוז , תש \" כ ][\nמענה להשליח ר ' יצחק דוד גראנער בקשר לנסיעתו ממלבורן לביקור\nבחצרות קדשנו ( תשורה גראנער כ \" ה סיון תשע \" א ע ' 15 :)\nשייך לזוג ' תי ' ואח \" כ להנהלת המוסד במעלבורן\nלט\nתמוז , תש \" כ ][\nמענה להת ' יצחק מאיר גורארי ' על מכתבו בעניני עבודת השם ( תשורה\nגורארי ' יו \" ד כסלו תשע \" ב ע ' 50-51 :)\nסימן את סעיף א במכתבו , וכתב :"],[9200110041,"41\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n(1 אזכיר עה \" צ .)\nורק בידו ויכולת מלאה בידו – לעשות ולתקן בכ \" ז . והפס \" ד דהק ' עוזרו .\nסימן את סעיף ב במכתבו – בו שאל , האם ללמוד בסדר חסידות ע \" ד\nדברים פרטיים הנוגעים לפרטי ההתבוננות שבהם מתעסק בעבודת השם\n– וכתב :\n(2 ) תלוי באם בסדר דלימוד אפ \" ל בשני האופנים באם לפני התפלה\nוכיו \" ב – באופן פרטי , וכמבואר בקונ ' התפלה . ודין קדימה להפרט\nשנוגע יותר באותו מעמד ומצב .\nסימן את סעיף ג במכתבו , וכתב :\n(3 ) כנ \" ל (1 )\nעל סעיף ד במכתבו , כתב :\n(4 א \" כ יסיח דעתו מכ \" ז למשך זמן וילמוד בהתמדה ובחיות וכנ \" ל הק ')\nעוזרו\nעל כללות המכתב , כתב :\n(5 ) אזכיר עה \" צ . ובודאי יקיים ובפועל ציווי כל רבותינו מתחיל\nמהבעש \" ט ועד לכ \" ק מו \" ח אדמו \" ר – ע \" ד שמירת ולבריאות הגוף ][\nופשוט שאין דברי בזה בדרך צחות כ \" א כנ \" ל בהנוגע פועל , אכו \" ש\nבעתם שינה וכו .'\nועיין רמב \" ם הל ' דעות רפ \" ד .\nמ\nה ' מנ \" א , תש \" כ ][\nמענה לר ' דובער בוימגארטען (\" כפר חב \" ד \" גליון 888 ע ' 128 :)\n[1 במכתבו כתב : \" יום הולדתי הוא כ \" ה מנ \" א . בכ ' מנ \" א אהי ' בקלברי ']\nושם אין מנין , והיותר קרוב הוא בנאפולי שזה חמשה שעות נסיעה\nמקלברי '. האם אסע לנאפולי על ש \" ק זו לעלות לתורה שם ? או ביום כ \" ה\nמנ \" א שחל ביום הקריאה יום ה '. ההוצאות מרובות דהיינו הרכבת .\nהאטעלים טרם י דעתי אבל אינם יקרים . אולי כן ליסע לשם על ש \" ק א '\nזה גם בתור מרכז שליחות או מצאגו \" ח שיש שם הרבה מהנוער . וגם רב\nצעיר שהנני מכיר חבריו ממילאן שלמדו יחד בטורין , שוחט יש שם עם"],[9200110042,"42\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nזקן שלם מחסידי וויזניץ אבל אינו עושה כלום להחזקת היהדות שם . יש\nלו פרנסה בשופי . . אבל כמה יכולים לעשות בשבת א .\"'\nכ \" ק אדמו \" ר שליט \" א מחק את התיבות : \" אולי כן \", והשאיר את\nהתיבות : \" ליסע לשם על ש \" ק א '\"; וכתב :\nובהתאם להתוצאות יחליט אם להיות שם עוה \" פ או למסור להררג \" מ\nשי ' גארעליק .\n[2 ] במכתבו כתב : \" לא זכיתי להיכנס ליחידות ליום ההולדת קודם\nשנסגר היחידות טרם חודש מנ \" א ונא יברכני בהרמת והארת קרן מזלי .\n.\".\nמענה כ \" ק אדמו \" ר שליט \" א :\nאזכיר עה \" צ .\nמא\nח ' מנ \" א , תש \" כ ][\nמענה לר ' דובער בוימגארטען שכתב : \" יש לי רעזערוויישען על B.O.A.C.\nמטוס 560 איה \" ש ביום ד ' בשעה 4 ללונדון , ומלונדון בליל אור ליום\nועש \" ק נחמו \" (\" כפר חב \" ד \" גליון 888 ע ' 128 :)\nאזכיר עה \" צ .\nביקור בהמוסד שם , באם בקל לסדר – נאום לפני הילדים - ות שי '\nוכיו \" ב .\nמב\nמנ \" א , תש \" כ ][\nמענה לר ' אוריאל צימער על דו \" ח מביקורו בעיר מאנטרעאל ( תשורה\nלאופר ה ' אד \" ר תשע \" ד ע ' 71-72 :)\n[1 ] במכתבו כתב – אשר הכבוד הרב אשר חלקו לו שם הי ' מאד בלתי\nנעים עבורו : \" לא מבעיא מצד מעלתי העצמית , בזה אין לי ספק שגם לא\nהעלה זאת איש בדעתו , אבל גם לא מצד אותה המעלה שכנראה חשבו\nשיש בי מצד שייכותי אל המקור , ועל זה התביישתי בושה גדולה .\""],[9200110043,"43\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nמענה כ \" ק אדמו \" ר שליט \" א :\nפשוט שאם מחשבה שלהם חשבו שיש בי מצד שייכותי אל המקור ][\nצודקת ( ופשוט דהבחירה בידו ), הרי במילא פטור מן [ התביישתי בושה\nגדולה ] .\nבהנ \" ל גם מענה ושלילת התאוננותו לפני על מצבו שכאילו בליובאוויטש\nמביטים עליו כשייך למק \" א וכו ' [ ובמילא בטלה האמתלא למיעוט\nהשמחה והפעולה .]\n[2 ] במכתבו כתב ע \" ד דברי המשפיע ר ' פרץ מאצקין בהתועדות חסידים\nשנערכה שם – אשר מצד אחד גדלה מעלת חסידים הראשונים מחסידי\nזמננו , ומצד שני חסידי כ \" ק אדמו \" ר שליט \" א יש בהם מעלה אף על\nחסידים הראשונים , אשר \" לאידך גיסא יש כיום מקושרים במסירה יותר\nמשהיו .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nומקיימים בפועל דרישת חב \" ד שדלא כהנהגת טלנא ( חה \" פ תרצ \" ד\nכ \" א .)\nמג\nי \" א אלול , תש \" כ ][\nמענה לר ' שניאור זלמן הלוי דוכמאן ( מצילום כתי \" ק – ס ' \" לשמע אוזן \"\nהוצאת תשע \" ו ) ע '( 39 , 322 , 362 :)\n[1 ] במכתבו כתב : \" עש \" ק י \" א אלול יום הולדת שלי בשנת תרנ \" א מבקש\nברכת כ \" ק כפי שיעלה בדעתו או \" במעשה \" או \" בדיבור \" או\nבמחשבה .\"\"\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(1) אזכיר עה \" צ\n[2 על הסיפורים שבמכתבו , כתב כ \" ק אדמו \" ר שליט \" א :]\n(2 ת \" ח על הסיפורים וחבל על שממעט בהם ומקצר .)"],[9200110044,"44\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nמד\nי \" ט אלול , תש \" כ ][\nמענה לר ' דובער בוימגארטען ( תשורה איידעלמאן ל \" ג בעומר תשס \" ו ע '\n27-28 )\n[1 במכתבו כתב :]\nר ' . . שחל \" ח , ויש עוד שדואגים אודות המוסד . . ומשתדלים לבססו .\"\nבין הוועד כולם אוהבים ואוהדים ליובאוויטש וראשי הוועד הד \" ר . . ור '\n. . יותר קרובים לליובאוויטש , וביקשו מהשלוחים שישלחו מנהל\nמליובאוויטש .\nעוד בהיותי שמה ביקשני כזה . ומפני כמה סיבות אז הרגשתי שאין דעת\nקדשו מסכמת על הענין , וכן לפני שנתיים בהיות ר ' . . אצל כ \" ק אד \" ש\nלא קיבל מענה חיובית .\nאבל כעת אחשוב שנשתנה המצב הרבה , והבע \" ב הם רצינים און זיי\nמיינען דעם ענין ערנסט . הנני חפץ לבקש מכ \" ק אד \" ש שבאם דעתו הק '\nמסכמת איבערצונעמען המוסד עכשיו וטוב הנני לזה בעיניו הק ', יואיל\nלשלחני לשם ואזכה להיות שם אישו .\nיש שם כר נרחב לעבודה בשדה החינוך הנערים והנערות . במסיבות שבת ,\nיסוד קעמפ ועוד . יודע אני שיתנו משכורת הגונה וכבר דברתי עם ר ' . .\nהנ \" ל אודות המשכורת שיתנו להמתאים .\nגם אמרתי שלפי דעתי יש איזה דברים שיש לתקן שם טרם שליובאוויטש\nיוכל איבערנעמען אם בכלל לשנות זמן לימודי החול לאחה \" צ ולימודי\nקודש לבוקר , ושכל הילדים מוכרחים לכסות ראשם לא רק בעת לימודי\nקודש אלא גם בעת לימודי החול ובזמן המשחק .\nכן מחכה עלי משרת רב בביהכנ \" ס . . וגם דירה יש שם טובה ומרווחת\nשנותנים לי חנם אם רק ארצה .\"\nכ \" ק אדמו \" ר שליט \" א סימן תיבת \" מסכמת \", וכתב :\n(1 לע \" ע עכ \" פ וע \" פ מה שהי ' בעבר מוקדם .)\nאבל ע \" פ מש \" כ יש שם כר נרחב לעבודה בשדה החינוך כו ]'[ כדאי\nשיתעניין שלא בתור שליח ובמשך הזמן כו .'"],[9200110045,"45\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n[2 ] במכתבו כתב : \" מובן שבאם כ \" ק אד \" ש מסכים ע \" ז אז יש לסדר\nאודות בנותיי , האם כן יסעו עמי או רק שאחת תסע וכו ' וע \" ז עוד חזון\nלמועד .\"\nעל תיבת \" האם \", כתב כ \" ק אדמו \" ר שליט \" א :\n(2 באופן שבעת הראשונה שם יהי ' פנוי יותר לצ \" צ .)\n[3 במכתבו כתב : \" אינני יודע באיזה אופן והיאך לקשר את י . ב . וי . ג .]\nלהיות שאינם מכירים זא \" ז וגם מצטיינים כ \" א במקצוע אחרת , במה\nוממה יהי ' ההתחלה .\"\nעל השם \" י . ב .\", כתב כ \" ק אדמו \" ר שליט \" א :\nיכול לכתוב ששמע ושסיפר לו שמתעניין וכו .'\nמה\nכ \" ף אלול , תש \" כ ][\nממענה להת ' משה יחיאל פעלער שכתב : \" הנני מבקש שכ \" ק אד \" ש יורה\nלי הדרך בזה אם להתחיל בענין אם לחכות בנוגע לזה , שכ \" ק אד \" ש מכיר\nאותי יותר משאני מכיר את עצמי \" ( תשורה פעלער י \" ז מנ \" א תשפ \" א ע '\n7 :)\n(4 ) נדבר כ \" פ שסו \" ס צריך ללמוד עכ \" פ משך איזה זמן – בהתמדה\nושקידה\nודוחה זה מפעם לפעם מפני סיבות וטעמים שונים ובלבולים שונים\n( ונתקיים דבר המשנה דאבות אם בטלת כו ') ויה \" ר שעכ \" פ עד לאחר חג\nהפ ' הבא עלינו לטובה ילמוד באופן הנ \" ל . ומה טוב עד לאחרי חג\nהשבועות זמן מתן תורתינו . ולאחר זה יתענין בשידוך וכו .'\nמו\n[ קייץ , תש \" כ ( 1 ])\nמענה לא ' ששאל : ( א ) איך יכול לפעול על עצמו שיהי ' בשמחה ; ( ב ) האם\nלשנות את נוסח התפלה לנוסח האריז \" ל –\nנדפס באגרות - קודש חי \" ט ע ' תנא ."],[9200110046,"46\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nמז\n[ קייץ , תש \" כ ( 2 ])\nמענה לא ' ששאל – בהמשך להמענה שקיבל ( נסמן לעיל מענה מו ) בו ציין\nכ \" ק אדמו \" ר שליט \" א , בקשר לשינוי נוסח התפלה , ל \" ל \" ת שלח הענין\nדב ' פעמים מאד \" – אשר למד את לקוטי תורה שלח הנ \" ל , ולא הבין\nכוונת הציון לשם –\nנדפס באגרות - קודש חי \" ט ע ' תנא .\nמח\nקייץ , תש \" כ ][\nמענה להשלוחה מרת בתי ' גרליק שכתבה ע \" ד שתי זוגות עמהם דיברה\nע \" ד נסיעה למילאנו לשליחות , ואמרו שמוכנים לצאת לשליחות רק באם\nההוראה תבוא מלמעלה ( אגרות - קודש חי \" ט ע ' תנ - תנא . תשורה לאופער\nג ' טבת תשס \" ח ע ' 6 והעתקה :).\nפשוט שא \" א למצוא מי שיסע לשם – כ \" א ע \" י דבור עם אלה\nשמתאימים לזה . ואין מספיק דבור פעם אחת . וכן לא מספיק דבור \" פון\nיוצא וועגן \", וכמו בכל עניני תומ \" צ . וכן – צריך אָנשטעלן שעוד מי שהוא\nידבר און צורעדן זיי , וכן ישפיעו על אלו שמונעים בזה .\nודאי ש \" המל \" ח \" יסייע בזה וידבר ג \" כ – אבל עיקר הדבור צ \" ל מכזה\nשבא מ מילאַן ויבאר הפרטים וידבר בחום וכו ', ואח \" כ יוסיף המל \" ח\nויחזק דבריו וכו .'\nשני הזוגות שכותבת אודותם – כל אחד מהם מתאים .\nבמענה לזה שאמרו לה שאני צריך לשלוח – אין רגיל שאני אהי '\nהמתחיל לדבר בזה ( מלבד באלה שאני בטוח שהם מקושרים , ובמקרים\nיוצאים מן הכלל .)\nובאם באמת רק זה המניעה – הרי בטח יתחילו הם לדבר וישאלו אותי ,\nואז אומר להם דעתי בזה ."],[9200110047,"47\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nליקוט מענות קודש\n– תש כ \" א –\nמט\nה ' תשרי , תשכ \" א ][\nממענה לר ' שניאור זלמן הלוי דוכמאן על מכתבו בו סיפורים וזכרונות\n( מצילום כתי \" ק – ס ' \" לשמע אוזן \" ( הוצאת תשע \" ו ) ע ' 39 :)\n(2 ת \" ח על הספורים . וחבל שמקמץ בהם .)\nנ\nו ' תשרי , תשכ \" א ][\nמענה להנהלת \" צעירי אגודת חב \" ד \" שכתבו \" פרטי - כל מאסיפת צאגו \" ח\nאור ליום ב ' ה ' תשרי , בדבר סדר היום בכינוס , ב - 770 איסטערן פארקוויי\n. . החלטות הכינוס : . .\" ( מצילום כתי \" ק – נדפס לעיל . המענה מתפרסם\nבזה לראשונה באדיבות מערכת הספר \" ועבדי דוד \" וזכות הרבים תלוי '\nבהם :)\n[1 על כללות המכתב , כתב כ \" ק אדמו \" ר שליט \" א :]\n(1 הבפועל בכהנ \" ל ?)\n[2 ] במכתבם כתבו : \" ללמוד מאמרי כ \" ק אדמו \" ר שליט \" א הנאמרים\nבשנה זו .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(3 ) ( ההנחות בשגיאות ולכן צ \" ל הקביעות בהנדפסים .)\n[3 ] במכתבם כתבו : \" בהמשך לשיעורי הלימוד שנוסדו ע \" י כ \" ק אדמו \" ר\nשליט \" א בעשי \" ת – לקבוע שיעורי לימוד בנגלה ודא \" ח על כל השנה .\"\nכ \" ק אדמו \" ר שליט \" א מחק תיבת \" בעשי \" ת \", וכתב :\n(4 ) שנוסדו ע \" י כ \" ק אדמו \" ר שליט \" א ][ לתשרי"],[9200110048,"48\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nנא\nז ' תשרי , תשכ \" א ][\nמענה לר ' יוסף מנחם מענדל טענענבוים שכתב : \" הרב קאפלאן מסר לי\nאודות בנו הבכור נחום שי ' כי כ \" ק אמר לו שיאמר לי בשם כ \" ק להעלות\nאת בנו למחלקת הרב בוקיעט שי ' על משך ימים לנסותו אם ראוי\nלמחלקה זו . ואשאל אם כנים הדברים \" ( ס ' \" תולדות התמימים בארצות\nהברית \" ע ' 567 :)\nעל התיבות : \" כי כ \" ק אמר לו שיאמר לי בשם כ \" ק \", כתב כ \" ק אדמו \" ר\nשליט \" א :\nבאם אפשרי מצד עניני הישיבה – אפי ' להציע\nנב\nי \" א תשרי , תשכ \" א ][\nמענה למארגני ה \" צ ' ארטר \" עמו נסעו קבוצת אנ \" ש והתמימים שהגיעו\nמאה \" ק לחצרות קדשנו לחודש תשרי ( ס ' \" מקדש מלך \" ח \" ג ע ' רד - רה .\nס ' \" לב הארי \" ע ' 241 :)\nועדה המארגנת .\nמכתבם בנוגע לסדה \" י דהנסיעה נתקבל .\nובטח נתקיים הסדר .\nבכ \" ז – ע \" פ הסדר מכ \" ק מו \" ח אדמו \" ר בכגון דא – יכתבו עד \" ז\nבפרטיות ( בנוגע להביקורים שם וכו ') וכיון שזה נוגע לאיזה ענינים –\nההקדם דדו \" ח זה ישובח , ות \" ח מראש .\nבשם השם תשכ \" א"],[9200110049,"49\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nנג\nלאחר שבת חוהמ \" ס , י \" ז תשרי , תשכ \" א ][\nמענה להמניחים על שאלתם בהמדובר בהתועדות שבת חול המועד\nסוכות :\nבשיחת שבת חוהמ \" ס נתבאר ענין התפלה שעיקרה הוא הדביקות בה ,'\"\nושמזה מובן שצריך הכוונה כללית שעומד לפני השכינה , ואם לאו אינה\nתפלה כלל כמ \" ש הרמב \" ם פ \" ד מהל ' תפלה , משא \" כ הכוונה דפירוש\nהמלות צריך רק בברכת אבות כמ \" ש הרמב \" ם שם פ \" י ( ופירוש זה הוא\nכמ \" ש בחידושי ר ' חיים בריסקער ). וכן מוכח ג \" כ בקו \" א בתניא שכתב\n\" מפני שכוונתו לשמים \". אמנם מסגנון הלשון בשו \" ע אדה \" ז משמע\nשסובר כהמחבר וכדעת התוספות . והקשה בדברי המחבר בשו \" ע שפסק\nכדעת התוספות , שהרי כותב בהקדמתו שבמקום שלשה עמודי עולם ,\nרי \" ף רמב \" ם ורא \" ש , פוסק כהרוב מהם , ובנדו \" ד כות ב הכ \" מ בפ \" ד\nוכ \" כ הרא \" ש ז \" ל \", הרי שס \" ל שגם דעת הרא \" ש הוא כדעת הרמב \" ם ,\"\nולמה פוסק בשו \" ע כדעת התוספות .\nשאלה : הרי לכאורה דעת הרא \" ש הוא כדעת התוספות , כמ \" ש להדיא בפ '\nתפלת השחר ובפ ' אין עומדין , ומ \" ש הכ \" מ \" וכ \" כ הרא \" ש ז \" ל \" הוא לפי\nשהכ \" מ אינו מחלק בדעת הרמב \" ם בין כוונה כללית לפירוש המלות ,\nוראי ' שבכ \" מ בפ \" י מביא אותה הגמרא שבפ \" ד , הרי שלדידי ' גם הרמב \" ם\nסובר כהתוספות , ומהו הקושיא על המחבר .\"?\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – ריש תו \" מ התועדויות\nחכ \" ט ( תשכ \" א ח \" א :))\nעל מה שכתבו : \" הרי שלדידי ' גם הרמב \" ם סובר כהתוספות , ומהו\nהקושיא על המחבר \"? – מחק את התיבות : \" הרי ש לדידי )'( \" גם ,\"\",\n\" כ התוספות )( וכתב :\";\nלדידי ' הרמב \" ם סובר ][ שאם התפלל בלא כוונה חוזר ומתפלל בכוונה –\nכמש \" כ בפירוש בכ \" מ ( והוא ל ' הרמב \" ם ג \" כ בפירוש .)\nוהוא היפך מפורש מדעת התוספות ]["],[9200110050,"50\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nנד\nכ \" ה תשרי , תשכ \" א ][\nמענה להת ' משה שלמה סלונים שכתב : \" לפני שבוע קבלתי הודעה\nממשרד הבטחון שהאריכו לי את שהותי כאן לעוד חודש עד 1 נובמבר\nשזה י \" ד חשון . אבקש מכ \" ק אדמו \" ר שליט \" א להשאר כאן עד אחרי י \" ט\nכסלו או לכה \" פ עד אחרי שבת מברכים כסלו , ואחכה להוראתו הק ' בזה \"\n( מצילום כתי \" ק – \" בית משיח \" גליון 108 ע ' 49-50 :)\nכיון שהאריכו זה כ \" פ על יסוד שאמרו להם בפי ' שזהו עד לאחרי החגים\n– אין לשנות עתה .\nנה\nאדר \" ח מרחשון , תשכ \" א ][\nמענה לר ' יצחק מנחם מענדל ליס – מארגן ה \" צ ' ארטר \" מאה \" ק לחצרות\nקדשנו לחודש תשרי ( מצילום כתי \" ק – \" בית משיח \" גליון 103 ע ' 42 :)\n[1 ] במכתבו כתב : \" הריני בזה להביא לידיעת כ \" ק שליט \" א כי בהתאם\nלדברי כ \" ק שליט \" א טיפלתי בחברת אל - על בהנוגע להחלפת נוסעים מפה\nלאה \" ק . הבאתי את כל הענין להנהלת אל - על פה . ולפי דבריהם – מסתבר\n– כי מצדם אין התנגדות להחלפת נוסעים אך היות שההסכם חתמנו עם\nת \" א לכן אין להם רשות לשנות והציעו לפנות לת \" א ולקבל את\nהסכמתם . עשינו לפי בקשתם . ואך היום נתקבל מכתב תשובה מת \" א\nוהיא שלילית לגמרי . כל הסברים נוספים בנידון הם ללא הועיל .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(1 ) מובן – שבלי דיבור שם פא \" פ אין כל סיכוים למילוי הבקשה .\n[2 ] במכתבו כתב : \" בהתאם לתוכן המברק הרצו \" ב התברר שגם החברה\nשינתה זמן נסיעתנו בחזרה מ - ג ' חשון ל - ב '. וזאת בהתאם לבקשת הסוכן\n. זה שהמציא לנו .\".\nמענה כ \" ק אדמו \" ר שליט \" א :\n(2 ) פשוט – אשר אין סוכן בעה \" ב על הנוסעים , כ \" א ממוצע ומשרת\nשלהם . ואין כל נפק \" מ – במה שמחליט על ד \" ע ."],[9200110051,"51\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n[3 ] במכתבו כתב : \" שואלים את חוו \" ד הק ' בכל הענינים הנ \" ל . וכן אולי\nכדאי יהי ' לטפל בתביעת פיצויים מהחברה בעד שינוי הזמן .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(3 ) בטיפול המתאים – מוכרחים יהיו ( החברה והסוכן ) לשלם\nלהנוסעים בעד כל ההיזק שנגרם ע \" י שינוי הזמן . אבל פשוט – שדרכינו\nדרכי נועם וגו '\n[4 על כללות המכתב , כתב כ \" ק אדמו \" ר שליט \" א :]\nהערה באם \" אל על \" נוקטת – בסעיף ( 1 ) – העמדה שאין לנטות\nמהמדובר , אף שאין לזה כל הסברה בשכל – כש \" כ וק \" ו שזה מחייבם\nשלא לנטות מהמדובר בסעיף ( 3 ) – פרט עיקרי שהשכל מחייבו .\nנו\nב ' מרחשון , תשכ \" א ][\nמענה להת ' חיים אברהם אליהו לנדא שהכניס את מכתב אביו הרב יעקב\nלנדא – בקשר לשאלת כ \" ק אדמו \" ר שליט \" א ( בעת סעודת יום ב ' דראש\nהשנה ) בנוגע המנהג בתקיעת ה \" שברים \" בליובאוויטש : \" אני שמעתי\nבחצרות קדשו נבג \" מ תקיעות רק מכ \" ק קדה \" ק בעצמו והיו כמה דברים ,\nשאפי ' היו מוקשים לבן אדם פשוט . ואני דברתי פעם עם הגאון החסיד\nר ' יעקב רש \" ל מריגא והוא ענה לי , מה איכפת לי \" ער בלאזט דאך \", און\nנאכטאן , הלא לא נהוג אצלנו . חשבתי שגם ענין השברים הוא דבר השייך\nרק לרבי , ועלי לעשות כפי שכתוב בשו \" ע \" –\nנדפס באגרות - קודש ח \" כ ע ' לט .\nנז\nד ' מרחשון , תשכ \" א ][\nמענה לא ' מאנ \" ש דאה \" ק (\" התקשרות \" גליון תשה ע ' 9-10 :)\n[1 ] במכתבו כתב – בהמשך ל \" יחידות \" אלי ' זכה : \" תשובת כ \" ק בנוגע\nלבריאות משפחתי לפי תפיסת זיכרוני היתה : בכלל דער מצב הבריאות\nנעמט זיך פון נערווען בא איהר דארף מען האבן א התחזקות אין ביטחון .\nחוץ מעניין ה . . וה . . שצריכים לשאול עצת רופא .\""],[9200110052,"52\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nמענה כ \" ק אדמו \" ר שליט \" א :\nא ) על מה שכתב : \" נעמט זיך פון נערווען \", כתב :(\nנעמט זיך ][ חלק חשוב – פון נערווען ][\nב ) על מה שכתב : \" חוץ מעניין כו \"'( – מחק תיבת \" חוץ \", וכתב :\nאבל כיוון שבחלקו הוא לא מהנ \" ל ובפרט מעניין כו ]'[\n[2 במכתבו כתב : \" שאלתי מכ \" ק מה לעשות בכדי לחזק עניין הביטחון .]\nמה למסור ל . . ובפרט שמטבעה יש לה ב \" ה ביטחון חזק ואינה דואגת\nכל כך . וכשמרגישים לא טוב , אז היא שאלתי במה ואיך לחזק\nהביטחון .\"?\nמענה כ \" ק אדמו \" ר שליט \" א :\nילמד בדא \" ח בחוה \" ל שער הבטחון וכיו \" ב .\nויסביר הענינים גם לזוג ' תי '\nנח\nאור לועש \" ק לך , ז ' מרחשון , תשכ \" א ][\nמענה להרב מרדכי הארליג ( מצילום כתי \" ק – תשורה הארליג י \" א אד \" ר\nתשנ \" ז ע ' 9-11 :)\n[1 ] במכתבו כתב : \" זה כמה שנים שאני מעורר את הרבנים מסביבתנו\nאודות נחיצות הדחופה לבנות בית טבילה לבנות ישראל , כי המקום\nביוניאן סטריט מצער מאד . . ולא נעשה דבר ממשי עד כעת . והרבה\nאנשים ממתפללי ביהמד \" ר שלי וגם אנשים מהסביבה אומרים שנחוץ\nמאד לבנות גם מקוה בעד נ שים ליד הביהמד \" ר . ויש האפשרות לנו לבנות\nמקוה בשביל נשים , כי הגברים ילכו דרך חצר ביהמד \" ר , והנשים ילכו\nדרך רחוב ראדזערס עוו . וזמנו של זה לא זמנו של זו . המקוה בשביל\nאנשים נבנה במרתף – בייסמענט – ומן הצד של מקוה זו אפשר לבנות\nשתי מקוואות בשביל נשים , ולמעלה מן המרתף נמצא כעת חנות ואפשר\nלפנות המקום ולבנות שמה חדרים עם אמבטיאות ומשם ירדו במדרגות\nלהמקוה . . והריני מציע כל הענין לפני כ \" ק אדמו \" ר שליט \" א ואתחנן\nלחוו \" ד הקדושה , ויצוה איך להתנהג וכאשר יגזר א ומר כן אקיים\nבעזהי \" ת .\""],[9200110053,"53\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות : \" ולמעלה . . ומשם ירדו\nבמדרגות להמקוה \", וכתב :\n(1 איני יודע היחס לזה כאן . ולכן יבוא בדברים בזה עם היודעים .)\nובהתאם להידיעות יחליטו .\n[2 ] במכתבו כתב : \" כן ארשה לי לשאול את כ \" ק אדמו \" ר הקדוש\nשליט \" א . שמעתי שכ \" ק י \" נ הידר ליקח הדסים מאיטליא , וגם אני הדרתי\nעד \" ז ליקח ג \" כ אותם ההדסים לקיום מצוה מן המובחר , ומעשה רב . אכן\nבזה אני נבוך אם כ \" ק אדמו \" ר שליט \" א לקח ג \" כ ההדסים הגדולים ,\nאמת שבסי ' תרמ \" ו אינו מבואר שיעור גדלן , אכן ביו \" ד סי ' לה מבואר\nשיעור טרפא דאסא בדרכי משה ס \" ק י \" ב – יש אומרים הוא כצפורן\nאגודל וי \" א שהוא כפרק אמצעי של אגודל , ובס ' גילוי דעת על ה ' טרפות ,\nמהגאון מבערזאן ז \" ל – כתב דהקטנים רק כצפורן אגודל הם הכשירים\nלמצוה , אבל בעלים גדולים כשני צפרני אגודל יש לפקפק אם הם\nכשירים . והאחרונים מביאים שמבואר בבה \" ג ה ' לולב היכא דרברבין\nטורפי ' פסול . לכן אחלה נא את פני כ \" ק אדמו \" ר שליט \" א אשר כל רז לא\nאניס לי ' שיאבה בטובו הגדול להאיר עיני איך להתנהג .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(2 שיעור טרפא דאסא עייג \" כ פס \" ד להצ \" צ יו \" ד סל \" ה ס \" ו ( פג , א .)) –\nוהנה בודאי שבזה , כמו בכל שיעורי התורה מסוג זה ( כלים פי \" ז ) –\nהכוונה לטרפא בינונית ז . א . שאפ \" ל גם קטנה מזה או גדולה – וכולם\nטרפא דאסא הם . ומד ' מינים עצמם ההוכחה – שהרי אתרוג גדול כ \" ש\nכשר ( או \" ח סו \" ס תרמ \" ח ). כמובן מלבד בהענינים ששם מפורש שזהו\nלעיכובא .\nוכנראה שזהו טעם מחלוקת הבה \" ג ואלו שאין מביאים דעתו ( כל\nהפוסקים . ואף שמביאין דעתו בכ \" מ ) כי יסוד הבה \" ג , שמפרש כך הדס\nשוטה . וכל שאין מפרש הדס שוטה כך – בטל היסוד ובטל האיסור . –\nועוד להעיר – שגם הבה \" ג לא פירש השיעור דרברבין ופתין . – בס ' חיים\nוברכה ( להרב טשערניק ) הביא הדעות בזה .\nלהעיר מחטים ככליות ( ואז הי ' זה בטבע ). וכן מהדיעה שנתקטנו\nהשיעורים – ז . א . שאין השיעור סימן .\n[3 כ \" ק אדמו \" ר שליט \" א סימן בעיגול את חתימת הנמען \" מרדכי בן חי ']\nשרה \", וכתב :\n(3) אזכיר עה \" צ"],[9200110054,"54\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nנט\nי \" ב מרחשון , תשכ \" א ][\nמענה לר ' דובער בוימגארטען ( תשורה איידעלמאן ל \" ג בעומר תשס \" ו ע '\n28-29 :)\n[1 ] במכתבו כתב : \" מעת שובו של . . מטלפן אלי תמיד וחפץ לחדש עוה \" פ\nהסדר שהי ' מקודם , והייתי טרוד ולא עניתי . לאחר זמן התחיל לדרוש\nלמה נתקררתי וחשש אולי פגע בכבודי , ונסעתי לבקר אצלו ועסוק הי '\nבלימוד בבא בתרא פ ' המוכר את הפרה בתחילה עם ג ' תלמידות , ואע \" פ\nשהרבה חשק ללמוד גמ ' עם הנשים לא הי ' לי , מ \" מ כבר הייתי שמה\nונטלתי חלק בלימוד . וכן התדברנו בינינו אח \" ז לסדר עוה \" פ למוד כמו\nמקדם נוסף על מה שביקשני לקבוע זמן לדא \" ח .\"\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות \" בבא בתרא \", וכתב :\n(1 ) להציע שילמוד עמהן מס ' שאין כל חשש בלימוד לנשים , וכמו מסדר\nמועד וכיו \" ב ( הל ' ת \" ת לאדה \" ז ספ \" א .)\n[ וראה לקמן מענה סד .]\n[2 ] במכתבו כתב : \" זה כמה חדשים שאבא זאב בן צירל נחלה במחלת\nfungus . . ביקר אצל רופא פרטי וגם אצל מומחה ונתנו לו כמה סמי\nמרפא לרחוץ בהם ולקחתם בפה ולע \" ע טרם נתרפא , ואבקש מכ \" ק\nאד \" ש שיברכו ברפו \" ש .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(2 ) אזכיר עה \" צ ( כדאי שיבקר את ד \" ר היימאן שי ' בנו של הרב\nמלונדאן .)\n[3 במכתבו כתב : \" שישתנה מזלי לטובה ולא יבואו עוד צרות ורעות וכו ']\nואהי ' כלי לברכתו הק ' ואזכה להיות שליח כ \" ק אד \" ש מתוך הרחבה .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nאזכיר עה \" צ להחזיר המצו \" ב ."],[9200110055,"55\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nס\nכ \" ף מרחשון , תשכ \" א ][\nמענה להת ' ירחמיאל בנימין הלוי קליין שכתב : \" היום נקראתי ביחד עם\nהת ' משה שי ' באגאמילסקי ע \" י הנהלת הישיבה בקשר להישיבה\nבפיטסבורג אודות הרמת הרוח אצל הבע \" ב בעיר בנוגע להישיבה . ודברו\nאתנו שנסע לשם על משך ב ' שבועות ( ר \" ח כסלו – י \" ג כסלו ). אודות\nעבודתינו שם , צריכים אנו להתייעץ עם הר \" ר שלום שי ' פויזנער כשנבוא\nלשם . והנני לשאול אם מתאים למצבי הנוכחי לקבל ההצעה הנ \" ל \"\nתשורה שייקביץ ז ' אלול תש \" פ ע '( 14 :)\n[1 ] מחק את התיבות \" והנני לשאול אם \", וסימן בקו ובשני חיצים תיבת\nמתאים .\"\"\n[2 סימן בעיגול את התיבות \" למצבי הנוכחי \", וכתב :]\n?\n[ וראה לקמן מענה סג .]\nסא\nועש \" ק וירא , כ \" א מרחשון , תשכ \" א ][\nמענה לר ' יוסף מנחם מענדל טענענבוים שכתב : \" הנני בזה להודיע לכ \" ק\nכי במוצאי שבת קודש הבע \" ל תתקיים אי \" ה התועדות מלוה מלכה\nהראשונה עבור תלמידי הישיבה בהבנין על בעדפארד עוו . בשעה 8 .\nהתלמידים יתאספו ע \" י 770 בשעה 7:45 והבאס יוליכם לבית\nההתוועדות ויחזירם \" ( ס ' \" תולד ות התמימים בארצות הברית \" ע ' 572-\n573 :)\nותהא בשעטומ \" צ .\n[ וראה לקמן מענה סב .]"],[9200110056,"56\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nסב\nכ \" ו מרחשון , תשכ \" א ][\nמענה לר ' יוסף מנחם מענדל טענענבוים שכתב : \" הנני שולח בזה לכ \" ק\nפרטי כל מאסיפת הרמי \" ם דמתיבתא בליל ה ' העבר . והנני להודיע לכ \" ק\nכי במוצאי שבת קודש העבר השתתפו בהמלוה מלכה יותר משבעים\nתלמידים כן ירבו \" ( ס ' \" תולדות התמימים בארצות הברית \" ע ' 573 :)\nת \" ח על הבשו \" ט\nסג\nר \" ח כסלו , תשכ \" א ][\nמענה להת ' ירחמיאל בנימין הלוי קליין והת ' משה באגאמילסקי שכתבו\n– בקשר לנסיעתם לעיר פיטסבורג לפעול לטובת ישיבת \" אחי תמימים \"\nשם : \" הננו להודיע שאנחנו נוסעים אי \" ה לעיר פיטסבורג ביום ראשון\nהבעל \" ט . . והננו לבקש ברכתו הק '\" ( תשורה שייקביץ ז ' אלול תש \" פ ע '\n15 :)\nאזכיר עה \" צ\nבטח יבקרו שם ( המתאימים לזה ) לשקו \" ט בנגלה .\nסד\nאור לה ' כסלו , תשכ \" א ][\nמענה לר ' דובער בוימגארטען ( תשורה איידעלמאן ל \" ג בעומר תשס \" ו ע '\n29-31 . \" כפר חב \" ד \" גליון 910 ע ' 102 :)\n[1 ] במכתבו כתב : \" דברתי עם . . אודות לימוד בסדר מועד [ ראה לעיל\nמענה נט ] וענה לי שבבא - בתרא מכין הוא בין כך ובין כך , משא \" כ למוד\nאחר מיוחד לנשים צריך להכין ואין לו זמן עד \" ז והוא אינו יכול ללמוד\nעם מישהו אחר מבלי הכנה .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(1 להראותו בשו \" ע אדה \" ז .)\n[2 במכתבו כתב : \" השאלה אודות . . אם בידי לעשות לו הטובה או לא .\"?]"],[9200110057,"57\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nמענה כ \" ק אדמו \" ר שליט \" א :\n(2 יתייעץ עם הרג \" מ שי ')\n[3 ] במכתבו כתב : \" ביקש ממני . . אולי אוכל למצוא בישיבה מישהו\nמתאים עבור בתו של פרופ ' . . בחור עם זקן .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(3 ) – יחליט בזה על יסוד הכרתו אותה וכן בחורי הישיבה .\n[4 במכתבו כתב :]\n\" הזכרתי כמ \" פ אודות משפחת . . והאח הצעיר אשר במילא כעת חפץ\nלנסוע לכאן ללמוד בישיבתינו . בסוף תשי \" ט ותחלת תש \" כ למדתי עמו\nהרבה זמן ויש לו התמדה גדולה וראשו מכיל הלימודים טוב . מובן שהנהו\n\" רוי \" בלימוד שמעודו לא למד , ועיקר מגמתי אז עמו הי ' להראות נועם\nוערבות שמיר ת התומ \" צ , ות \" ל שהצלחתי במדה גדולה בכמה פרטים\nבשמירת ש \" ק ואכילת כשר , וכבר כתבתי שדקדק לאכול פת ישראל\nבעשי \" ת ואיך שהלך עריוהכ \" פ לטבול במס \" נ .\nולפיענ \" ד הי ' דבר גדול ביאתו לכאן גם עבור מילאן שיוכל לעשות שם\nצאתכם לשלום ויכול להיות בפני הכל שזהו מצד תעמולת הרג \" מ והר \" מ\nלאזאר , שאינני חפץ בשום קרעדיט רק טובת הענין .\nובאם ההצעה מוצאת חן בעיני כ \" ק אד \" ש וכשר הדבר בעיניו , יהי ' יותר\nקל דורכפירן הענין לתכליתו הן מצד הנהלת הישיבה והן מצד עצם הענין ,\nלפי שמי יכנס א \" ע בענין זה שצריך התעסקות גדולה ועצומה מבלי לדעת\nדעת קדשו היאך הוא .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(4 ) מובן שזהו שייך לאלו היודעים הנ \" ל ז . א . הכותב ואנ \" ש דמילאַן\nובכלל אינה מובנת שאלתו וספקו בענין שאין בו צד שלילי באם יהי ' מי\nשיתענין כאן בהאברך עכ \" פ בתקופה הראשונה לבואו .\n[5 במכתבו כתב :]\n\" ג ) השאלה אודות . . בארגנטינה .[ ].\nז ) מכתבים מארגנטינה מאוד בהתרגשות . מכתבים מ . . בהרבה אהבה\nוידידות והחליט לעשות ישיבה עם מורים מליובאוויטש .\nח ) כותבים כאן שישלחו כאן שני נערים ללמוד וכן עוד שני נערים לאח \" ז ."],[9200110058,"58\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nט ) כן כתבו ש . . הסכים לייסד ישיבה מל ' נערים ט \" ו משלנו וט \" ו\nמהרחוב והוא . . מבטיח שיהי ' ל ' אלו .\nי ) כן כותבים אשר כבר הסבירו לכולם שם מטוהר ליבי ותקנו את הכל\nבכדי שאבוא ויהי ' הכל מוכן בכבוד וכדבעי למהוי .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(5 ) ז – יו \" ד ( וכן ע \" ד .[ ]. )\nמובן שזהו תלוי בהפתרון 1 ) מתי נוסע לשם 2 ) איך יסדר העבודה בכדי\nלשלול אי - הקיום שהי ' בעבר וכו .'\n[6 במכתבו כתב :]\n\" זה עכשיו שאל אותי הרחמ \" א חדקוב על מה שהי ' מסומן על מכתבו של\n. ., ש . . כתב שנותן את הישיבה לשנינו וע \" ז סימן כ \" ק אד \" ש \" מה\nהתכנית שלי בזה \". והנה ע \" ע לא הי ' לי שום תכנית לפי שהבנתי מכל\nהענין שלא ירד למעשה וגם לפועל לא הי ' שום הצעה קונקראטי אלי רק\nשכן תפסו שב אם ישלחו א ' מכאן לשם אהי ' אני , זהו .\nבכלל כן משמע ממכתבו של . . שכתב שתחילת הכל צריך לבקש בית\n( ולפנ \" ז ביקש לקנות בית של הגב ' . . שעולה 40 אלף דולר ובטח הוא סיפר\nלה שהכסף יבוא מכאן על סמך זה בטח היא אינה מבקשת עוד קונים ,)\nומורה ומנהל ואח \" כ ילדים , ואמרתי לו טרם נסיעתי שראשונה יבקש\nהתל ' ואח \" כ הש אר .\"\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את שם המדובר (\" ממכתבו של כו ,)\"'\nוכתב :\n(6 ) הרי במעמדו אמרתי שאיני מבטיח כ \" א שמדבר עד \" ז ופשיטא שאין\nלדבר כלל מסכומים כאלו ועתה בכלל נשתנה כל המצב כי הוכרז כבר\nשנפתח שם בי \" ס למורים ( כנראה בעזר הדזוינט ועוד ) מהסעמינאר\nוכו .'\nסה\nיו \" ד כסלו , תשכ \" א ][\nמענה לר ' דובער בוימגארטען ( תשורה איידעלמאן ל \" ג בעומר תשס \" ו ע '\n31-33 :)"],[9200110059,"59\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n[1 על כללות המכתב , כתב כ \" ק אדמו \" ר שליט \" א :]\n(1 להחזיר המצורף .)\n[2 ] במכתבו כתב : \" בנוגע למכתב לשם עבור אחיו של . . האם אכתוב\nבשמי סתם , או שיותר טוב לכתוב שכ ן אמר או רמז כ \" ק אד \" ש , כמובן\nהנני כותב באופן שהמכתב ישאר אצל ו ורק בע \" פ יסביר להם הענינים\nואחר שאקבל תשובת כ \" ק אד \" ש תומ \" י אכתוב המכתב וטרם אשלח\nאמסור המכ ' לכ \" ק אד \" ש לראות הטוב בעיניו .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(2 ) הי ' מובן ברור מדברַי כשדברו עמדי עד \" ז\n[3 במכתבו כתב :]\n\" עוד טרם הבנתי בטוב איך צ \" ל הבאנעמונג שלי עמהם , היינו אם צ \" ל\nתמיד בביטול יחס ול . . בכדי ביי זיי אויפצונעמען וע י \" ז להכנס אצלם\nיותר בפנים או לא . לפי ש . . ו . . מרגישים שאחד מרכין ראשו וכו ' נוצען\nזיי דאס אויס הרבה וחפצם לעשות מההרכנה השתחוואה בפישוט ידים\nורגלים , הן סוכ \" ס מוכרחים לדעת אשר מוסד אשר בשמם יקרא והם\nיתערבו בו וועט ניט געווינען דעם צוטרוי על שאר קהילות הספרדים\nמשם . אבל כ שיהי ' מוסד לא על שמם , יהי ' פתוח באופן שכל הרוצה יבא\nויראה מבלי לבדוק בציציותיו וגם שאר הקהילות ישתתפו בהוצאות . .\nזה ברור שאחד מבלעדי אין להם ומשו \" ז כתבתי הכל כאן ברור לפי שאני\nצריך לדעת איך להתנהג , אם הנני צריך לטובת הענין להיות כחסידו ותל '\nשל פלוני אין זה כלל קשה בשבילי וכן הייתי נוהג בתחילת בואי לשם ,\nאבל כנ \" ל איני יודע באם זהו ענין ואדרבה אולי לטובת הענין יותר טוב\nשאתנהג מיט א שטעל .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nא ) על כללות הענין , כתב :(\n(3 ) לפי המצב שהי ' בהווה בכל מקרה ופעם כשיבוא לשם , עד השייכות\nהרי למי שהוא צריך להשתייך וכבר אמרתי – שמפני ההשתל ' בעבר –\nאין זה שמכאן מייסדים שם מוסד ונושאים באחריותו וכו ' כ \" א שזהו\nענינם וכו ' ומבקשים סיוע מכאן וכו .'\nב ) סימן בעיגול את שם המדובר , וכתב :(\n(4 אבל באופן שלא למעט דמותו .)"],[9200110060,"60\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n[4 במכתבו כתב :] \" . . כתב שהסביר ל . . על היחידות וכו ' שהסביר להם\nמה שאד \" ש ענה וכו ' ור וצה לדעת האם זה נכון .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(5 נכונות המענות .)\n[5 במכתבו כתב :] \" בקשר לברכה לפרנסה הנה הרווחה בפרנסה הי ' מעל\nלעבודה , כי הי ' זמן שהי ' לי פרנסה ונסיעות כאלה ל . . והוצאות כרוכים\nבהוצאות ומלפנים הייתי מקבל מרחמ \" א בכל חודש על הוצאות ובנתיים\nלא הגשתי דו \" ח הוצאות , וכעת השיב לי על שאלתי שהבודזשעטען לא\nמרשה לו להשתתף ומובן שלא פסקתיו ובמילא פרנסה בהרחבה וואלט\nגארניט שאדן .\"\nעל התיבות \" דו \" ח הוצאות \", כתב כ \" ק אדמו \" ר שליט \" א :\n(6 מה הסכום לערך ?)\n[6 על כללות המכתב , כתב כ \" ק אדמו \" ר שליט \" א :]\n(7 אזכיר עה \" צ .)\nסו\nאור לכ \" ג כסלו , תשכ \" א ][\nמענה לר ' דובער בוימגארטען ( תשורה איידעלמאן ל \" ג בעומר תשס \" ו ע '\n33 תשורה באטלער ו ' תשרי תשע \" ח ע ' קיח :).\n[1 ] במכתבו כתב : \" עם . . למדתי שער היחוד ולא בהצלחה גדולה , ואח \" כ\nאגה \" ת עם יותר הצלחה . ועכשיו שגמרנו אגה \" ת אמר ששמע שיש סדר\nשסידר כ \" ק אד \" ש ומתחילים בדא \" ח בקדימה ואיחור והוא חפץ בסדר\nזה .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(1 ) בתניא ח \" ג – ח \" ב – ח \" א\nקונטרס ומעין\nדרמ \" צ הדרושים הבלתי ארוכים בכמותם"],[9200110061,"61\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n[2 ] על ענין מסויים שכתב – בקשר לאשה מסויימת , המסורה לעניני הכלל\n– כתב כ \" ק אדמו \" ר שליט \" א :\n(2 ימסור למזכ ')\n[3 ] במכתבו כתב : \" כפיה \" נ אתחיל הקביעות עוה \" פ בסעמינאר איה \" ש\nשבוע זו באור ליום ועש \" ק ויואיל נא כ \" ק אד \" ש להורות במה להתחיל\nולברך שיהי ' בהצלחה .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(3 ) במקום שלבם חפץ אזכיר עה \" צ\n[4 במכתבו כתב : \" אודות עסקים . . ש . . רוצה לעשות הכל לעגאל .\"]\nמענה כ \" ק אדמו \" ר שליט \" א :\n(4 ) באם לעגאל ][\n(5) אזכיר עה \" צ\nסז\nכ \" ה כסלו , א ' דחנוכה , תשכ \" א ][\nמענה לא ' שכתב שהתקרב לתומ \" צ ובני משפחתו מבלבלים אותו בזה\nורוצים להשפיע עליו להתרחק מדרך התומ \" צ ( מצילום כתי \" ק – תשורה\nסימפסון י \" א אד \" ר תשס \" ה ע ' 4. אגרות - קודש ח \" כ ע ' צה :)\nבתקופתנו , כו \" כ מאלו שבחרו בחיים , בדרך תורתנו תו \" ח , יש להם\nבלבולים ומניעות מבני משפחתם שרוצים שיחזרו מבחירתם זו .\nוהדרך היותר מתאימה וקרובה יותר לשלום : 1 ) לא להכנס כלל לשקו \" ט\nוטענות ולהִמנַע ממחלוקת בזה . לכתוב רק ע \" ד עניני משפחה וכיו \" ב –\n[ לאחרי שמודיעים פ \" א שבחרו בהחלט בדרך התורה . והרי כבר הודיע\nזה .]\n2 ) לא להתבלבל מהזלזולים וכיו \" ב שבמכ ' ( שכנ \" ל כו \" כ מסוגו מקבלים\nמכ ' כאלו ). ובפרט שיודע שזהו בא בתקוה – אולי עי \" ז יכריחוהו לסור\nמדרך התומ \" צ .\n3 ) ללמוד בהתמדה ושקידה . והרי הצלחתו בזה – תהי ' המענה היותר\nטובה להטענות שכותבים לו . וסו \" ס יתקבל זה גם אצל הטוענים ."],[9200110062,"62\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nבנוגע לפרנסה – יתבונן כשיתקרב הזמן לזה .\nבנוגע לזקן ופאות – יקבע הסגנון אם ואיך להודיע – לאחר שיקבל\nהמענ ות על כל מכ ' שלו ויענה עליהם וכו .'\nסח\nד ' טבת , תשכ \" א ][\nמענה להת ' ירחמיאל בנימין הלוי קליין שכתב : \" הנני להודיע שקבלתי\nמכ ' מאחי יעקב הלוי בן רחל ע \" ה ובו מודיע שנולד לו בת למז \" ט וקרא\nשמה בישראל רבקה חי ' פייגע בת מלכה ליבא \" ( מצילום כתי \" ק . המענה\nמתפרסם בזה לראשונה באדיבות מערכת הספר \" מיין גענעראל \" וזכות\nהרבים תלוי ' בהם :)\nת \" ח על הבשו \" ט\nויגדלוה לתחומע \" ט\nסט\nז ' טבת , תשכ \" א ][\nמענה להת ' דוב טייכמן שכתב – בקשר לנסיעתו מחצרות קדשנו לאה \" ק ,\nיחד עם הת ' אברהם דונין והת ' אברהם יצחק ששונקין : \" סדר וזמן\nהנסיעה לאה \" ק ת \" ו הוא : ביום ד ' ט \" ז טבת ב - 10.30 בבוקר יוצאים עם\nהאניה קווין אליזבט . האניה נעצרת בצרפת וממשיכה אחר - כך לאנגליה .\nלצרפת נגיע בעזרת ה ' ביום ג ' כ \" ב טבת בבוק ר ואחר - כך עוברים לאניה\nשניה , ענוטריה , היוצאת ביום ה ' כ \" ד טבת מנאפולי לאה \" ק ת \" ו . ולפי\nדברי סוכן הנסיעות תריסר יש לנו את האפשרויות האלה : א ) להיות רק\nבאנגליה כמעת - לעת בערך , ומשם לנסוע ישר לנאפולי . ב ) להיות רק\nבצרפת כשני מעת - לעת בערך , ומשם לנסוע לנאפולי . ג ) לה יות רק\nבמילאנו כשני מעת - לעת , ומשם לנסוע לנאפולי . ד ) להיות בצרפת מעת -\nלעת ובמילאנו מעת - לעת , ומשם להמשיך לנאפולי . ושואל הנני מכ \" ק\nאדמו \" ר שליט \" א איך לסדר נסיעתי \" (\" התקשרות \" גליון רסא ע ' 10-11 .\nקונטרס ועד הנחות בלה \" ק שבת חוהמ \" פ תשע \" ז ע ' 18 :)\nיתחלקו ביניהם ( ע \" פ הגורל או בריצוי ) – א ' ינצל כל זמן הפנוי באנגלי ,'\nהב ' – בצרפת , הג ' – באיטלי .'"],[9200110063,"63\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nיתוועדו שם ימסרו מהמדובר כאן וכו '. ויה \" ר שיהי ' בהצלחה רבה .\nוכמובן – גם בהאניות עד \" ז , ועאכו \" כ באהקת \" ו .\nע\nטבת , תשכ \" א ][\nמענה בקשר לחתונה מסויימת שעמדה להתקיים בתקופה זו ( תשורה\nאיידעלמאן ל \" ג בעומר תשס \" ו ע ' 34-35 :)\nצודק כמוכם בשלילת \" מנהגים \" הנ \" ל שלא שערום אבותינו ועוד כהנה\nשאינו מזכיר\nבזבוז ממונם של ישראל בכלל , ועל ענינים שאינם רצויים כלל אפי '(\nבאם הי ' חנם . ולא עוד אלא שהכיוון הוא ר \" ל לעשות העיקר – טפל ואת\nהבלתי רצוי כלל – לעיקר וד \" ל .\nוהאומנם מחוייב הנני להיות חלק מהצערעמאניע ושתונצח אח \" כ\nבאלבום , בשביל המוזרות בלבנה ושמחירו סכום המספיק להחזקת\nכתה גדולה בישיבה במורוקו במשך ששה חדשים ויותר )\n[ וראה לקמן מענה עא .]\nעא\nכ \" ף טבת , תשכ \" א ][\nמענה לר ' דובער בוימגארטען ( תשורה איידעלמאן ל \" ג בעומר תשס \" ו ע '\n34 :)\n[1 במכתבו כתב :]\n\" עלי להפגש בבית אחי מ \" מ מחר בלילה עם . . וחמותו . ובקשר לזה\nאבקש שיואיל כ \" ק אד \" ש להוריני בדיוק בכוונתו בתיבות \" הענינים\nשתוכנם רק להידמות למנהגי המדינה שלא שערום אבותינו \", לאיזה\nפרטים , המוזיק או הפרחים ולפי שבטח אין כוונתו על השייטיל או על\nהמשקה , אלא רק על מ וזיק או פרחים או תמונות .\nעלי כאן להדגיש שהחתן מצדו חפץ בהוצאות קטנות ואמר שבשבילו\nיכינו הערינג וואורסט על פאפירענע טעלער ובאיזה מקום שיהי ', ואדרבא\nאני הזהרתיו שלא יעמוד נגדם בתקיפות בזה ושצריך להתחשב עמהם"],[9200110064,"64\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nג \" כ , וגם אמר שעל הכלה יוכל לפעול ג \" כ בזה אלא שקרובי ' רוצים דוקא\nהתפשטות והתרחבות , ואולי כוונתו הק ' לעשות כל החתונה באופן הנ \" ל\nבכלים של נייר באיזה ביהכנ \" ס וזה יכול להיות , משא \" כ כשרוצים\nמאכלים חמים ומרק אז אפי ' לא שוכרים זאל גדול ולא מבשלים כ \" א\nאייגינע מ \" מ ה מחיר שוה כמעט כששוכרים אולם , ושמעתי מאחדים\nשכוונתו הק ' הי ' שכן יהי ' מאכלים חמים רק שיהי ' בזול וחקרתי\nומצאתי שמחירים כמעט שוים .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nשלא שערום אבותינו ][ משא \" כ מאכלים חמים ומרק ][\nואינו מובן הספק .\n[2 ] במכתבו כתב : \" כן האם צריכים לבטל את המנות והמוזיקע והפרחים\nלגמרי או רק לצמצם בהוצאות אלו . מובן שרק צד החתן מתאימים בדעה\nלעשות כנ \" ל אבל יתכן שאחרי ידיעתי יותר נכון אוכל בהסברה טובה\nבדרכי נועם לפעול עליהם ג \" כ .\"\nעל התיבות : \" בדרכי נועם לפעול עליהם \" – כ \" ק אדמו \" ר שליט \" א שינה\nאת הסדר שיהי ' כתוב : \" לפעול עליהם בדרכי נועם \", וכתב :\nבכלל מובן שהכוונה רק מה שאפשר .\nעב\nלפני חודש שבט , תשכ \" א ][\nמענה להרב יהושע קארף שכתב : \" היות ששאלתי ההנהלה דנוארק\nאודות בני פנחס שיחי ' אם ישאר שם בעבודתו בקביעות , וענו לי שהם\nשבעי רצון ממנו ואם לא יצטרך ליסע למקום אחר אין מניעה מצדם\nשישאר שם , ע \" כ אני שואל אם להשתדל להשיג דירה שם עבורו . ואם\nהמיועדת לו תשתדל להשיג שם משרה ולעזוב עבודתה כאן אחר חתונתם\nבע \" ה לשטומ \" צ , על מה שצריכה כעת ליתן להם תשובה . ההנהלה\nדנוארק אמר אפשר שיהי ' להם משרה בשבילה בהאפיס שלהם ויתברר\nבמשך הזמן \" ( מהעתקה . המענה מתפרסם בזה לראשונה באדיבות\nמשפחת הרב פינחס קארף ע \" ה וזכות הרבים תלוי ' בהם :)\nיאמרו שרוצה לעשות כל הנ \" ל על יסוד דבריהם הנ \" ל וידברו פרטי\nהעבודה והמשכורת וכו ' ובהתאם לזה יחליטו – בנו וב \" ג שיחיו\n[ מענתי לו – ג \" כ שלא ע \" פ סדר היא כלל כי בנו וב \" ג עליהם לשאול בזה ]"],[9200110065,"65\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nעג\nו ' שבט , תשכ \" א ][\nמענה לר ' דובער בוימגארטען ( תשורה איידעלמאן ל \" ג בעומר תשס \" ו ע '\n35-36 קובץ \" עיוני תורה \" חוברת יט ע '. 7-8 :)\n[1 במכתבו כתב :]\n\" ברשימת הר ' לנדא ממקוה כ \" ק אדנ \" ע בראסטאוו אינו מזכיר כלל על\nאוצר לזריעה , וכן במילאנא למקוה הנעשית ע \" י הרב פערלאוו ועשהו\nמקוה ע \" ג מקוה ואוצר לזריעה אין שם , אבל שם אמרו שלא עשו אוצר\nלזריעה מאפס מקום לזה . והנני שואל האם יש מקום להידור בזה ?\nשלפי \" ד באם הי ' נחיצות הי ' בטח כ \" ק אדנ \" ע מצוה לעשותה , בשגם סיפר\nלי ר ' נתן דוד רוזנבלוים מב . א . בדיוק בזמן ההיא הי ' בראסטאוו וראה\nכמה כוחות הי ' משקיע כ \" ק אדנ \" ע במקוה זו עד שלפעמים הי ' ממהר\nלגמור תפילתו ופושט טלית ותפילין ומטפס ויורד לתוך הבור ונותן\nהוראות להפ ועלים , וגם לפעמים מסייע קצת בהמלאכה ובטח הי ' עושה\nאוצר לזריעה אם נצרכת , והנני יודע אשר באיזהו מקומן כן עושים ואולי\nבשביל הגאליציאנער או האונגארישער , ואנא יורני בזה כ \" ק אד \" ש ובכל\nמה שכתבתי לעיל .\"\nכ \" ק אדמו \" ר שליט \" א מחק את התיבות \" והנני שואל בזה האם \" וסימן -\nהשאלה , וסימן קו תחת התיבות \" יש מקום להידור בזה \"; וציין : (1 )\n[2 במכתבו כתב :]\nבמתיבתא . . מניחים כוחות הרבה על . . שלא יבוא ללמוד דא \" ח ,\"\nמתחילים לבטל אצלו בכלל עצם ענין החסידות ומגלים לו את החרמים\nהקדמונים שמזמני הגר \" א וכו ' ואח \" כ מורים לו החסרונות שאצלינו . .\nות \" ל שעד עתה לא פעלו עליו לרעה , לומד הנהו בהתמדה וגם חוזר על\nלימודו בינו ל בין עצמו , אך שמזמן לזמן אומר שמלימוד מסילות ישרים\nשלומד בינו לבין עצמו יש לו יותר תועלת .\nוזה לא כביר שואל אותי על ענין המחלוקת בין הפוסקים להמקובלים\nוכו ' מה שיש בשער - הכולל בשם ר \" ה מפאריץ וכו ', ושואל הוא וכן אחרים\nסוכ \" ס הרי כשיש מחלוקת בין הפוסקים להמקובלים הרי כפי שכתוב\nבשו \" ע שכלך אחר הפוסקים , ובאיזה צדק יכולים ללכת אחרי\nהמקובלים נגד דין מפורש בשו \" ע . ובפרט : המנהג המקובל אצל חסידים\nשלא לדלג בפסוד \" ז אפי ' להגיע למנין מפני הפיכת הצינורות בעת שעפ \" י\nדין אין לזה שום סברא , וכן אומר החכ \" צ בפי ' בתשובה אודות שאלה זו"],[9200110066,"66\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nהובא בהל ' תפי ' כ \" ה בשו \" ע , ואומר שם שאפי ' הרשב \" י והאריז \" ל דעתם\nכן אשר בעת שצריכים אניאגן להמנין כן לדלג , וא \" כ על מה אנו סומכים\nבהלכה שאין אנו מדלגים .\"?\nכ \" ק אדמו \" ר שליט \" א סימן קו תחת התיבות : \" בעת שצריכים \", וכתב :\n(2 ) – תמי ' גדולה קושיתו של הנ \" ל דוקא ע \" ז – שהרי אומרים\nשסומכים בהחלט בכל דבר על המשנ \" ב , והמשנ \" ב אומר שכן היא\nהנהגת הרבה אנשי מעשה ר \" ס נ \" ב ) וכן עיין שם בשע \" ת .(\nכנראה אמיתיית הטעם – ע \" פ מש \" כ בקו \" א דתניא סד \" ה לא טובה ,\nממשא \" כ בדורות הראשונים כו ' שעד \" ז הלך ופחת מדורות הכי\nאחרונים – לגבי דורות האחרונים , ובמילא מוכרחים גם פרטי התפילה\nוכו .'\nכדאי לשאול הנ \" ל – איך נוהגים אלו שהקשו הנ \" ל : אמירת מה טובו\nכו ' קטורת לפני מנחה , ובעיקר – המתחשבים 1 ) עם דעת הרמב \" ם\nשהמתפלל בלא כוונה צריך לחזור ולהתפלל הל ' תפילה פ \" ד הט \" ו )(\nשלפי פי ' חידושי ר \" ח הלוי ( לר \" ח בריסקער ) ה \" ז פסק קיים 2 ) עם\nפס \" ד המשנה הועתק בשו \" ע ( או \" ח רסצ \" ח ) שקודם כל תפילה צריך\nלחשוב מרוממות הא - ל 2 ) שפלות האדם 3 ) ויסיר כל תענוגי האדם\nמלבו .\nעד\nט ' שבט , תשכ \" א ][\nמענה להת ' ירחמיאל בנימין הלוי קליין שכתב : \" אתמול בלילה הלכתי\nלשיעור הקבוע בפנימי ' תורה - ודעת . והשתתפו שמונה תלמידים מגיל 19-\n23 , ולמדתי המאמר יו \" ד שבט תש \" י . והראו בפעם הזאת התעניינות\nגדולה יותר מפעמים הקודמים . . אחרי השיעור התועדו קצת לכבוד יו \" ד\nשבט והבטיחו לבוא במוצש \" ק לההתועדות \" ( תשורה גארדאן י \" א אלול\nתשע \" ח ע ' יח :)\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות : \" התעניינות גדולה\nיותר \", וכתב :\nת \" ח על הבשו \" ט"],[9200110067,"67\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nעה\nט \" ז שבט , תשכ \" א ][\nמענה להת ' ירחמיאל בנימין הלוי קליין שכתב : \" הנני להודיע שאתמול\nבלילה הלכתי להקביעות דא \" ח בישיבת תורה - ודעת . ולמדו אות ב '\nמהמאמר דיו \" ד שבט תש \" י . והשתתפו ה ' תלמידים כ \" י . ואחרי הלימוד\nחזרו מההתועדות דיו \" ד שבט ש . ז ., כמה מהם הי ' בההתועדות וגם\nהביאו עמהם כמה מחברי הם . הקונטרסים שלומדים בהם נשארים אצל\nא ' מהתלמידים , ויש תלמידים שלא יכולים לבוא להקביעות , הנה הם\nמבקשים מהתל ' שמשתתפים בהקביעות שילמדו עמהם , ממילא יש להם\nקביעות ביניהם ב ' פעמים בשבוע \" ( מצילום כתי \" ק – תשורה גארדאן י \" א\nאלול תשע \" ח ע ' יח :)\nויהא בהצלחה ובאופן דמוסיף והולך .\nעו\nמוצש \" ק משפטים , כ \" ו שבט , תשכ \" א ][\nמענה לר ' דובער בוימגארטען ( תשורה איידעלמאן ל \" ג בעומר תשס \" ו ע '\n36-38 :)\n[1 במכתבו כתב :]\n\" בליל ש \" ק הי ' שיעור בחומש רש \" י ואף שחזרתי שם שיחת שש \" פ –\nסיפור על הבעש \" ט והבלעכער היתום , והוספתי ביאור על מה שכן הי '\nשירת מרים והנשים בתוקף יותר גדול , מכ \" ק אד \" ש משיחות פ ' בשלח ,\nמ \" מ הרגשתי שלא בהצלחה וראיתי מיד שאין המקום עבורי אבל לחזור\nהביתה ג \" כ לא הי ' טוב . וכולם פליטי מלחמה , בנו להם בתים טובים\nוחפצים לשכוח מכ ל העבר ולהשתוות ככל האמריקנים ואולי גם להיות\nיותר אמריקנים מאמריקנים וזה מתבלט ברהיטים , טלוויזות , תלבושת ,\nדיבוריהם , כיבוד לפני ואחרי השיעור . .\nודברתי עם הר ' . . וראיתי שאינני לבד בהרגשתי זו וגם הוא מרגיש זו ,\nוביקשו ממני להכניס . . בשיעור כדי שכולם ישתתפו באופן פאזיטיווי\nבדיסקוסיא . . והפלא שא ' מהם הרב . . תל ' מנאווהארדאק ולמד בתורה\nודעת וחפץ חיים ובישיבה אוניברסיטה ורב בביהכנ \" ס כעשרה שנים\nוכעת של ח ידו במסחר – והתלוצץ כא ' הרקים וכו .\"'"],[9200110068,"68\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nמענה כ \" ק אדמו \" ר שליט \" א :\n(1 איפכא ( מסברתו ) מסתברא לי . כ \" ז הוכחה שצריך לדבר בפניהם .)\nוכדאי להשתדל שידבר שם עוה \" פ וחזקה לתעמולה כו ' והרי יש חומה\nומועילה ) מימינם .(\n[2 ] במכתבו כתב : \" עלה בדעתי עוד הצעה להיות שהתחיל שם להו \" ל\nהשיחות לנוער בספאניש , ועוד טרם שנעשה דבר ממש בהפצתם ממש ,\nשאעסוק בזה אני קודם בארגנטינה ואח \" כ בכל מדינות לאטין אמריקה ,\nלבד מברזיל . .\".\nמענה כ \" ק אדמו \" ר שליט \" א :\n(2 ) שייך להמל \" ח\n[3 ] במכתבו כתב : \" עד היום לא יצא עדיין שום החלטה מהשופט\nהוירלאנדס לביטול האינדאייטמנט נגד . . ובמילא עודנו תחת הבעל .\nקודם ש \" ק התדברתי עם וועבערמאן והחלטנו שהוא ידבר הרבה עם ר '\nמשה סוויסה נ \" י גיסו של השופט שימהר להוציא הדעסיזאן לטובת . .\".\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול תיבת \" שהוא \", וכתב :\n(3) בטח יזרזו עוה \" פ ע \" ז\n[ וראה לקמן מענות : קד , קח , קט , קיב , קטו , קיח .]\n[4 ] במכתבו כתב : \" ביום ג ' העבר בלילה נאמתי לפני אסיפת נשי חב \" ד\nבבראנקס , וחזרתי אותה השיחה דשש \" פ עם הביאור כמו כנ \" ל דחומש\nורש \" י , ואח \" כ סיפרתי מנסיעותיי . . ורצוף כאן מכתב מאחת השומעות\nשקיבלתי היום , ואגב איני יודע מה לענות לה ואולי היותר טוב שנתקשר\nעם המל \" ח א ו שאמסור להקאונסל שיטפלו בזה .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(4 ) המתחיל במצוה אומרים לו גמור\n[5 ] במכתבו כתב : \" בטח ראה אד \" ש הגליון מיאנג ישראל בו רוצים\nלנאום שם בפ ' זכור אודות הסיגניפיקאנס של חסידות במאדערן טיימס .\nושאלתי מאיפה לקחת חומר לזה , ובהיות שהי ' קשה לר \" ד רסקין למצוא\nמישהו שילך לשם על ש \" ק זה ובפרט בש \" ק ההוא להיותו סמוך לפורים\nבטח יתוועד אד \" ש עם העולם , אבל מכיון שזה מצוה עוברת והתבוננתי\nשבתור שליח הייתי צריך להיות מזמן במקום שליחותי אלא שמפני כמה\nסיבות לא זכיתי , וכאשר לשבת שלאחרי י ' שבט ציין כ \" ק אד \" ש שיהא\nנחשב כאילו , בטח גם בפעם הזאת יהי ' כן . ויה \" ר שאינני פתי און נאר זיך"],[9200110069,"69\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nניט אליין אפ בזה שהריני היחיד שעושה כזאת לנסוע מכ \" ק אדמו \" ר\nבדיוק כשהוא יוצא לעולם .\"\nכ \" ק אדמו \" ר שליט \" א מחק תיבת \" בטח \", וסימן קו תחת התיבות\nשיהא נחשב כאילו גם בפעם הזאת יהי ' כן \"; וציין :\" (5)\n[5 ] במכתבו כתב : \" לאור כל הנ \" ל הנני מאחל שיואיל נא כ \" ק אד \" ש\nלהוריני מה לעשות בעתיד ויברכני ברפו \" ש במהרה ובהסתדרות טובה\nבגו \" ר .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(6) אזכיר עה \" צ\n[7 על כללות המכתב , כתב כ \" ק אדמו \" ר שליט \" א :]\n(7 ) להחזיר המצורף\nעז\nכ \" ז שבט , תשכ \" א ][\nממענה להחתן הת ' ירחמיאל בנימין הלוי קליין על מכתבו ( קובץ \" מיין\nגענעראל \" ח \" א ע ' 16 :)\n(3 ) המשתדל ע \" ד הסתדרות ? והרי זמן החתונה בשטומו \" צ מתקרב .\nעח\nכ \" ז שבט , תשכ \" א ][\nמענה להחתן הת ' ירחמיאל בנימין הלוי קליין על מכתבו – בהמשך\nלהמענה שקיבל ( לעיל מענה עז ) ע \" ד ההסתדרות לאחר החתונה ( קובץ\nמיין גענעראל \" ח \" א ע '\" 16 . והעתקה , באדיבות מערכת הספר \" מיין\nגענעראל \" :)\n[1 במכתבו כתב :]\n\" הנה עד עתה לא השתדלתי מפני שחיכיתי לקבל הוראה מכ \" ק אדמו \" ר\nשליט \" א . ואולי יואיל כ \" ק אדמו \" ר שליט \" א לזכני להורות לי המקום\nאשר שליחות נפשי שם , אשר אנחנו ( אני והכלה ) מוכנים לכל שליחות\nבזמן ומקום בשמחה וטוב לבב ."],[9200110070,"70\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nובהתאם למענתו הקודם של כ \" ק אדמו \" ר שליט \" א אלי \" שצריכים\nלהציע מעצמם \" , הנה דברתי היום עם הרב חדוקוב שי ' שלעצמי אין לי\nשום הצעות , רק מה ששמעתי משך הזמן וגם שהציעו לי . ואמר לי\nשאכתוב ההצעות שהציעו לי משך הזמן . .\".\nעל התיבות : \" מפני שחיכיתי לקבל הוראה מכ \" ק אדמו \" ר שליט \" א \" –\nכתב כ \" ק אדמו \" ר שליט \" א :\n?! הרי [ מענתו הקודם של כ \" ק אדמו \" ר שליט \" א אלי \" שצריכים להציע\nמעצמם ]\"\n[2 במכתבו כתב :]\n\" א ) מתי שהי ' כאן הרב חנוך שי ' גליצנשטיין , הציע לפני לאחרי יציאתו\nמיחידות , היות שכ \" ק אדמו \" ר שליט \" א התלונן שחסר א ' שיעמוד בקשר\nעם כל אלו שעומדים בקשר או שבקרו אצל כ \" ק אדמו \" ר שליט \" א .\nב ) בחודש תשרי ש . ז . הציע לפני הרב חנזין שי ' שחסר לו א ' שיעזור לו\nבהנהלת הרשת באה \" ק .\nואולי יכול להיות ב ' הצעות הנ \" ל כהצעה א .\"'\nמענה כ \" ק אדמו \" ר שליט \" א :\n(2) שאלת צה \" ל ?\n[3 במכתבו כתב :]\nבזמן האחרון הציעו לפני האברכים שי ' מאוסטרלי ' שחסר שם א '\"\nבעבודת המל \" ח צאגו \" ח ומסיבות - שבת .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(3 הנוגע ידיעת אנגלית ?)\n[4 במכתבו כתב :]\n\" הנני לשאול היות שיש דירה עם רהיטים להשכיר . . וגם הנני יכול לצאת\nמשם בכל זמן שאצטרך , הכתובת הוא . . והנני לשאול אם נכון לשכור\nהדירה בשבילי .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(4 ) באם הנני יכול לצאת משם בכל זמן שאצטרך ][ וישר בעיני ב \" ג תי '"],[9200110071,"71\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n[5 ] במכתבו כתב : \" הנני לשאול אודות הניירות עבורי היות שהנני צריך\nלהראות שהתחתנתי כבר אם כדאי לסדר הנשואי - אזרחות מקודם ,\nמכיון שנפ \" מ רק בב ' שבועות .\"\nכ \" ק אדמו \" ר שליט \" א מחק תיבת \" אם \", וסימן בחץ את התיבות \" כדאי\nלסדר כו '\", וכתב :\n(5 ) – באם אין טרחא יתרה בדבר .\nעט\nיו \" ד אדר , תשכ \" א ][\nמענה לר ' שניאור זלמן הלוי דוכמאן על מכתבו ( מצילום כתי \" ק – ס '\nלשמע אוזן \" ( הוצאת תש \" נ ) ע ' טז , שלז :)\"\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את מה שכתב : \". . ואח \" כ ביקש\nאותי אז איך זאל צו זיי עפעס ריידען ואמרתי אז איך בין זייער צופרידען\nאז עס איז דורך 53 יאהר און איך טרעף זיך מיט זיי וכו ' וכו \"' – וכתב :\nת \" ח על הנח \" ר מידיעה זו .\nפ\nכ \" ד אדר , תשכ \" א ][\nמענה לר ' דובער בוימגארטען ( תשורה איידעלמאן ל \" ג בעומר תשס \" ו ע '\n38 :)\n[1 במכתבו כתב : \" יש בידי בקבוק משקה שזכיתי לקבל מידו הק ']\nבשמח \" ת ואז שאלני לאן ועניתי לבוענאס איירעס , והי ' נראה שכ \" ק\nאד \" ש מסכים בטוב ע \" ז אבל עד הנה לא יכולתי לנסוע מפני סיבות בלתי\nתלויות בי . מצדי הנני מוכן ומזומן לנסוע כמו שאמר כ \" ק אד \" ש\nבהתוועדות פורים . ואנ א יואיל כ \" ק אד \" ש להוריני מה לעשות עם\nהבקבוק הזה , האם מותר למכרה על חג הפסח ולהשתמש בה אח \" כ\nכשאסע בשעטומ \" צ או לשלחה בידי רפאל שי ' או מישהו אחר .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nא ) סימן בעיגול תיבת \" למכרה \", וכתב :(\n(1 ) מופרך לגמרי"],[9200110072,"72\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nב ) סימן קו תחת התיבות \" או מישהו אחר .\"(\n[ וראה לקמן מענה פב .]\n[2 ] במכתבו כתב : \" ויברכני שיגמר . . לטוב בטוב הנוהנ \" ג ואזכה למלא\nשליחותי ככוונתו הק ' מתוך הרחבה והרווחה .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(2) אזכיר עה \" צ\nפא\nכ \" ה אדר , תשכ \" א ][\nמענה לר ' דובער בוימגארטען שכתב : \" הנהלת צאגו \" ח מציעים לי ליסע\nלדטרויט על ש \" ק ויקרא הבעל \" ט , בבעל הארבור לא הייתי מפ ' תצוה .\nוהנני שואל אם להיות בבעל הארבור בשביל המקוה , או אולי מכיון\nשאהי ' שם שבת הגדול וימים הראשונים דחגה \" פ לא יזיק נסיעתי לשם \"\n( תשורה איידעלמא ן ל \" ג בעומר תשס \" ו ע ' 39 :)\n[1 ] על מה שכתב : \" הנהלת צאגו \" ח מציעים לי ליסע לדטרויט על ש \" ק\nויקרא הבעל \" ט \", כתב :\nנכון ליסע ][\n[2 על מה שכתב : \" לא יזיק נסיעתי לשם \"] – סימן בחץ ובעיגול את\nהתיבות \" לא יזיק .\"\nפב\nאור לכ \" ו אדר , תשכ \" א ][\nמענה לר ' דובער בוימגארטען ( תשורה איידעלמאן ל \" ג בעומר תשס \" ו ע '\n39 :)\n[1 ] במכתבו כתב : \" רצוף מכתב שקיבלתי היום מחברת יגדיל תורה\nחתום מר ' משה מוהדעב שאודותו כתבתי אתמול .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(1) להחזיר"],[9200110073,"73\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n[2 ] במכתבו כתב : \" כ \" ק אד \" ש לא ענה לי מה לעשות עם הבקבוק משקה\n[ ראה לעיל מענה פ ] האם למסרה בידי ר ' רפאל . . לשם או להשתמש בזה\nכאן בחודש ניסן ביום ב ' ניסן או י \" א ניסן הבעל \" ט , ואנא שיוריני בזה .\"\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות \" הבקבוק משקה ,\"\nוכתב :\n(2) סוף דבר\n[3 ] במכתבו כתב – בקשר לא ' ממקורביו : \" יצא מאת היחידות בשמחה\nוהנהו מרושם בטוב וכן אביו . אבל אביו יש לו א קליין קעפל ואינו כמו\nבניו , ויה \" ר שיצא הכל בטוב .\"\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות : \" א קליין קעפעל ואינו\nכמו בניו \", וכתב :\n(3 ההמשך ?)\nפג\nאור לכ \" ח אדר , תשכ \" א ][\nמענה לר ' דובער בוימגארטען ( תשורה איידעלמאן ל \" ג בעומר תשס \" ו ע '\n40-41 :)\n[1 ] במכתבו כתב : \" הנני רוצף כאן המכתב שקיבלתי היום מר ' יעקב ליפא\nבירמאן ששופך אור על כמה ענינים של בוענאס איירעס . העיקר מה\nשכותב אודות החלטתם לקבלני בתור מנהל של . . אך שמפקפקים האם\nמתאים הנני למשרה זו וכו ' והאמת הוא אשר הנני מוצא את עצמי במאד\nמתאים למשרה ז ו , אך לטובת הענין כמדומני שיותר נכון שיהללוני זרים\nעד \" מ בנימין קליין ושמואל פסח באגמילסקי , ובהיות כאן ד \" ר\nהייברמאן , הרב שפירא , מר . . על עסק מר ' . . עם כולם דיברו בנימין\nקליין ושמואל פסח וישבחוני ויהללוני ואחכ \" ז מפקפקים , כנראה\nמהמכתב .\"\nעל התיבות \" מה שכותב \", כתב כ \" ק אדמו \" ר שליט \" א :\nהאם ( זהו ) מכ ' אופיציאלי שלהם !? ( 1 )\n[2 ] במכתבו כתב : \" והנה מהמכתב אין ברור האם זה 15 אלפים ( פסו )\nלחודש או 20 וזהו נפק \" מ על יותר מחמישים דולר , ומה עלי לעשות\nכעת .\""],[9200110074,"74\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nמענה כ \" ק אדמו \" ר שליט \" א :\n(2 אויסדינגען מה שאפשר אבל בכל אופן אין החילוק כספי זה מעכב .)\n[3 ] במכתבו כתב : \" בעניני . .: הנה כבר הודעתי אשר בקיץ עוד לפני\nנסיעתי לאיטלי ' עבור האתרוגים אמר לי ר \" מ טייטלבוים שיש בידו\nפתקא מ . . מש \" כ מקדמת דנא , האם הענין עודנו בתקפו עומד ואמרתי\nשכן , ואמר שיגש תומ \" י להעבודה וכו ' אבל עס האט זיך געשלעפט הרבה\nעד לפני כחוד ש בעיקר . ובסמיכות לפורים כפה \" נ התדברו . . ואח \" כ\nצריכים לחכות עוה \" פ זמנים טובים , כמדומני אם הי ' להם אתעדל \" ת\nעד \" מ מהרב חודוקוב שם היו ממהרים את הענין יותר . אין . . טענות\nעליהם שהרי כ \" א מהם יש לו כו \" כ ענינים , אבל מכיון שכ \" פ לא הצליחו\nאינם ממהרים . ובפרט שמדובר אודות נסיעה יותר מעיק . . הענין שאינו\nיודע מה לעשות .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(3 יזרזם הוא עכ \" פ ( ומובן שיאמר להם שעושה כן ע \" פ הצעתי .))\n[4 ] במכתבו כתב : \" אנא יורני כ \" ק אד \" ש איך ומה לעשות אם בכלל נכון\nלנסוע על הוצאות בלתי שלהם , כעת שם ספאניש בבוקר ולימודי קודש\nאחה \" צ , זו \" ן יחד , תלמידים מהלכים בגילוי ראש וכו ' האם עלי להתנות\nתנאים מקודם .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(4 תלוי בזה , וואס קען מען אויספירעהן .)\n[5 במכתבו כתב : \" כן יואיל נא כ \" ק אד \" ש להשים דברים בפי לענות לר ']\nי \" ל בירמאן אודות טל ומטר שם והענין נוגע גם לו בהיותו שם וכן לאהרן\nטוויל . במדינת ברזיל החליטו חכמי הטבע אשר צריכים למטר כל השנה\nכולה , ובארגנטינה בצפון המדינה דומה לברזיל , אבל בבוענאס איירעס\nוהס ביבה דומה לניו יורק רק שהכל להיפך כשכאן חורף שם קיץ , ובמילא\nבזמן שצריכים כאן מטר א \" צ שם , כשקיץ כאן שם צריכים מטר .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(5 ) כמה שו \" ת יש בזה ושייך לרב .\n[5 על כללות המכתב , כתב כ \" ק אדמו \" ר שליט \" א :]\n(6 להחזיר המצורף .)"],[9200110075,"75\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nפד\nאדר , תשכ \" א ][\nמענה להת ' משה יחיאל פעלער שביקש ברכה עבור כמה מבני משפחתו\nשאינם בקו הבריאות ( קובץ הערות התמימים ואנ \" ש מאריסטאון ש \" פ\nפקודי תשמ \" ט ( גליון תרי ) ע ' 24. אגרות - קודש ח \" כ ע ' קצה :)\nלפלא אַז מ ' רעט און מ ' רעט וכשמגיע לפועל – כאו \" א חושב שהכוונה\nלמי שהוא אחר לא אליו !\nכו \" כ פעמים מובא פתגם - הוראת רבות י נו נשיאנו טראַכט גוט , וועט זיין\nגוט ( שהכוונה שהמח ' תועיל בזה ) – ובהיפך מזה \" ממציא \" מחשבות\nבאופן הפכי , ולמרות שנמצאים בחודש אדר שנצטוינו להרבות בשמחה ,\nשרוי בעצבות ( עיין תניא בזה ) וכו .'\nוחותמים בדבר מלכות : טראַכט גוט וועט זיין גוט – בנראה ו ב נגלה .\nפה\nשלהי אדר , תשכ \" א ][\nמענה להחתן הת ' ירחמיאל בנימין הלוי קליין ( מצילום כתי \" ק – תשורה\nנפרסטק כ \" ב סיון תשע \" ח ע ' 4-5 :)\n[1 ] במכתבו כתב שלמרות שביקש מאביו לבוא לחתונתו המתקיימת בניו\nיארק , הנה אין ביכולתו לבוא , מה שפעל הרבה על בריאותו של האב .\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות : \" בקשתי שיבוא על\nחתונתי \", וכתב :\n?\nהמצא היתר בזה ( ליציאה מאהקת \" ו ) ע \" פ שו \" ע ?\n[2 במכתבו כתב שאף אחד ממשפחתו לא ישתתף בחתונה .]\nמענה כ \" ק אדמו \" ר שליט \" א :\nע \" פ דברי רבותינו נשיאינו מייסדי ומנהלי תו \" ת כל הת ' ור \" מ ור \" י\nדתו \" ת הם משפחתו ."],[9200110076,"76\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nפו\nמוצש \" ק ויקרא , ר \" ח ניסן , תשכ \" א ][\nמענה לר ' צבי מאיר שטיינמעץ על מכתבו בו גולל בארוכה את פרטי\nהאירועים שקדמו לחתונת בתו וחתנו לאזאר ( ראה לעיל מענות יח - יט ) ,\nאשר אינם נותנים לו מנוח עד עתה ( תשורה זלמנוב אדר \" ח אדר תשע \" ג\nע ' 58 קונטרס ועד הנחות בלה \" ק ש \" פ קרח תשע \" ד ע '. 14-15 :)\nאזכיר עה \" צ להנ \" ל ולביטול כל קושיות כו ' – כ \" א כמו שהוא מסטרא\nדאילנא דחיי יעויין דברי משה רבנו רע \" מ והאריך באגה \" ק לאדה \" ז סי '\nכ \" ו\nפז\nב ' ניסן , תשכ \" א ][\nמענה לר ' ירחמיאל בנימין הלוי קליין שכתב :\n\" הרב חדוקוב שי ' מסר לי היום הוראת כ \" ק אדמו \" ר שליט \" א אודות\nהסתדרותי בזמן שהותי כאן .\nא ) אודות חצי היום הא ' לקביעות במקצוע בתורה . והנני חושב ללמוד\nהל ' מקואות כפי שהזכיר כ \" ק אדמו \" ר שליט \" א . והנני חושב לדבר עם\nהרב הרליג אודות שילמוד עמי .\nב ) אודות חצי היום הב ', הנה הציע לי הרב חדוקוב שי ' שאתעסק על משך\nהג ' חדשים במשרד המל \" ח , ובהשקפה ראשונה העבודה הוא לסדר\nהתיקים בהמל \" ח וגם ההתעסקות בעניני צאגו \" ח ומסיבות - שבת . .\nבשבוע העבר הציע לי הרמ \" ל שי ' ראדשטיין שאתעסק בעבודת כולל -\nחב \" ד . וכפי הנראה העבודה בלי תוכן . וגם העבודה בלי סכום שעות , אלא\nכמה שעות שארצה , ואודות שכירות עדיין לא דיברו . אבל הנני חושב\nשבהצעה זו הזמן מתבטל ( ווערט צוריבען ) ביותר מכיון שאין השעות\nקבועות וגם שאין תוכן בהעבודה , וגם שבההצעה הא ' יכול להיות\nשהשכירות פחות , אבל השימוש שמגיע מזה על להבא משתלם .\nוהנה בשאלתי מה לעשות .\nאשתי לאה בת העניא חאשע שתחי ' מתחילה מחר לעבוד בב ' המשרות\nשהי ' לה . א ) בבית רבקה . ב ) ת \" ת אהבת אחים .\""],[9200110077,"77\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – תשורה שייקביץ ז ' אלול\nתש \" פ ע ' 15 :)\n(1 ) בכלל נכון . ע \" פ מרז \" ל במקום שלבו חפץ – גם בהנ \" ל יעסוק א ])[\n(2 לכה \" פ ד ' שעות ביום .)\n(3) א ) בבית רבקה . ב ) ת \" ת אהבת אחים ][ ויהא בשטומו \" צ\n(4 ) מקרן תורה – - 25 $ לשבוע .\n[ וראה לקמן מענה פח .]\nפח\nג ' ניסן , תשכ \" א ][\nמענה לר ' ירחמיאל בנימין הלוי קליין שכתב : \" בהתאם למענתו של כ \" ק\nאדמו \" ר שליט \" א \" בכלל נכון וכו '\" [ לעיל מענה פז הנה לא זכיתי להבין ,],\nאם המענה הוא רק על חצי יום הא ' או ג \" כ על חצי יום הב '\" ( מצילום\nכתי \" ק – תשורה שייקביץ ז ' אלול תש \" פ ע ' 15 :)\nכ \" ק אדמו \" ר שליט \" א מחק תיבת \" או \", וסימן בחץ ובעיגול את התיבות\nג \" כ על חצי יום הב .\"'\"\nפט\nח ' ניסן , תשכ \" א ][\nממענה להרב יצחק דוב אושפאל על מכתבו ( ס ' \" שבח יקר \" ע ' 197-198 .\nתשורה שמוקלער ב ' אייר תשפ \" א ע ' 5 :)\n.[ ]. ב ) בכלל בעריכת ב \" מ – אין דעתי נוחה ומכמה טעמים – מזה\nשהב \" מ עובר לפני התיבה , ומזה שהוא הבעל קורא בתורה , וכן בענין\nבזבוז ממון על האל וכיוצא בזה\nעל הנכון וטוב אמירת ד \" ת ( ולא שפיטש וכו )'\nהזכרתיו על הציון ."],[9200110078,"78\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nצ\nיום הבהיר י \" א ניסן , תשכ \" א ][\nמענה לר ' שניאור זלמן הלוי דוכמאן על מכתבו ( ס ' \" לשמע אוזן \" ( הוצאת\nתש \" נ ) ע ' טז :)\nובת \" ח על שהתחיל עוה \" פ בשילוח ר \" ד .\nצא\nיום הבהיר י \" א ניסן , תשכ \" א ][\nמענה לר ' יוסף מנחם מענדל טענענבוים שכתב :\n\" הנני בזה להודיע לכ \" ק כי בהתאם להוראת כ \" ק נסתדר התועדות –\nמסיבות יום טוב – על יום ב ' דחג עבור התלמידים דהישיבה בשכונות . .\nהתועדות עבור תלמידי המתיבתא , ביום ב ' א ' דחול המועד , בבית\nהמדרש כ \" ק אדמו \" ר שליט \" א , המתועדים הרד \" ר והרי \" כ שי '. ביום ג '\nב ' דחול המועד בשעה 3 , התועדות מהרמי \" ם והמשפיעים עם הנהלת\nהישיבה ( בחדר שני של הבית המדרש או בחדר הרש \" ל שי .)'\nהוכן – על חשבון קופת בחורים – בערך 40 פונט מצות , לחלק זיתי\nשמורה ( ד ' מצות לכל אחד ) להתלמידים שאין להם מצות שמורה בביתם ,\nוט ' פונט מצות – על חשבון צא \" ח – לחלק להמורים המלמדים מקצועות\nהחול העלעמנטרי וההיי - סקול ולהשוטר מר ווילעט ( ו ' מצות לכל אחד\nואחד ). נתחלקו – מטעם המל \" ח – הגדות קטנות לכל התלמידים שי '\nשעשה עליהם רושם טוב ביותר . .\nוהנני מצרף עצמי עם המברכים את כ \" ק אדמו \" ר שליט \" א בברכת מזל\nטוב לאריכות ימים ושנים טובות והצלחה אלקית מופלגה בכל עניניו\nהקדושים .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( ס ' \" תולדות התמימים בארצות הברית \" ע '\n570-571 :)\nויה \" ר שיהי ' כהנ \" ל בהצלחה בכמות ואיכות ."],[9200110079,"79\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nצב\nכ \" ג ניסן , תשכ \" א ][\nמענה לר ' אברהם זושא זיסקינד שכתב : \" בתורת שמואל תרכ \" ו ד \" ה כל\nהולך על גחון ( דף עב ) מבאר ההפרש בין קו הימין והחסד לגבורות ,\nשמהגבורות בריבוי ההשתלשלות יכול להיות איזה יניקה וכו ' ולכן\nמיצחק יצא עשו אפי ' אחר שנימול אבל מחסדים לא יכול להיות יניקה ,\nומה שמאברהם יצא ישמעאל זהו קודם שנימול . וצ \" ע הרי בני קטורה\nוהם פסולת , ובפרט מדין כמבואר בקונט ' החלצו , והן נולדו אחר שנימול \"\n–\nנדפס באגרות - קודש ח \" כ ע ' רלה .\nצג\nכ \" ו ניסן , תשכ \" א ][\nמענה לר ' יוסף מנחם מענדל טענענבוים שכתב :\n\" הנני בזה למסור לכ \" ק דו \" ח מההתועדויות עם התלמידים הצעירים\nביום ב ' דחג ( בכללות כבר הודעתי ע \" י הרב חדקוב שי '), תודה לה ' שהי '\nבהצלחה . .\nא ' דחול המועד התוועד הרב יואל כהן שי ' עם תלמידי המתיבתא וחזר\nלפניהם השיחות קודש בליל פסח .\nבהתוועדות הרמי \" ם ביום ב ' דחול המועד . . המתועד הרש \" ל שי '; תוכן\nהמדובר : המעלה של תומכי תמימים והאחריות והזכות של הרמי \" ם\nוהמדריכים ואשר צריכים לנטוע בהתלמידים יראת שמים וחסידות\nוהתקשרות וכו '. בכלל היה באופן פון א חסידישען פארברענגין , והשי \" ת\nיתן שיבוא אין א פ ועל ממש .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( ס ' \" תולדות התמימים בארצות הברית \" ע '\n571-572 :)\nת \" ח על הבשו \" ט ."],[9200110080,"80\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nצד\nי \" א אייר , תשכ \" א ][\nמענה לר ' יוסף מנחם מענדל טענעבוים שכתב :\n\" הנני בזה להודיע לכ \" ק ע \" ד הבחינה ביום ג ' ע \" י הרבנים טייטעלבוים\nוגרינבערג שי ', בחנו החמשה מחלקות דמתיבתא , ות \" ל שהיו שבעים\nרצון מאד , הן מידיעתם והן מהבנתם של התלמידים שיחיו , כפי\nשהתבטאו \" זיי האבן גוט געלערינט און ווייסען גוט \". הרב גרינבערג בחן\nאותם גאנץ שווע רליך מיט א פולע ר ' עקיבא איגר ' ס . .\nכידוע כבר לכ \" ק נסתדר עוד מהתחלת החורף , אשר בכל יום ה ' מתעכבים\nהרבה תלמידים עירוניים דמתיבתא אחרי הסדרים של הישיבה ואוכלים\nארוחת הערב בהישיבה , ואח \" כ לומדים בערך שעה וחצי ( ביחד עם\nתלמידי הדארמיטארע לומדים בכל שבוע בערך 80-70 תלמידים כן\nירבו ), אח \" כ אומר אחד מ התלמידים פלפול לפני כולם 30-20 מינוטן\nבערך , אשר זה עושה רושם טוב ביותר . בזמן האחרון מודיעים מקודם\nמי מהתלמידים שיאמר וגם מראה מקומות , והנני שולח לכ \" ק קאפיעס\nמהג ' שבועות של אחר החג . התלמיד יעקב שי ' קראנץ משתתף בכל שבוע\nומסייע להתלמידים באמירת הפלפול .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( ס ' \" תולדות התמימים בארצות הברית \" ע '\n474 , 574-575 :)\nת \" ח על הבשו \" ט .\nצה\nלאחר ש \" פ אחו \" ק , י \" ג אייר , תשכ \" א ][\nמענה להמניחים על שאלתם בהמדובר במאמר ד \" ה קדושים תהיו\nשנאמר בש \" פ אחרי - קדושים י \" ג אייר בחדרו הק ' לפני התפלה ( מצילום\nכתי \" ק – תשורה חאנין ב ' ניסן תשע \" ז ע ' 231-232 :)\n[1 במכתבם כתבו :]\n\" נתבאר בהמאמר ההפרש בין עבודת הצדיקים – לעבודת הבע \" ת . אח \" כ\nנתבאר ההפרש בין אתכפיא לאתהפכא , שזהו ג \" כ ההפרש בין פסח\nראשון לפסח שני , שבפסח ראשון אסור להיות חמץ בפסח , כי ענין פסח\nראשון הוא בחי ' כי ברח העם , בדרך בריחה , שצריך לברוח מהרע ולצעוק"],[9200110081,"81\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nאי אפשי . משא \" כ בפסח שני , חמץ ומצה עמו בבית , כי חודש אייר הוא\nחודש זיו , שכבר נהפך הרע כו ' וצריך לומר אפשי ואבי שבשמים גזר עלי .\nשאלה : אם הכוונה שאתכפיא הו \" ע עבודת התשובה , ולכן פסח ראשון\nשהוא בדרך בריחה מהרע , צריך לומר אי אפשי , כמאמר המגיד בענין\nבע \" ת , ואתהפכא הו \" ע עבודת הצדיקים , ולכן בפסח שני , אתהפכא , צריך\nלומר אפשי כו .\"?'\nכ \" ק אדמו \" ר שליט \" א מחק תיבת \" הו \" ע \", וכתב :\nהכוונה שאתכפיא ][ בערך לאתהפכא הוא ע \" ד העילוי ד עבודת התשובה ][\nאבל בכללות גם אתהפכא זו הוא בעבודת הבינונים עדיין .\n[2 במכתבם כתבו :]\nנתבאר בענין ספה \" ע שסופרים יום אחד , אבל נשאר הימים שלאחריו ,\"\nוצריך עדיין לבררם .\nשאלה : ( א ) לאיזה ענין נאמר זה ? ( ב ) הרי לכאורה זה דומה לאתכפיא ,\nשנשאר עדיין רע וצריך לבררו , וא \" כ מהו השייכות דספה \" ע לחודש אייר\n( שנתבאר בשיחות הקודמות , שניסן הו \" ע יצי \" מ , ואייר ספה \" ע ) שהוא\nבחי ' אתהפכא .\"?\nמענה כ \" ק אדמו \" ר שליט \" א :\n( א ) מחק את התיבות : \" אחד \", \" אבל \", \" ו צריך )( וכתב :\";\nנתבאר בענין ספה \" ע שסופרים ][ ומבררים ( כי עוד לא נתהפך ונעשה\nצדיק .[ ]. וביותר שהרי נשאר ][ ו הימים שלאחריו ][ ש צריך עדיין לבררם ][\nב ) על התיבות : \" שהוא בחי ' אתהפכא \", כתב :(\nבאופן הגילוי , מלמעלה – ניסן כולו חודש הגאולה ( שהייתה מבכבודו\nובעצמו )\nאייר כולו ספה \" ע ( עבודת האדם ) כולו – זיו לא עצמות ) ר \" ת המרכבה ,(\nעבודת האבות שנמצאו והמשיכו לכאו \" א . ואח \" כ סיון – מ \" ת . אתדל \" ע ,\nאתדל \" ת , אתדל \" ע . משכני נרוצה ( ל ' רבים ) הביאני\n[ באופן ] עבודת האדם [ ניסן ] אתכפיא – אייר אתהפכא – כמבואר\nבלקו \" ת ר \" פ במדבר ."],[9200110082,"82\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n[3 במכתבם כתבו :]\n\" נתבאר שישראל הוא בחי ' אות ו ', ובחי ' ו ' כשכלול מיו \" ד פעמים יו \" ד\nהוא ששים רבוא , שאז קיבלו את התורה .\nשאלה : אם זה ביאור לענין קדוש ישראל שנמשך ע \" י התשובה , או שזהו\nבחי ' ישראל שנמשך ע \" י הצדיקים ) ובחי '( קדוש ישראל ( שנמשך ע \" י\nהתשובה ) הוא למעלה מבחי ' ישראל .\"?\nכ \" ק אדמו \" ר שליט \" א מחק את השאלה , וכתב :\nזה ביאור ][ בקיצור לענין ][ שורש ותוספת גודל ענין הבחי ' אף שרק בסוד\nשורש\nשמזה מובן גודל התוס ' שבא – לאח \" ז דגודל הנ \" ל .\n[ דמספר ס \" ר – הוא מספר השלם ( שלכן קבלו אז התורה ). אבל בעצם\nהוא מספר ששה ( ולא עשר ), דמה דישראל ( ז \" א ) הוא ו \" ק , זהו בסוד\nשרש ( בלא התוס ') וע \" ז ולאח \" ז באה הברכה יוסף ה ' עליכם ככם אלף\nפעמים ] וגודל התומ \" צ והצדיקים ( המביאים את התוס ') והשמחה\nשעי \" ז . ויספו ענוים בה ' ( שבו ז \" א באות וא \" ו ששה .)\n[4 במכתבם כתבו :]\nנתבאר בענין התשובה שענינה לאשתאבא בגופא דמלכא .\" – נאמר איזה\nפירוש על התיבות בגופא דמלכא אין זוכרים מה .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nבערך עבודת הצדיקים : לגדולתי ולקדושתי – בערך גדולתכם\nוקדושתכם ( ב \" ר פ \" צ ויק \" ר קדושים ס \" פ קדושים .)\nצו\nל \" ג בעומר , תשכ \" א ][\n\" צעטל \" בכתי \" ק שכתב כ \" ק אדמו \" ר שליט \" א – ביום ל \" ג בעומר לאחר\nשחזר מהאהל – והורה לפרסם בכל מקום ( ס ' \" משבחי רבי \" ע ' 122 .\nתשורה בלעסאפסקי כ \" ג טבת תשפ \" א ע ' מה . רשימת א ' התמימים :)\nהמנצלים ( הניצלו ) יום סגולה ושמחת רשב \" י זה להתחלת ביסוס\nהרחבת מבצעים פעולות וענינים כללים ופרטים"],[9200110083,"83\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n[ במענה לשאלת המזכיר הרחמ \" א חדקוב לפירוש הדברים – ענה כ \" ק\nאדמו \" ר שליט \" א : \" אויב מ ' וועט פרעגן פשט , זאלט איר ענטפערן אז איך\nווייס אויך ניט , און מיר באדערט דאס ניט .]\"\nצז\nועש \" ק אמור , י \" ט אייר , תשכ \" א ][\nמענה לר ' יוסף מנחם מענדל טענענבוים שכתב : \" הנני בזה להודיע לכ \" ק\nכי אתמול הלכו כל התלמידים עם מוריהם לפראספעקט - פארק כנהוג .\nהתלמידים הקשישים דמתיבתא התועדו עמהם הר \" י כהן והרח \" מ\nבוקעט שי ' משעה 2 עד שעה 6 בערך . גם אני נוכחתי משך זמן . דברי כ \" ק\nבהנוגע לל \" ג בעומר [ לעיל מענה צו ] נמסר לנו באמצע ההתועדות , האט\nמען דאס אויסגענוצט בעת ההתועדות על ענין של אהבת רעים ואהבת\nישראל והתעסקות של א ' עם חברו ושקידה ומסי \" נ לתורה ותפלה \" ( ס '\nתולדות התמימים בארצות הברית \" ע '\" 575 :)\nת \" ח על הבשו \" ט .\nצח\nלאחר ש \" פ בהו \" ב , כ \" ז אייר , תשכ \" א ][\nמענה להמניחים על שאלתם במאמר ד \" ה רפאני גו ' שנאמר בהתועדות\nש \" פ בהר - בחוקותי ( מצילום כתי \" ק – ריש תו \" מ התועדויות ח \" ל\nתשכ \" א ח \" ג :))(\n[1 ] במכתבם כתבו : \" שאלה בכמה ענינים שלא זכרו בשעת חזרת המאמר\nרפאני תשכ \" א .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n– יעוין ד \" ה זה דשנת תרח \" ץ ( קונ ' לו .)'\n[2 במכתבם כתבו :]\n\" ג ' הפסוקים דאיתן ( משכיל לאיתן , והאיתנים מוסדי ארץ , וצדקה כנחל\nאיתן ), שהו \" ע המשכת איתן בכל הג ' מדריגות דתומ \" צ ( השגה , מדות\nומעשה .)"],[9200110084,"84\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nאם ענין זה נאמר בתחילה , כשדובר בענין המשכת אתה הוא הוי ' לבדך\nשצריך להיות ההמשכה בעשי ', שההמשכה היא ע \" י תומ \" צ . ועל זה\nנתבאר , שאיך ממשיכים ע \" י התומ \" צ מבחינה זו , לפי שהתומ \" צ היא\nמצד איתן שבנשמה , ובחי ' איתן מגיע בבחי ' אתה הוא הוי ' לבדך . או\nשענין זה נאמר אח \" כ , בפירוש הפסוק רפאני , בענין עבודת התשובה .\"\nכ \" ק אדמו \" ר שליט \" א מחק את התיבות : \" או שענין זה נאמר אח \" כ ,\nבפירוש הפסוק רפאני , בענין עבודת התשובה \"; ועל התיבות \" ענין זה\nנאמר \", כתב :\nבביאור איך ישראל מגלים את המקו \" ח\n[3 ] במכתבם כתבו : \" מהו פירוש הושיעני ואושעה , שנתבאר בהמאמר\nשהוא מלשון וישע הוי '. מהו \" ע ההמשכה דוישע . ואם המשכה זו היא\nלמעלה מענין התשובה , רפאני .\"?\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול קטע זה , וכתב :\nמובן מענינם בספירות : תומ \" צ – ע \" ס . רפואה – אריך ( והעלה ארוכה ,\nר \" ת כי אני ה ' רופאך ) ישועה – ש \" ע נהורין ד ) ע \" ק . קדושתי שלמע '(\nועוד יותר מזה – הושעני ואושעה\n[4 ] במכתבם כתבו : \" מה שמסיים בהפסוק כי תהלתי אתה , אם הוא טעם\nשלכן רפאני ( ואיך הוא הטעם על זה ?), או שהוא המשכה שבאה אחרי\nההמשכה שמלמעלה דרפאני , ואחרי עבודת המטה וארפא , ואח \" כ נמשך\nכי תהלתי אתה , וע \" ד המשכת מ \" ת שנמשך אחרי יצי \" מ ( רפאני ) ואחרי\nספה \" ע ( וארפא .\")\nכ \" ק אדמו \" ר שליט \" א מחק את מה שכתבו : \" או שהוא המשכה . . ואחרי\nספה \" ע ( וארפא )\"; ועל מה שכתבו : \" אם הוא טעם שלכן רפאני ( ואיך הוא\nהטעם על זה ?)\", כתב :\nכיון שתהלתי – ענינה לגלות עד ( ע \" ס הגנוזות כו ') העלם העצמי שיהי '\nאתה ( גילוי , מלא ה )"],[9200110085,"85\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nצט\nלפני כ \" ד אייר , תשכ \" א ][\nממענה להת ' משה יחיאל פעלער ( תשורה פעלער י \" ז מנ \" א תשפ \" א ע ' 7 :)\n[1 ] במכתבו כתב – בקשר למצב אמו : \" דברתי היום עם אבי שי ' והגיד\nאבי שדיבר עם Hay Dr. וכבר ראה Hay הידיעות שמסרתי לאבי\nממעמוריעל הוספיטול והגיד הוא שלא חשב להזריק הקעמיקל עד גמר\nה - X-Rays . והגיד Hay שה - 60-X-Ray Cobalt הי ' בהצלחה באמי\nשתליט \" א , שברור שנתקטן ה - Tumor. לקחו עוד צילום על ה - Chest\nהיום ונותנים לאמי שתליט \" א Intravenous Liquids .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(1 ) בכגון דא – עיקר ההטבה באה ורואים אותה כעבור כמה ימים\n[2 ] במכתבו כתב ע \" ד שידוך שהוצע לו , ושאל : \" באם נכון עבורי להתענין\nבההצעה הנ \" ל .\"\nכ \" ק אדמו \" ר שליט \" א סימן קו תחת התיבות : \" נכון עבורי להתענין\nבההצעה הנ \" ל \", וציין : (4 )\n[3 ] במכתבו כתב : \" מצד המצב של אמי שתליט \" א ואחותי תי ' הייתי יכול\nלדחות את זה במחשבתי , אבל היות שבנוגע להמצב של שניהם הורה כ \" ק\nאד \" ש טראכט גוט וועט זיין גוט – בנראה ונגלה [ לעיל מענה פד ] . .\".\nמענה כ \" ק אדמו \" ר שליט \" א :\n(5 אזכיר עה \" צ .)\nק\nכ \" ד אייר , תשכ \" א ][\nממענה להת ' משה יחיאל פעלער ( תשורה פעלער י \" ז מנ \" א תשפ \" א ע ' 7 :)\n[1 ] במכתבו כתב – ע \" ד אחותו , בקשר לפטירת אמו ע \" ה : \" וגם היא תרצי\nלנסוע על הבית עולם וכו ' ולכאורה פשוט שאין נכון הנ \" ל . .\".\nכ \" ק אדמו \" ר שליט \" א מחק תיבת \" ולכאורה \", וסימן בחץ ובעיגול את\nהתיבות \" פשוט שאין נכון הנ \" ל \", וכתב :"],[9200110086,"86\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n(1 ) לאחרי שידעו פס \" ד מרב מתי להודיעה באופן שיהי ' מינימום דענין\nשבעה \"\" – יתיעצו עם דר . מור איך להודיעה לאט לאט\n[2 במכתבו כתב : \" אבי שי ' לא יכול להתעכב זמן רב בנ . י . ורצונו שיהי ']\nענין של \" ווארט \" קודם שישוב למיניאפוליס , אבל נחוץ לי לדעת הוראת\nכ \" ק אד \" ש על הענין דאפשר זה היילידיג ביותר .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(3 ) ענין של \" ווארט ]\"[ אפילו באם אפשר יהי ' לברר דעת הצד השני בזה\nעד אז – הנה זה היילידיג ביותר ][\n[3 ] במכתבו כתב : \" הגדתי לו ג \" כ שבטח היא לא תכעסי על עצמה או\nעלינו היות שההעלמה הי ' הוראת כ \" ק אד \" ש וגם זה דין מפורש ביו \" ד\nשאין מגידין לבת .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(4 ) יסבירו לה אשר זה דין מפורש ביו \" ד שאין מגידין לבת ][ ובמילא\nמוכרחים היו לעשות כנ \" ל ופשוט שדוקא הנהגה ע \" פ שו \" ע – היא רצון\nוטובת הנפטרת\n[4 ] במכתבו כתב : \" תקותי שהמזכירות יקראו לי לביתי . . להגיד לנו\nהוראת כ \" ק אד \" ש כדי שנדעו מזה בהקדם .\"\nכ \" ק אדמו \" ר שליט \" א סימן בחץ ובעיגול את התיבות : \" המזכירות\nיקראו כו .\"'\nקא\nתחלת סיון , תשכ \" א ][\nמענה להת ' משה יחיאל פעלער ( תשורה פעלער י \" ז מנ \" א תשפ \" א ע ' 8 :)\n[1 ] במכתבו כתב : \" משפחת לו שי ' רוצים עכשיו לדעת ממני מה עלינו\nלעשות עכשיו – ווארט או תנאים , אז הנני מבקש הוראת כ \" ק אד \" ש\nבנוגע לזה .\"\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות \" לעשות עכשיו \", וכתב :\n(1 ) כמנהג אברכי אנ \" ש שי ' בזה"],[9200110087,"87\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n[2 ] במכתבו כתב : \". . אבל מסתם אין כ \" ק אד \" ש רוצה שאהי ' במחלוקת\nעמו כמו שאין כ \" ק אד \" ש רוצה שאהי ' במחלוקת עם הבעלי בתים\nהצעירים .\"\nכ \" ק אדמו \" ר שליט \" א סימן קו תחת התיבות : \" אין כ \" ק אד \" ש רוצה\nשאהי ' במחלוקת עמו כמו שאין כ \" ק אד \" ש רוצה שאהי ' במחלוקת עם\nהבעלי בתים הצעירים \", וכתב :\n(2 ) כמובן\nקב\nלאחר יום ב ' דחג השבועות , תשכ \" א ][\nמענה להמניחים על שאלתם במאמר ד \" ה ואהי ' אצלו אמון גו ' שנאמר\nבהתועדות יום ב ' דחג השבועות ( מצילום כתי \" ק – ריש תו \" מ התועדויות\nחל \" א ( תשכ \" א ח \" ג :))\n[1 ] במכתבם כתבו : \" נתבאר על הפסוק קול דודי גו ' שהוא בחי ' קלא דלא\nאשתמע , וקלא דלא פסיק , קול שלמעלה מהשתל ', ומ \" מ כתיב מדלג\nומקפץ ברגל , לפי שגם המשכה שלמעלה מהשתל ', נמשך ע \" י בחי ' רגל ,\nבחינה התחתונה ( וע \" ד שגם באור שקוה \" צ נמשך מבחי ' מל ' דמל '). ויש\nבזה ב ' מדריגות : מדלג ברגלו אחת , שההמשכה היא רק בחי ' רגל , ומקפץ\nבב ' רגלים , שעי \" ז נעתק בכל גופו . והם בחי ' מקיף הקרוב ומקיף הרחוק ,\nומצד המשפיע הוא בחי ' מקיף הישר ומקיף החוזר , אור שבגדר גילוי\nועצם האור .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nא ) על מה שכתבו : \" לפי שגם המשכה שלמעלה מהשתל ', נמשך ע \" י בחי '(\nרגל , בחינה התחתונה \" – מחק תיבת \" שגם \", וכתב :\nלפי ][ ש המשכה שלמעלה מהשתל ]'[ וכש \" כ מהמשכה שבהשתל '( –\nשרק נה \" י שבעליון כו ' נמשך ע \" י בחי ' רגל , בחינה התחתונה ][\nב ) על מה שכתבו : \" ויש בזה ב ' מדריגות כו \"'( – מחק את התיבות : \" בחי '\nרגל )( \" בחי '\", מקיף )( \" שבגדר גילוי \"; וכתב :\",\nויש בזה ב ' מדריגות : מדלג ברגלו אחת , שההמשכה ][ שבהעתקה [ היא\nרק רגל ] אחת ומקפץ בב ' רגלים , שעי \" ז נעתק בכל גופו . והם ][ ע \" ד [ מקיף\nהקרוב ] חברי דניאל )( [ ומקיף הרחוק , ומצד המשפיע הוא בחי ' מקיף"],[9200110088,"88\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nהישר ומקיף החוזר ] בספי ' א \" א ועתיק ולפה \" צ התפשטות ה [ אור ועצם\nהאור ]\n[2 ] במכתבם כתבו : \" וגם הגילוי דמקיף הישר אינו דומה לאופן הגילוי\nדאו \" פ . דאופן המשכת האו \" פ הוא במיעוט ובהעלם , וכמו או \" א\nמלבישים זרועות דאריך , שהגם שלשון מלבישים מורה על זה שתופסים\nאת המהות ( ולא יניקת הארה לבד ) מ \" מ הרי זה בא בהתלבשות כו ', ולכן\nנעשה התחלקות בחו ב , משא \" כ במקיף שאופן המשכתו הוא בבחי '\"\nריבוי אור כמו שהוא , וכמו או \" א יונקים ממזלא , דעם היות הארה לבד ,\nבחי ' מזלות ושערות , מ \" מ אינו בא במיעוט והתלבשות , שלכן נעשה מזה\nיחוד והתכללות חו \" ב . דכ \" ז הוא בבחי ' מקיף הישר , משא \" כ בחי ' מקיף\nהחוזר הוא למעלה מגדר גילוי לגמ רי , וכשהוא נמשך ומתגלה , הוא\nמתגלה כמו שהוא בעצמותו ( ולא בחי ' הארה לבד ). ועד \" ז הוא בחי '\nמנוחה שאחרי היגיעה , ומנוחה בעצם .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n( א ) על מה שכתבו : \" וגם הגילוי דמקיף הישר אינו דומה לאופן הגילוי\nדאו \" פ . דאופן המשכת האו \" פ כו \"' – מחק תיבת \" וכמו \", וכתב :\nדאופן המשכת האו \" פ הוא במיעוט ][ ובהתלבשות ובהעלם ][ וע \" ד [ או \" א\nמלבישים זרועות דאריך , שהגם שלשון מלבישים מורה על זה שתופסים\nאת המהות ( ולא יניקת הארה לבד ) מ \" מ הרי זה בא בהתלבשות כו ', ולכן\nנעשה התחלקות בחו \" ב ]\n( ב ) על מה שכתבו : \" משא \" כ במקיף שאופן המשכתו הוא בבחי ' ריבוי\nאור כו \"' – מחק את התיבות : \" כמו שהוא \", \" במיעוט ו התלבשות )( ;\"\nוכתב :\n[ משא \" כ במקיף שאופן המשכתו הוא בבחי ' ריבוי אור , וכמו או \" א\nיונקים ממזלא , דעם היות הארה לבד , בחי ' מזלות ושערות ] ורק יניקה\nמ \" מ אינו בא ][ ב התלבשות ][ והעלם [ שלכן נעשה מזה יחוד והתכללות\nחו \" ב .\n( ג ) על מה שכתבו : \" דכ \" ז הוא בבחי ' מקיף הישר , משא \" כ בחי ' מקיף\nהחוזר הוא למעלה מגדר גילוי לגמרי , וכשהוא נמשך ומתגלה , הוא\nמתגלה כמו שהוא בעצמותו ( ולא בחי ' הארה לבד ). ועד \" ז הוא בחי '\nמנוחה שאחרי היגיעה , ומנוחה בעצם \" – מחק את התיבות : \" דכ \" ז הוא\nבבחי ' מקיף הישר \", \" בעצמותו \"; סימן בעיגול תיבת \" דכ \" ז \", וכתב :\n!?"],[9200110089,"89\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n[3 במכתבם כתבו : \" דזהו ההפרש שבין הדילוג דיצי \" מ , דילג על הקץ ,]\nשהגילוי דועברתי גו ' הוא בשביל מכת בכורות . ביטול הקליפות ( ולא\nהספיק על זה גילוי או \" פ , ע \" ד הושיט כו ' ושרפן , כי מצד בחי ' קו המדה\nשבראשו דבוק ובסופו אינו דבוק יש נתינת מקום להשתל ', וגם מבחי '\nהאור שק וה \" צ , היינו בבחי ' זו שבה הוא דביקות הקו , ישנו כבר נתינת\nמקום למדידת הקו והשתל ' כו ', ולכן בשביל ביטול הקליפות לגמרי , הי '\nצריך להיות המשכת עצם האור למעלה משרש ומקור הקו ) שזהו \" ע\nמנוחה לאחרי המלחמה , בחי ' מקיף הישר . משא \" כ במ \" ת הוא בחי '\nמקפץ , מנוחה בעצם . מקיף הח וזר . והגם שגם בתורה ישנו הענין\nדלהבדיל בין הטמא ובין הטהור כו ', לא זהו עיקר הענין דתורה . וגם אי \" ז\nבדרך דחיית הרע , כ \" א בירור והעלאת הניצוצות לקדושה . והגם שיצי \" מ\nהי ' הכנה למ \" ת , וההכנה צ \" ל מעין הגילוי , הוא לפי שגם ביצי \" מ הי '\nבהעלם גם בחי ' עצם האור , ורק מה שנת גלה הי ' זה בשביל מכת בכורות ,\nמנוחה אחרי המלחמה , אבל בהעלם הי ' בזה גם בחי ' מנוחה בעצם ,\nונתגלה אח \" כ בשעת מ \" ת .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nא ) על מה שכתבו : \" דזהו ההפרש שבין הדילוג דיצי \" מ , דילג על הקץ ,(\nשהגילוי דועברתי גו ' הוא בשביל מכת בכורות . ביטול הקליפות כו ,\"'\nכתב :\nביטול הקליפות ][ ( בעת התוקף שלהם – כן נ \" ל , אף שלא נתפרש במאמר\n– מפני גודל החידוש שבכל זה )\nב ) על מה שכתבו : \" ולא הספיק על זה גילוי או \" פ כו \"'( – מחק את\nהתיבות \" עצם האור \", וכתב :\n[( ולא הספיק על זה גילוי או \" פ , ע \" ד הושיט כו ' ושרפן , כי מצד בחי ' קו\nהמדה ] שמודד מפני החילוק שבראשו דבוק ובסופו אינו דבוק ][ , שעי \" ז\n[ יש נתינת מקום להשתל ', וגם מבחי ' האור שקוה \" צ , היינו בבחי ' זו שבה\nהוא דביקות הקו , ישנו כבר נתינת מקום למדידת הקו והשתל ' כו ', ולכן\nבשביל ביטול הקליפות לגמרי , הי ' צריך להיות המשכת ] מ [ למעלה משרש\nומקור הקו ])\nג ) על מה שכתבו : \" שזהו \" ע מנוחה לאחרי המלחמה כו \"'( – מחק תיבת\n\" שזהו )( ע \", וכתב :\"\nשזהו ][ ע \" ד [ מנוחה לאחרי המלחמה , בחי ' מקיף הישר . משא \" כ במ \" ת\nהוא בחי ' מקפץ ] ע \" ד מנוחה בעצם . מקיף החוזר ]["],[9200110090,"90\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nד ) על מה שכתבו : \" והגם שגם בתורה כו \"'( – מחק את התיבות : \" שגם\nב תורה )( \", \" ישנו ה עני )( ן ד להבדיל )( \", \" וגם אי )( ז בדרך ,\"\" עיקר הענין ;\"\"\nשינה את הסדר : תיבות \" לא זהו עיקר הענין דתורה \" לאחר התיבות\nכ \" א בירור והעלאת הניצוצות לקדושה \"; וכתב :\"\nוהגם ][ ש תורה עני ][ נה להבדיל בין הטמא ובין הטהור כו ', אי ][ ן הכוונה\nדחיית הרע , כ \" א בירור והעלאת הניצוצות לקדושה ][ ועוד ד לא זהו ][\nהכוונה פנימית דתורה ][ כ \" א תוס ' אור בפני ' ישראל ( ועל ידם בסדר\nההשתל )'\nה ) על מה שכתבו : \" והגם שיצי \" מ הי ' הכנה למ \" ת כו \"'( – מחק את\nהתיבות : \" הגילוי \", \" הוא לפי \", \" ונתגלה אח \" כ \"; שינה את הסדר : תיבת\nזה \" לפני תיבת \" הי '\"; וכתב :\"\nוהגם שיצי \" מ הי ' הכנה למ \" ת , וההכנה צ \" ל מעין ][ זה שמכינים , י \" ל\nשזהו שגם ביצי \" מ הי ' בהעלם גם בחי ' עצם האור ][ ובעצמו \"\" [ ורק מה\nשנתגלה ] ש [ זה הי ' בשביל מכת בכורות , מנוחה אחרי המלחמה , אבל\nבהעלם הי ' בזה גם בחי ' מנוחה בעצם ] ובגילוי בשעת מ \" ת ][\n[4 ] במכתבם כתבו : \" השאלות : א ) אם פירוש מדלג ברגלו אחת לבד , הוא\nענין אחד עם בחי ' או \" א יונקים ממזלא , דהגם שהוא ריבוי אור , מ \" מ\nהוא הארה לבד , בחי ' מזל ושערות , שזהו \" ע רגל . משא \" כ מקפץ בב ' רגליו\nשעי \" ז נעתק בכל גופו , הוא בחי ' עצם האור שאינו בגדר גילוי , וכשנמשך\nומתג לה הוא מתגלה בכל עצמותו .\"\nכ \" ק אדמו \" ר שליט \" א מחק את התיבות : \" אם פירוש \", \" הוא ענין אחד\nעם \", \" ריבוי אור , מ \" מ הוא \", \" שזהו \" ע ,\" \" וכש )( נמשך ו מתגלה )( וכתב :\";\nמדלג ברגלו אחת לבד ][ דוגמא לזה [ בחי ' או \" א יונקים ממזלא , דהגם\nשהוא הארה לבד , בחי ' מזל ושערות ] ע \" ד רגל ][ – הוא ריבוי אור\nומכש \" כ רגל שהוא אבר )(\n[5 במכתבם כתבו : \" ב ) מהו פירוש שגם בחי ' מקפץ , המשכת עצם האור ,]\nהוא ע \" י בחי ' רגל ? אם הכוונה ע \" ד משנ \" ת בהשיחה בענין העצם כשאתה\nתופס במקצתו אתה תופס בכולו , דפירוש מקצתו הוא מצד ההתגלות\nלמטה שמצד הגילוי הוא בגדר ציור והתחלקות , דזהו \" ע מקצתו , אבל יש\nבזה כל העצם . ועד \" ז פירוש שמתגלה ע \" י בחי ' רגל , ומ \" מ נעתק הוא בכל\nגופו .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nא ) על מה שכתבו : \" אם הכוונה כו \"'( – מחק תיבת \" אם \", וכתב :"],[9200110091,"91\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n[ הכוונה ע \" ד משנ \" ת בהשיחה בענין העצם כשאתה תופס במקצתו אתה\nתופס בכולו ] וע \" ד שהנשמה הוא אלקות שנעשה נשמה\nב ) על מה שכתבו : \" דפירוש מקצתו כו '\", כתב :(\nבמ \" א מצוין ע \" ז : עיין בי ' שחורה אני בהגהה .\n[6 ] במכתבם כתבו : \" ג ) מהו ההפרש בין דחיית הקליפות לביטול\nהמלאכים , שלביטול המלאכים מספיק גם או \" פ שבהשתל ', אף שהוא\nבגדר קו המדה .\"?\nמענה כ \" ק אדמו \" ר שליט \" א :\nא ) על מה שכתבו : \" מהו ההפרש בין דחיית כו '\", כתב :(\nההפרש בין דחיית ][ וביטול הקליפות לביטול המלאכים ][\n( ב ) על מה שכתבו : \" שלביטול המלאכים מספיק גם או \" פ שבהשתל ', אף\nשהוא בגדר קו המדה \", כתב :\nבמ \" א מבואר שגם לביטול המלאכים ][ באצבעו הקטנה מל ' – ה \" ז\nמרוממות המל ' – היינו סוכ \" ע ( י \" ל ששייך גם לענין דהשתל ' הכתרים\nזמ \" ז ). כאן – נראה הכוונה כי מצד קו המדה אין שייך גילוי בארמ \" צ\nכלל כמלאה גילולים . או ע \" ד הפי ' דולא מלאך כי מלאך הי ' נבלע\nונשתקע שם ( הובא בלקו \" ת צו טז , א – כן – כנ \" ל אפ \" ל : מפני שהי '\nבתוקף עדיין דלא נתמלאה סאתן ( ובזה מובן החילוק ממחנה סנחריב )\nקג\nלאחר יום ב ' דחג השבועות , תשכ \" א ][\nמענה להמניחים על שאלתם בהמדובר בהתועדות יום ב ' דחג השבועות\n– בענין העובר קו התאריך בימי ספירת העומר , שי \" ל שחג השבועות\nאצלו צ \" ל ע \" פ הספירה שלו :\nאיך מתאים ביאור השיחה משנת תשי \" ז שנעתקה כאן , למ \" ש שבה '\"\nבסיון אצ \" ל זמן מ \" ת ? וגם איך מתאים למ \" ש הדברי נחמי ' בהשלמת\nהשו \" ע סימן תקפא בקו \" א ?\nב ) ישנם טוענים שהגם שמצות ספירה היא על כאו \" א , וחגה \" ש הוא\nבהמשך לספה \" ע , מ \" מ אינו בא בהמשך להספירה של כאו \" א , כ \" א\nלספה \" ע של כלל ישראל . ומביאים ראי ' ( א ) מנשים שפטורות מספה \" ע"],[9200110092,"92\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nומ \" מ מחוייבות בחגה \" ש , שבהן אא \" ל שחגה \" ש בא בהמשך לספירתן ,\nשהרי פטורות מספירה , כ \" א בהמשך לספירה של כלל ישראל . ( ב ) איך\nיהי ' הדין בגר שנתגייר בערב חג השבועות , שמסתמא יהי ' מחוייב\nבקדושת היום , אף שלא הי ' לו מקודם ספירה כלל . וא \" כ מוכיחים\nשעצרת נמשך לספה \" ע של כלל ישראל .\nמהי התשובה על טענתם ? ומהי ההוכחה שחגה \" ש בא בהמשך לספה \" ע\nשל יחיד ? אולי כדאי לציין דברי הרמב \" ן ( ויקרא כג , טו ) וז \" ל : שיספור\nשבע שבתות תשע וארבעים ויקדש יום החמישים הנספר בידו .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – תשורה שפירא ח ' סיון\nתש \" ס ע ' 59 :)\n[1 ] על מה שכתבו : \" איך מתאים ביאור השיחה משנת תשי \" ז שנעתקה\nכאן , למ \" ש שבה ' בסיון אצ \" ל זמן מ \" ת ?\", כתב :\nי \" ל שהוא ע \" ד שהי ' במדבר בפעם הא ' – שאף שגמרו בנ \" י הספירה\nמצדם הוסיפו ( משה , או מלמע ' – כשני הדעות שבש \" ס ) יום א ' וניתנה\nתורה ביום נא . והי ' ביום ה ששי דוקא – כפסק אדה \" ז .\n[2 ] על מה שכתבו : \" וגם איך מתאים למ \" ש הדברי נחמי ' בהשלמת\nהשו \" ע סימן תקפא בקו \" א ?\", כתב :\n– הד \" נ פליג בשנים : 1 ) ס \" ל דהלכה כר \" י דבז ' בסיון ניתנה תורה . ומזה\nדתמיד צ \" ל בחה \" ש זמן מ \" ת .\n[3 סימן בעיגול את התיבות : \" לספה \" ע של כלל ישראל \", וכתב :]\n!?\nאפילו נביא אין רשאי לחדש מצוה . וכאלו נאמר שישנה הנחת תפלין של\nכלל ישראל ! ( ועייג \" כ שו \" ע אדה \" ז סתפ \" ט ס \" א .)\n[4 סימן בעיגול את מה שכתבו : \" ומביאים ראי ' כו '\", וכתב :]\nמעורב בזה ב ' גדרים : קביעות זמן ( בירור ,) עשי ' . מהנ \" ל הוכחה שאין\nחה \" ש נעשה ע \" י ספה \" ע ( עכ \" פ לא ע \" י הספירה ) ( כמו שאין חהמ \" צ\nנעשה ע \" י י \" ד ימים שקדמוהו , כ \" א ע \" י יצי \" מ . ועד \" ז בסוכות וכו )'\n[ בנשים עוד נקודה – שלכמה דעות – במ \" ע שהזמ \" ג בעלה פוטרה , ולא\nשאין בהן הענין מלכתחילה . וק \" ל ] – ולפי הקס \" ד של המקשן – אינו\nמובן למה ממרחק יביא לחמו , והו \" ל להוכיח ממי ששכח או הזיד\nמלספור פ \" א ( או שלא סיפר כלל ) שמפורש דינו בשו \" ע [ ואף ( שע \" פ\nהפנימי ' – הרי ) שחסר לו יום ( בירור מדה ]) – ובכלל הוא כמו בכמה"],[9200110093,"93\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nענינים שע \" פ פנימי ' – צ \" ל הכנה כוונה או ברכה בכדי שיעשה הענין .\nובדין הנגלה – בעשי ' גרידא או בבוא הזמן הקבוע – בכל אופן נעשה\nהענין ( כגוף בלא נשמה וכיו \" ב ). וי \" ל כמה הסברים בזה . ואכ \" מ . וגם\nדוגמאות בדין : כיפר ולא כיפר , שינה עליו הכתוב ( ודוקא אז ) לעכב , צ \" ל\nראוי לבילה אבל אז אינה מעכבת ועוד .\nבכללות – היסוד דתורה על הרוב תדבר\nקד\nי \" ב סיון , תשכ \" א ][\nמענה לר ' דובער בוימגארטען ( תשורה איידעלמאן ל \" ג בעומר תשס \" ו ע '\n41-42 :)\n[1 ] במכתבו כתב : \" קבלתי מענת כ \" ק אד \" ש , אבל לא הבנתי מזה מה עלי\nלעשות בפו \" מ . טלפנתי אל העו \" ד ואמר לי שהיום א \" ל מענה ברורה\nשאטלפן לו מחר בצהרים , אבל האם להתענין בהצעת . . או לא , וכן מכל\nהדו \" ד עם . . האם להתענין הלאה בזה או לא . וגם מה שכתב כ \" ק אד \" ש\nבסוף דבריו על מכתבי אופן שליחות של ליובאוויטש וכו ' אין מתאים כלל\nוכו ', כבר אינני יודע האם יש ענין בשביל . . לחשוב אודות הסתדרות\nבבוענאס איירעס .\"\nעל התיבות : \" קבלתי מענת כ \" ק אד \" ש \", כתב כ \" ק אדמו \" ר שליט \" א :\n(1 שעניתי ' לא בפעם הא ', כ \" א זה פעם ב ' או ג ') – וחוזר ושואל !\n[2 ] במכתבו כתב : \" חפצי ורצוני למלאת כוונת כ \" ק אד \" ש כמו שצ \" ל וכמו\nשהוא מבין את הכוונה ולזכות להיות שליח שלו . אין לי שום נפק \" מ , אם\nזהו רצונו . אבל אם זה ענין וואס איך אליין שפאר זיך אהין , למה לי כל\nהענין . אבל מכיון שמכ \" ק אד \" ש שמעתי כמ \" פ אודות מדינת ארגנטינה\nוכ ו ', ע \" כ אבקש שיואיל נא כ \" ק אד \" ש להאיר עיניי ויורה לי מה עלי\nלעשות בזה , וכן איך ובאיזה אופן אחליט עד כמה מבוססת הדין\nוחשבון .\"\nעל התיבות : \" שפאר זיך אהין \", כתב כ \" ק אדמו \" ר שליט \" א :\n(2) ובתקפו עומד\n[3 ] במכתבו כתב : \" עד \" ז הוא גם בנוגע להצעות . .\"."],[9200110094,"94\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nמענה כ \" ק אדמו \" ר שליט \" א :\n(3) שייך לסוחר\n[4 על ענין מסויים שכתב , כתב כ \" ק אדמו \" ר שליט \" א :]\nשייך להתייעץ עם אלו המכירים את המציעים מצב המוסד וכו .'\nקה\nי \" ז סיון , תשכ \" א ][\nמענה להת ' משה יחיאל פעלער ( תשורה פעלער י \" ז מנ \" א תשפ \" א ע ' 8 :)\n[1 ] במכתבו כתב : \" הנני למסור הפוטוגרעפס שלקחתי עם הנוער\nשהצלחנו , בברכת כ \" ק אד \" ש , להביא מפענעמה לישיבת כ \" ק אד \" ש\nבבוסטון . כוונתי לצרף להארטיקל שלי שידפיסו לשבועון דפ ' קרח , א '\nמהתמונות האלה , לענ \" ד התמונה שבו תמונת כ \" ק אדמו \" ר מו \" ח כ \" ק\nאד \" ש , אבל באם אין נכון זה מאיזה טעם הנני לבקש הוראת כ \" ק אד \" ש\nאיזה מהם לצרף .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nא ) על מה שכתב : \" הנני למסור הפוטוגרעפס כו '\", כתב :(\nות \" ח\nב ) מחק את התיבות \" אבל באם אין \", וסימן בחץ את התיבות \" נכון זה .\"(\n[2 ] במכתבו כתב – בקשר לנער מסויים : \" הוא בר שלשה עשרה שנים\nעמו \" ש אבל עוד לא חג את הבר מצוה שלו . הם יסדרו את זה בבוסטון .\"\nעל התיבות : \" לא חג את הבר מצוה שלו \", כתב כ \" ק אדמו \" ר שליט \" א :\n(2 אבל בטח מניח תפילין ?)\n[3 ] במכתבו כתב : \" הנני מבקש הוראת כ \" ק אד \" ש באם נכון להדפיס\nמגבית בהארטיקל שלי שהיות שבברכת כ \" ק אד \" ש בא הענין לפועל . .\".\nכ \" ק אדמו \" ר שליט \" א מחק תיבת \" באם \", וסימן בעיגול את התיבות :\nנכון להדפיס כו '\", וכתב :\"\n(3) באם הצליחה המגבית דע \" ע"],[9200110095,"95\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n[4 ] במכתבו כתב : \" כשהייתי בבוסטון נאמתי לפני סיום אסיפה של\nהשל \" ה סונדיי סקול דבוסטון . . מסדרי המסיבה היו הרה \" ח משה שי '\nגורקוב , האחים קרינסקי שי ', ומר ומרת ניומאן .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nכמובן נכון במאד . והנכון ג \" כ שיכתוב מכ ' תודה על הקבלת פנים וכו '\nבעיקר מר ומרת ניומאן ][\nקו\nכ \" א סיון , תשכ \" א ][\nמענה לר ' דובער בוימגארטען שכתב : \" היום בקר מסרתי לכ \" ק אד \" ש\nהב ' מכתבים שקיבלתי עוה \" פ מחברת . .; כאן שוהה ר ' . . שי ' הטבח של\nה . . ויספר נוראות מהרדיפות שקיבלו אנ \" ש הספרדים דשם וביחוד מה\nשסובל . . וכן הגיעו מכתבים עד \" ז מ . . וכן הגיע כאן תל ' אחד\nממונטיבידאו ל ישיבת מיר , . . שמו , ויספר ג \" כ עד \" ז שהי ' נוכח בבוענאס\nאיירעס בעת המחלוקת בביהכנ \" ס ושמע ג \" כ הקולות בעת שהכו . .\nהנ \" ל \" ( תשורה איידעלמאן ל \" ג בעומר תשס \" ו ע ' 42 :)\n(1 האם אין שם ביהכנ \" ס אחר להתפלל בו !?)\n(2) אזכיר עה \" צ\nקז\nכ \" ח סיון , תשכ \" א ][\nמענה לר ' יוסף מנחם מענדל טענענבוים שכתב : \" בהתאם לזה שכ \" ק\nהורה אחר פורים ע \" ד התענינות ע \" ד תלמידים דערי השדה ( אשר\nלדאבונינו נמסר לנו דברי כ \" ק אז אחר שכבר נסעו ) התאספנו בש \" ק אחר\nההתוועדות הרמ \" מ הרד \" ר ואני עם מר ליטווין והתלמיד אנדרוסיער שי '\nלסדר שהתלמידים דבא סטאן יבקרו את הישיבה על בעדפארד . ולאחר\nאריכות הדברים ( שהם לא חשבו כלל עד \" ז ) נסתדר שיתפללו בבוקר\nבבית מדרש כ \" ק אד \" ש ( לפי תכניתם היו צריכים להתפלל כל א ' בבית\nשהתאכסן ויאכלו שם ארוחת הבוקר ), ולנסוע אח \" כ לנויארק ועמפייער\nויאכלו ארוחת הבוקר אצל מר שפיצער , ואחר הביקור בנויארק לבא\nלבעדפארד לארוחת הצהרים בשעה 12:30 בערך , והראנו להם את בית\nהאוכל בעת שהתלמידים הצעירים ברכו ביחד בקול . אח \" כ אכלו ארוחת"],[9200110096,"96\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nהצהרים ביחד והרב פאגעלמאן שוחח עמהם בבית האוכל , גם נתן להם\nצידה לדרך : לחם ונקניק ופירות . הנערים הובלו בהבאס של הישיבה\nלאכסניות שלהם ובעת שנסעו מהבנין יצאו כמה מחלקות ולוו אותם\nבשיר : כי בשמחה וכו '\" ( ס ' \" תולדות התמימים בארצות הברית \" ע '\n576 :)\nויה \" ר שיהי ' הנ \" ל , התחלה טובה לפעילות ממשית לריכוש תל '\nקח\nז ' תמוז , תשכ \" א ][\nמענה לר ' דובער בוימגארטען ( תשורה איידעלמאן ל \" ג בעומר תשס \" ו ע '\n42-43 :)\n[1 במכתבו כתב :]\n\" שאלתי מר ' . . משם , קבלתי זה איזה ימים המענה וועגען אייער קומען\nאבער איהר קענט געזונטערהייט קומען קיינער זוכט אייך ניט , אף\nשמתחילה כתב שצריך ליזהר , אבל אח \" כ שיחדו שם במקום המתאים\nאון מ ' האט די גאנצע זאך אפגעווישט .\nאבל העו \" ד סיפר לי בתוך הוויכוחים עם הצד שכנגד על . . איך יהין לנסוע\nלשם הרי יכולים לשימו בכלא תיכף בהכנסו למדינה . ואח \" כ התנגד\nלנסיעת . . מטעם שיסע שם לפתות את העדים שיש לו שם נגדו , וע \" ז שאל\nהשופט א \" כ באם שיש לך עדים איך אמרת שהנך מוכן לגשת למשפט\nתומ \" י ? וע \" ז ענה שעדים אין לו שם אבל מחכה משם ניירות . העו \" ד\nמסופק האם נכונים הדברים או שרק מגמגם ומפטפט ולאידך גיסא\nחושש שמא הוא הקטיגור ימסר לשם שהנו נוסע .\"\nכ \" ק אדמו \" ר שליט \" א סימן קו תחת התיבות : \" שמא הוא הקטיגור\nימסר לשם שהנו נוסע \", וכתב :\n(1 ) כל זמן שיהי ' ספק – שב וא \" ת עדיף\n[ וראה לקמן מענה קט .]\n[2 ] במכתבו כתב : \" בהנוגע לבר מצוה של בני , חשבתי לנסוע לאוהל עמו\nביום י \" ב תמוז קודם התפילה ואח \" כ להתפלל כאן , יעלה לתורה במנין\nכ \" ק אד \" ש , ואח \" כ אחה \" צ בשעה 1-2 אחרי שובינו מהאוהל לערוך\nסעודה ושם יחזור המאמר , ובלילה להשתתף בהתוועדות כ \" ק אד \" ש .\""],[9200110097,"97\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות \" לנסוע לאוהל \" ואת\nהתיבות \" ואח \" כ להתפלל \" וסימן קו - חיבור ביניהם ; וכתב :\n(2 ) לברר אצל זקני אנ \" ש הנוהגים כן\n[3 ] במכתבו כתב : \" אוכל לבשר שהחזן נחמי ' לעוויצקי שמזמן קודם פסח\nהנני לומד עמו פעמיים בשבוע ביחד עם משה ביו , הנה בביהכנ \" ס שלו\nהקאנסערווטיבי בקראנפארד ניו גרסי העבירו את הצערעמוניא של בת\nמצוה משבת , שהי ' קודם הרבה חילול שבת דאורייתא , לליל חול . וכן יסד\nשם חברת שו \" ע ללמוד עם הבעה \" ב והאברכים הדינים שהנו לומד כאן ,\nוהתחיל עם ד ' תל ' פ \" א בשבוע וכבר יש לו יותר ממנין משתתפים , וכעת\nמסדר שהראביי ילמוד עמהם לפי שהוא מרגיש שהוא אינו דובר הכי טוב\nעבור זה .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(3) ת \" ח על הבשו \" ט\n[4 על כללות המכתב , כתב כ \" ק אדמו \" ר שליט \" א :]\n(4) אזכיר עה \" צ\nקט\nט ' תמוז , תשכ \" א ][\nמענה לר ' דובער בוימגארטען ( תשורה איידעלמאן ל \" ג בעומר תשס \" ו ע '\n44 :)\n[1 ] במכתבו כתב : \" התדברתי עוה \" פ עם העו \" ד ואמר לי אשר הקטיגור\nטלפן לו ויגיד לו אשר הוא מצידו ג \" כ מרגיש Motion שבאם אינו נוסע\nלחוץ למדינה אזי יהי ' המשפט יותר קרוב ולא לחכות לאקטובער , וע \" ז\nידונו לפני השופט ביום ב ' הבעל \" ט . ואמרתי להעו \" ד שבאם יכול המשפט\nלהיות נגמר קודם ר \" ח מנ \" א אולי כדאי לעשות ככה , ובכל אופן שלא\nיהי ' בחודש מנ \" א כמו שכתוב בשו \" ע . והנה מהירותו הוא להיות ששם\nיש סחורה על יותר מט \" ז אלף דולר ואחרי המשפט הכל עבורו , ומלבד\nמה שיוכל לשלם חובתו בעד עניני המשפט שעולים כבר לסך יותר מאלף\nדולר וגם להעו \" ד וגם בעד נזק וצער ושבת ובושת וכו .\"'\nמענה כ \" ק אדמו \" ר שליט \" א :\n(1 ) יעשו כן ולא יבלבלו בעוד ענינים"],[9200110098,"98\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n[2 ] במכתבו כתב : \" ובעצם הענין של החששות שהעיר , ושע \" ז ענה כ \" ק\nאד \" ש \" שכל זמן שיהי ' ספק שב ואל תעשה עדיף \" [ לעיל מענה קח ]. הנה\nהוסיף העו \" ד ואמר שחשש זה רחוק מאוד אחר שהתבונן עוה \" פ , ובאם\nשכן יהי ' ספק או ספק ספיקא הרי אפי ' אם יהי ' המשפט ויגמר הענין\nבטוב ג \" כ יוכל למסור , לפי שאין זה סדר מסדרי משפטים למסור אלא\nשחשש הוא שמא יצא זה מגדרו וימסור . ובכן באם יש לחוש לחשש זה\nהרי גם אח \" כ יש לחוש לזה .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(2) ואז אין מחויב לדעת האם ומתי נוסע להודיעו הנוסע או לא\n[3 על כללות המכתב , כתב כ \" ק אדמו \" ר שליט \" א :]\n(3) אזכיר עה \" צ\nקי\nלפני י \" ג תמוז , תשכ \" א ][\nמענה לר ' יעקב ומרת לובא אלטא טויבא ליפסקער שכתבו : \" הננו להודיע\nלכ \" ק אדמו \" ר שליט \" א שביום ג ' י \" ג תמוז הבעל \" ט יסעו בנינו : צבי הירש\nושניאור זלמן שי ' למחנה \" גן - ישראל \", ויוסף יצחק ושמואל שי ' יסעו\nאי \" ה , עם אחותם חי ' צבי ' תחי ', לנאות - דשא . ונבקש ברכת כ \" ק אדמו \" ר\nשלי ט \" א \" ( מצילום כתי \" ק – נדפס לעיל . המענה מתפרסם בזה לראשונה\nבאדיבות משפחת הנמען ע \" ה וזכות הרבים תלוי ' בהם :)\nויהא בשטומו \" צ\nקיא\nט \" ו תמוז , תשכ \" א ][\n\" צעטל \" בכתי \" ק שכתב כ \" ק אדמו \" ר שליט \" א להת ' אהרן אביגדור\nקאזין בקשר לנסיעתו לביתו שבאנגליא בצום שבעה עשר בתמוז יהפך\nלשמחה ( ס ' \" תולדות התמימים בארצות הברית \" ע ' 498 :)\nבטח יתחיל אריזת חפציו וכדומה לפני יום ג .'"],[9200110099,"99\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nקיב\nאור לט \" ז תמוז , תשכ \" א ][\nמענה לר ' דובער בוימגארטען ( תשורה איידעלמאן ל \" ג בעומר תשס \" ו ע '\n44-45 :)\n[1 במכתבו כתב : \" להוסיף עוד כמה בשו \" ט אודות הבחור נחמי ']\nלאוויצקי שקנה כאן במל \" ח כמה מהענינים המודפסים כמו השבת\nביכעל , תפילין , ומזוזה סיקס אספעקטס , וחילקם מהם בחנם ומהם\nשילמו לו . בליל אור לי \" ב תמוז הי ' אסיפה ומטרתה לשכלל כמה\nמהענינים הכללים והדתיים וכו .\"'\nמענה כ \" ק אדמו \" ר שליט \" א :\n(1) ת \" ח על הבשו \" ט\n[2 ] במכתבו כתב : \" בנוגע לענין המשפט : הי ' פרטים שיתקיים מקודם\nר \" ח מנ \" א ויה \" ר שיגמר הענין במהרה בכי טוב .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(2) אזכיר עה \" צ\nקיג\nועש \" ק בלק , ט \" ז תמוז , תשכ \" א ][\nמענה לר ' יוסף מנחם מענדל טענענבוים שכתב : \" הנני שולח בזה לכ \" ק ב '\nדוגמאות ( א ' מהישיבה וא ' מהמתיבתא ) מהסדר הלימוד לימי הקיץ\nשנעשה ע \" י הרמי \" ם שי ' עבור התלמידים שי ', ומצורף בזה ב ' המכתבים\nשל כ \" ק בהנוגע לימי החופש , אחדים מהרמי \" ם מסרו ג \" כ שאלות\nשהתלמידים צריכים ל ענות בכתב . לכל תלמיד נמסר \" תפלת מנחה\nומעריב \" במתנה ( נדבת הרב וויינבערג שי '). לכל א ' מהרמי \" ם נמסר ב '\nכרטיסים - כפולים כדי לכתוב לתלמידיו ב ' פעמים במשך ימי החופש ,\nכהוראת כ \" ק בזה \" ( ס ' \" תולדות התמימים בארצות הברית \" ע ' 613 :)\nת \" ח"],[9200110100,"100\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nקיד\nועש \" ק בלק , ט \" ז תמוז , תשכ \" א ][\nמענה לר ' דובער בוימגארטען שכתב : \" להיות שיש לי ג \" פ בשבוע\nקביעות ' ן עם זולת ' ן בלילה האם ארשם בתוך הלומדים בקביעות החדש\nכאן בביהמ \" ד כ \" ק אדמו \" ר שליט \" א ?\" ( תשורה איידעלמאן ל \" ג בעומר\nתשס \" ו ע ' 45 :)\nכ \" ק אדמו \" ר שליט \" א מחק תיבת \" האם \", וסימן קו תחת התיבות\nקביעות ' ן עם זולת ' ן בלילה \"\" – וכתב :\nפשוט שאין לבטלן ולא ארשם בתוך הלומדים ][\nקטו\nאור לכ \" ח תמוז , תשכ \" א ][\nמענה לר ' דובער בוימגארטען ( תשורה איידעלמאן ל \" ג בעומר תשס \" ו ע '\n45-46 :)\n[1 ] במכתבו כתב : \" בנוגע המשפט , אודות חילוקים בשופטים ומייעצים\nלהעדיף א ' על שניים אחרים , וע \" כ אנא יורנו כ \" ק אד \" ש היותר נכון שלא\nלמהר ואולי עי \" ז נכנס לתוך חודש מנ \" א או יותר טוב למהר .\"\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול קטע זה , וכתב :\n(1 ) כעצת העו \" ד בזה\n[2 ] במכתבו כתב : \" רוצף הנני מכתב שקבלתי מאת הבחור נ . ח . מב . א . בה\nמבקש אותי לשאול מאת כ \" ק אד \" ש אודות למוד , ואנא שיואיל כ \" ק\nאד \" ש להורות מה לענות לו ע \" ז .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(2 ) בגיל שלו הרי העיקר ענין שידוך וכיון שזה בקל יותר באה \" ק ת \" ו\nמאשר בכאן – יש להתענין בנסיעה לשם מאשר לכאן\n[3 על כללות המכתב , כתב :]\nלהחזיר\nאזכיר עה \" צ"],[9200110101,"101\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nקטז\nי \" ג מנ \" א , תשכ \" א ][\nמענה לאחת שכתבה שהתפללה להקב \" ה על ענין מסויים ותפלתה\nנתקבלה ( תשורה לוין י \" ט אד \" ר תשס \" ה ע ' 26 :)\nאיך שתפלה ביחד עם בטחון חזק בה ' ( מתוך שמחה דוקא ) מועלת .\nקיז\nאור לב ' אלול , תשכ \" א ][\nממענה לר ' דובער בוימגארטען ( תשורה איידעלמאן ל \" ג בעומר תשס \" ו\nע ' 46-47. קובץ פלפולים - והערות ארגנטינא חוברת יא ע ' 41-42 :)\n[1 ] במכתבו כתב : \" לפני שבוע או עשרה ימים , הופיע אצלי להקביעות\nדדא \" ח התל ' ב . ויגיד לי אשר ער האט א לאנגע צייט ערנסט געטראכט ,\nוכמה לילות לא ישן מטעם זה ההתבוננות , ויחליט אשר אינו יכול להיות\nחסיד ליובאוויטש , מטעם אשר מוצא כו \" כ ענינים מנגדים לשו \" ע , וכן\nאין לו ה נאה מלימוד דא \" ח . ואילו מצא אשר החיוב ללמוד דא \" ח הי '\nתקיף וחזק כמו החיוב דנגלה הי ' לומד אעפ \" י שאין נראה לו , אבל מכיון\nשמצא בשו \" ע וכו ' וכו \" כ שמנגדים בכלל ללימודים אלו , ובמילא אין\nהחוב שעלי ' כ \" כ חזק , אשר על כן החליט להפסיק מללמוד . ואף שכל\nאדם מישראל צריך לבחו ר לו שיטה ולו אין נראה גם השיטה של . . וכו '\nמ \" מ עד שימצא משהו שכן יוכל להיות להמצא שם אין דער היים ילמוד\nגפ \" ת ומוסר , ודי לו .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nג ) יסבירו אז גענוג שפילען זיך בנוגע לתומ \" צ . פס \" ד ברור בשו \" ע ( או \" ח\nר \" ס צ \" ח ) שלפחות ג \" פ ביום צריך לחשוב ( שפי ' – באופן דהבנה\nעיי \" ש ) מרוממות הא - ל , כן מחוייב בתמידיות ( בתוככי כל ישרא - ל )\nלייחדו לאהבו וליראו ( הקדמת ס ' החינוך ) – ואין אלו מצוות שבדיבור\nאלא – שבהבנה והדרך לקיומם היא ע \" י שיתבונן כו ' ( רמב \" ם הל ',\nיסוה \" ת רפ \" ב ) ואינו ידוע בנוגע לאחרים , אבל לאנשים כערכנו ( משא \" כ\nבראשונים כמלאכים כו ' ) יכול שילמוד נגלה ומוסר כל היום כולו\nעשיריות שנים ולא ידע מאומה לפי שכלו שלו שזה נדרש מרוממות הא -\nל ( ועיין הקדמת ס ' חוה \" ל ) ובמילא לא יקיים ר \" ל אף פעם כל מצוות\nהנ \" ל – ומה שלא נהנה מזה – פס \" ד הוא , מצוות לאו ליהנות ניתנו ."],[9200110102,"102\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n[2 ] במכתבו כתב : \" משא \" כ עם נ . ל . בכלל הולך בסדר טוב ומרווה צמאונו\nונראים לו יותר עניני הדא \" ח . . וכאן מוכרחני לכתוב אשר על משמרתי\nעמדתי ואפי ' בליל אור ליום ג ' שבוע העברה אזרתי חיל ונסעתי אליו\nולמדתי עמו וכ \" כ שלט מוחי על לבי . . ואנא יברכני נא כ \" ק אדמו \" ר\nשליט \" א שאזכה להתעסק בעבודות אלו מתוך הרחבה והרווחה ומנוחת\nהנפש ומנוחת הגוף .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nד ) אזכיר עה \" צ\n[3 ] במכתבו כתב – בקשר לא ' ממקורביו : \" כששב ממאנטרעאל לא\nהתקשר עם ליובאוויטש באופן כמו קודם נסיעתו אך סידרתי שלום בין\n. והוא , והשבת שעבר שבת עמהם בראקוואי ואיה \" ש ביום ב ' בקר ב '.\nאלול נוסע צלחה למילאן .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nה ) באיזה הנחה נסע ? ( בנוגע חב \" ד במילאן )\n[4 ] במכתבו כתב : \" כאן מוצאני לנכון לשאול עוד הפעם האם מכתביי\nמזמן לזמן עם פרטים ופרטי פרטים אינם הכבדה על כ \" ק אדמו \" ר\nשליט \" א והאם חפץ מכתביי אל ה שלפעמים נראה כאילו הנני מכביד\nעליו .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nפשוט שנכונה הפרטיות וטובה .\nקיח\nה ' אלול , תשכ \" א ][\nמענה לר ' דובער בוימגארטען שכתב : \" ויואיל נא כ \" ק אדמו \" ר שליט \" א\nלברך . . שיצא הפס \" ד מאת השופט – שגוי הוא ואינו בעל בחירה –\nלטובת . . ויהס קטיגור ויקח הסניגור מקומו וישחררו . . תומ \" י ויתנו ל\n. . הסחורה . שאוכל במהרה ליסע למקומי אויף דורכפירעהן די כוונה עם\nכל צאצאיי כפי שכ \" ק אדמו \" ר שליט \" א מבין אותה \" ( תשורה\nאיידעלמאן ל \" ג בעומר תשס \" ו ע ' 48 :)\nאזכיר עה \" צ והרי הימים ימי רצון ורחמים"],[9200110103,"103\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nקיט\nקייץ , תשכ \" א ][\nמענה להרב פינחס קארף ( מהעתקה . המענה מתפרסם בזה לראשונה\nבאדיבות משפחת הנמען ע \" ה וזכות הרבים תלוי ' בהם :)\nמהעיקרים : היסח הדעת\nלא מלחמה בהדעת )(\nוהצלחה\nאזכיר עה \" צ\nקכ\nתשכ \" א ][\nמענה להמזכיר הרח \" י קרינסקי שכתב – בקשר לתערוכת ספרי קה \" ת\nביריד הספרים הבינלאומי השנתי המתקיים בארצות הברית : \" מצו \" פ\nדו \" ח מההוצאה והכנסה של התערוכה תשכ \" א , ורשימה מאלו שעזרו\nבזה . מצורף ג \" כ הדו \" ח מאשתקד להשוואה \" ( מצילום כתי \" ק – תשורה\nניו כ \" ה אד \" ש תשס \" ח ע ' 21 :)\nכיון שהי ' הנ \" ל בהצלחה רבה ( וכמובן – שזכות הוא לכל המתעסקים\nבזה , ובפרט להעומדים בראש ), כדאי להענין ע \" ד עוד תערוכות כהנ \" ל .\nכמדומה , ישנו משרד מיוחד ע \" ז בהנהלת העיר .][\nויה \" ר שג \" ז יהא בהצלחה , ובגו \" ר ."],[9200110104,"104\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nליקוט מענות קודש\n– תש כ \" ב –\nקכא\nלאחר יום ב ' דראש השנה , תשכ \" ב ][\nמענה להמניחים על שאלתם במאמר ד \" ה טוב טעם ודעת גו ' שנאמר\nבהתועדות יום ב ' דראש השנה :\n\" בהמאמר נתבאר ענין ג ' הסעודות דשבת , מעלי שבתא הוא בחי ' התענוג\nשמעבודת הבירורים , יומא דשבתא הוא בחי ' תענוג העצמי שנמשך אחרי\nזה , אבל הוא ע \" ד פנימיות עתיק כמו שבא בפנימיות אבא , ורעוא דרעוין\nהוא בחי ' פנימיות עתיק כמו שהוא במקומו , תענוג העצמי ממש .\nונתבאר שגם בתורה ישנם בחינות אלו . בחי ' התענוג עצמי כמו שנמשך\nבחכמה הקדומה , ובחי ' תענוג עצמי ממש . ולכן נענש דוד על שאמר\nזמירות היו לי חוקיך , לפי שענין הזמירות הוא גילוי תענוג עצמי כמו\nשנמשך בחכמה וכו ', ואי \" ז אמיתית ענין התורה .\nובזה נתבאר תוכן הבקשה טוב טעם ודעת למדני , טוב טעם הוא תענוג\nהפשוט מה שלא בא גם בהעלם העצמי דחכמה , והבקשה שגם זה יבוא\nבגילוי , עד לשכל הגלוי שבמוח הגשמי , שזהו למדני . וזהו ג \" כ מה שאומר\n\" ודעת \", היינו שבחי ' תענוג הפשוט יהי ' ע \" ד ודעת , דע \" ה שהדעת הוא\nכמו פנימיות הכתר ( דלכן כשאין הכתר נמנה , והו \" ע פנימיות הכתר ,\nהדעת נמנה ) ומ \" מ נמנה במנין הספירות , היינו שבא בהתגלות , דכמו \" כ\nגם הטוב טעם בחי ' תענוג עצמי הפשוט , יבוא בגילוי .\nשאלה : מסגנון לשון המאמר משמע שתוכן הבקשה שבבחי ' טוב טעם\nיהי ' למדני , היינו שכמו שהוא בעצמותו יבוא בגילוי , בלי שום ירידה כלל ,\nולא ע \" ד פנימיות עתיק כמו שבא בפנימיות אבא . ולפי \" ז מהו הדמיון\nלענין הדעת , והרי הדעת עם היותו כמו פנימיות הכתר מ \" מ הוא ירידה\nכו ', שלכן מביאים ( קונט ' קיח ספ \" ד ) דוגמא לפנימיות עתיק כמו שבא\nבפנימיות אבא , מענין הדעת כו .\"?'\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – ריש תו \" מ סה \" מ\nתשכ \" ב :)"],[9200110105,"105\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n[1] מחק את התיבות : \" ולפי \" ז מהו \", \" ו הרי )( \" הוא ירידה כו '\"; וכתב :\",\nו הדמיון לענין הדעת ][ ש הרי הדעת עם היותו כמו פנימיות הכתר מ \" מ ][\nבא בהבנה ( במנין הספי )'\n[2 ] מחק את התיבות : \" שלכן מביאים \", \" דוגמא לפנימיות עתיק כמו\nשבא בפנימיות אבא , מענין הדעת כו '\"; ועל התיבות : \"( קונט ' קיח\nספ \" ד )\", כתב :\nוהרי , כמדומה , בעת האמירה ציינתי להמשך זה . ועיי \" ש לאחרי סי \" א .\nקכב\nועש \" ק האזינו , י \" ב תשרי , תשכ \" ב ][\nמענה לר ' אפרים וואלף שכתב :\n\" ישנם מבין אנ \" ש האומרים שעניני כק \" ש יכולים זיך אויספירען במלואן\nרק ע \" י צעירים . – לפי \" ד אני כבר לא בין הצעירים – והנני שואל האם\nכדאי למסור את כובד האחריות למי מהצעירים ( לי אין הצעה מפורטת\nוגם לא אמרו לי שם ) ואני אהיה כעין עוזר אצלו – או שבכלל אעשה\nמשהו אחר .\nשאלתי מעין זה לפני כמה שנים ולא קבלתי מענה ; והנני כותב עד \" ז\nעוה \" פ כי אינני רואה הצדקה שהמוסדות – הן הישיבה והן ביסל \" מ או\nאפילו ביה \" ס בלוד – יסבלו עי \" ז שאני לא בסדר וכד .'\nהנני מבקש סליחה מכ \" ק אדמו \" ר שליט \" א : אמנם מחשבות כאלו\nמטרידים לפעמים והנני מבקש שכ \" ק אדמו \" ר יבהיר כל המצב וכל\nהדברים יתבררו ללא ספיקות , שכל אחד ידע תפקידו ויוכלו למלאות\nרצון כ \" ק אדמו \" ר שליט \" א בשלימות , ושכל המניעות וההסתרים\nיתבטלו .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( ס ' \" ימי תמימים \" ח \" ג ע ' 90 . תשורה\nמוזיקנט ל \" ג בעומר תשס \" ב ע ' 50 :)\n[1 ] סימן את התיבות : \" שעניני כק \" ש יכולים זיך אויספירען במלואן רק\nע \" י צעירים \", וכתב :\nברוח ובמרץ , ואין זה נוגע כלל לשנים , ובעוה \" ר כו \" כ צעירים הישנים\nשינה עמוקה"],[9200110106,"106\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n[2 על כללות המכתב , כתב :]\nכבר עניתיו שינהל המוסדות והענינים בשמחה ובט \" ל וזכות הרבים\nוהתעוררות ר \" ר דנשיאינו – מסייעתו הלוך והוסיף\nקכג\nועש \" ק בראשית , כ \" ו תשרי , תשכ \" ב ][\nמענה למרת יהודית גראנער ( אשת המזכיר הרי \" ל גראנער ) על מכתבה –\nבהמשך להמדובר בהתועדות יום שמחת תורה , ע \" ד הנהגת הרבנית\nרבקה נ \" ע שהייתה ממשכנת את התכשיטים שקיבלה מבעלה אדמו \" ר\nמהר \" ש למטרות צדקת הכנסת כלה , והלימוד וההוראה מזה בשלילת\nחיי מותרות – בו כתבה אשר מוסרת את טבעת היהלום שלה לכ \" ק\nאדמו \" ר שליט \" א ( תשורה כהן י \" ב תמוז תשס \" ד ע ' 24 . קובץ ועד תלמידי\nהתמימים חה \" ס תשע \" ד ע ' 14 :)\nבטח בהסכם בעלה שי ' וכוונתה רצוי .' – ומצו \" פ הטבעת . און זאל עם\nטראגען מתוך בריאות הנכונה שמחה וט \" ל לאורך ימים ושנים טובות .\n– אבל לא תעשה האָליוואוד קיטשען גם כשירחיב ה ' פרנסתם עוד\nיותר .\nקכד\nאדר \" ח מרחשון , תשכ \" ב ][\nממענה להת ' משה יחיאל פעלער ( תשורה פעלער י \" ז מנ \" א תשפ \" א ע ' 8 :)\n[1 על ענין מסויים שכתב בקשר לחתונתו , כתב כ \" ק אדמו \" ר שליט \" א :]\n(2 ) בכגון זה מובן , אשר העדר מענה פירושו – שצ \" ל כמו שהוא אצל\nתמימים ותלמידי תו \" ת שמתחתנים עתה בשטומו \" צ\n[2 ] במכתבו כתב : \" אבי שי ' וגם כלתי תי ' רוצים מאד לדעת אודות\nההסתדרות שלנו אחר החתונה . מכ \" ק אד \" ש שמענו שעלינו להסתדר\nבמיניאפוליס , ומהרב חודאקוב שי ' קבלתי ההצעה להיות Regional\nDirector של המל \" ח במיניאפוליס כמו שנמצאים Directors Regional\nבדעטראיט ובמיאמי .\""],[9200110107,"107\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nמענה כ \" ק אדמו \" ר שליט \" א :\n(3 ) הצעה נכונה . ולנהל הענינים באופן שבמשך הזמן יהי ' גם רב שם\n( אם שלע \" ע מפני המצב שם , אולי אין כדאי לאמר זה בפירוש )\n[3 ] במכתבו כתב : \". . לדעת אם יתחיל השליחות שלנו תיכף אחרי\nהחתונה .\"?\nכ \" ק אדמו \" ר שליט \" א סימן קו תחת התיבות \" אחרי החתונה \", וכתב :\n(4 ) באם יש שם נשים צעירות יר \" ש – עכ \" פ אחדות .\nקכה\nט \" ו מרחשון , תשכ \" ב ][\nמענה לר ' יוסף מנחם מענדל טענענבוים שכתב : \" הנני בזה להודיע לכ \" ק\nכי הר \" י שוועי שי ' התחיל אתמול – אחר ארוחת הצהרים – ללמוד עם\nהכתה והתעסקות בהדארמיטארע . ויתן השי \" ת שתהי ' בהצלחה \" ( ס '\nתולדות התמימים בארצות הברית \" ע '\" 613 :)\nאזכיר עה \" צ .\nקכו\nאור לט ' כסלו , תשכ \" ב ][\nמענה להשליח ר ' ירחמיאל בנימין הלוי קליין על דו \" ח שכתב ( להנהלת\nהמל \" ח ) מנסיעתו לשליחותו באוסטרליא ( מצילום כתי \" ק – קובץ \" מיין\nגענעראל \" ח \" ב ע ' 8-10 :)\n[1 ] במכתבו כתב בין השאר – בתיאור משך נחיתת - הביניים בלונדון :\n\" ואח \" כ נסעתי להראיון בהדזשואיש קראניקעל . .\".\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות \" נסעתי להראיון ,\"\nוכתב :\nפרטים ?\nוסימן תיבות אלו בחץ ."],[9200110108,"108\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n[2 על כללות המכתב , כתב כ \" ק אדמו \" ר שליט \" א :]\n(2 ( הפ \" נ נלקח ))\nאזכיר עה \" צ\nקכז\nועש \" ק וישב , כ \" ג כסלו , תשכ \" ב ][\nמענה להשליח ר ' ירחמיאל בנימין הלוי קליין על דו \" ח נוסף שכתב\n( להנהלת המל \" ח ) מנסיעתו לשליחותו באוסטרליא ( מצילום כתי \" ק –\nקובץ \" מיין גענעראל \" ח \" ב ע ' 12-13 :)\nפננ\nקכח\nט \" ז שבט , תשכ \" ב ][\nמענה לא ' שביקש עצה לנטייתו לכעוס , וכן למצב השלום - בית בביתו\nתשורה קרעמער י \" ד אלול תשע \" ג ע '( 23 :)\nבנוגע לענין הכעס – דברים מבהילים כתוב עד \" ז בכתהאריז \" ל ( ומרומז\nגם בנגלה ). וישתדל להיות חקוק זה בזכרונו . וכן מש \" כ בתניא רפמ \" א :\nוהנה ה ' נצב עליו ובוחן כו ' – ואיך זה יתכעס בנוכחיותו של ממה \" מ\nהקב \" ה ! כן יחליט – כשיכעוס ימתין 60 סעקונדעס טרם ידבר בזה\nובמילא ישקוט הכעס ברובו .)(\nביחסו לזוג ' תי ': יחקוק בזכרונו ציווי חז \" ל ( חולין פ \" ד , ב ) שצריך לכבד\nאת אשתו יותר מלפי היכולת וצריך להזהר מלצערה אפילו בדברים\nב \" מ נט , א .)(\nקכט\nכ \" ג שבט , תשכ \" ב ][\nממענה לר ' בן ציון שם - טוב על מכתבו בעניני עסקנות ( מהעתקת\nהמזכיר :)\nאזכיר על הציון"],[9200110109,"109\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nקל\n[ שבט , תשכ \" ב ( 1 ])\nמענה לתלמידי ה \" קבוצה \" מאה \" ק הלומדים בישיבת תו \" ת המרכזית\nשכתבו – בקשר לההשתדלות להארכת זמן שהותם בחצרות קדשנו :\n\" מכיון שכנראה שבקשתנו בפרטיות שהגשנו ע \" י הקונסוליה למשרד\nהבטחון וכן בקשת הנהלת הישיבה לא התקבלה , ברצוננו להגיש היום\nבקשה חדשה לתקופה של 3 חדשים וזהו נוסח בקשתנו :\n\" נא לאשר שהותי בארה \" ב לתקופה של 4 חדשים . הנימוק הוא , מכיון\nשאנו נמצאים כבר בארה \" ב אצל כ \" ק אדמו \" ר שליט \" א מליובאוויטש ,\nומשרד הבטחון הואיל לאשר את בקשתנו הקודמת , מבקשים אנו\nלהאריך לערך 4 חדשים מכיון שכידוע הנסיעה לרבי אינה קלה , ועוד פעם\nלבוא זה דבר שתלוי בהרב ה קשיים , לכן מבקשים אנו להבין את מצבנו\nולאשר את הבקשה הנ \" ל .\"\nהרב דזיקאבסאהן שי ' יסע היום לוינגרטן וידבר אתו ע \" ד הבקשה הזאת\nושהנ \" ל יעשה השתדלויות לועדה המטפלת בענין זה שיאשרו לנו בקשה\nזאת לכה \" פ .\"\nמענה כ \" ק אדמו \" ר שליט \" א (\" בית משיח \" גליון 827 ע ' 42 והעתקה :).\nנכון הדבר . ואולי למשך שיכלול את חג הפסח ( ואפשר להוסיף זה\nבנימוק הבקשה .)\nקלא\n[ שבט , תשכ \" ב ( 2 ])\nמענה לא ' התמימים מתלמידי ה \" קבוצה \" מאה \" ק הלומדים בישיבת\nתו \" ת המרכזית שכתב – בקשר לההשתדלות להארכת זמן שהותם\nבחצרות קדשנו :\n\" דברנו היום אחה \" צ עם הר ' דזיקאבסאהן והוא מסר לנו הידיעות\nמהסוכונות שאמרו שהי ' להם ידיעה שלילית מהקונסוליה . בכל אופן\nעפ \" י הצעת הר ' דזיקאבסאהן שלחנו את הבקשות לקונסוליה , ואח \" כ\nדברתי בטלפון עם הקונסוליה ואמרתי להם ששלחתי מכתב בקשה\nלתקופה יותר קצרה , והם ענו שה גיעה כבר תשובה שלילית אליהם\nושלחו כבר היום מכתבים לעשרת הבחורים שעליהם לחזור ."],[9200110110,"110\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nושאלתי על איזו בקשה היתה התשובה ואמרה לי שעל שנה . אמרתי להם\n– אבל עכשיו ברצוני לשנות הבקשה לתקופה יותר קצרה עד אחרי חג\nהפסח . וענו לי שהם לא יכולים לקבל את המכתב רק מה שהם יכולים\nלעזור לנו הוא שנשלח מברק למר ניב בו אנו מבקשים בקשה זו לאשר\nלכה \" פ עד לאחר חגה \" פ . והם חיכו לתשובה מניב ע \" ז והמכתב הי ' מונח\nאצלם בינתיים . וע \" כ שואלים אנו מכ \" ק אדמו \" ר שליט \" א אם לשלוח\nמברק , ואם אנחנו לבד או שההנהלה תשלח את המברק , וכן שואלים אנו\nאם כדאי לטלפן במקום להבריק .\n\" אנו מבקשים להאריך את שהותנו כאן עד אחר חג - הפסח כיון שאנו\nמעונינים מאד להיות במחיצתו של הרבי בפסח שהוא משהו מיוחד ,\nונסיעה לרבי פעם שני ' כרוכה בקשיים רבים . נא להבריק תשובה\nבהקדם .\"\"\nמענה כ \" ק אדמו \" ר שליט \" א (\" בית משיח \" גליון 827 ע ' 42-43 והעתקה :).\nכ \" ק אדמו \" ר שליט \" א מחק חלק מהדברים שבמכתבם , וכתב :\nיתייעצו בכהנ \" ל ( לבד הנמחק ) עם ההנהלה .\nקלב\nכ \" ב אד \" ש , תשכ \" ב ][\nמענה להת ' שמואל פסח באגאמילסקי שכתב :\n\" הנני למסור נוסח השטר הרשאה למכירת חמץ שבדעתי לשלוח אי \" ה\nלמקומות שבקרתי שאין מי לסדר זה שם .\nוהנני לשאול בהתאם לההוספה עפ \" י הוראת כ \" ק אד \" ש \" ישראל המוכר\nאו בא כחו יהי ' באם ירצה מורשה מהנכרי הקונה ושלא על מנת לקבל\nפרס למכור בשבילו או לתת במתנה מהענינים הנמכרים \" [ ראה ליקוט\nמענות קודש תש \" כ מענ ה כא :]\nא ) אם להוסיף זה בסוף השטר קודם תי ' \" וכ \" ז נעשה . .\".\nב ) כיון שנוסח זה נכתב בהשטר שהמוכרים חותמים עליו אם לשנות\nהנוסח קצת ולכתוב \" ואנו המוכרים או בא כחנו כשנרצה נהי ' מורשה\nמהנכרי . .\", או נוסח אחר \" וכ \" א מאתנו המוכרים או בא כחו יהי ' באם\nירצה מורשה מהנכרי . .\".\nג ) אם למחוק תיבות \"( וכ \" ז נעשה ) בת \" כ ובקאג \" ס ובכל אוהיו \" מ .\"\""],[9200110111,"111\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nמענה כ \" ק אדמו \" ר שליט \" א ( קובץ \" שאלות פירושים וביאורים \" חוברת\nב ע ' 23-24 :)\nמחק את התיבות : \" ואנו המוכרים . . נהי ' מורשה מהנכרי . .\", וכתב :\nיברר בכהנ \" ל ובכללות נוסח השטר – פס \" ד רבנים מורי הוראה בפועל ,\nויעשה כהוראתם .\nוכן בנוגע לקרה \" ת וכו ' – שהציע מאז .\nוראה לקמן מענות :[ קלד , קלה , קמ .]\nקלג\nכ \" ו אד \" ש , תשכ \" ב ][\nמענה להרב יואל הכהן כהן שכתב – בקשר להמדובר בהתועדות ש \" פ\nשמיני , ע \" ד הלימוד מג ' הדיעות בזמן הציווי על עשיית ונדבת המשכן ,\nכנגד ג ' הסוגים שבבנ \" י צדיקים בינונים ורשעים : \" היות שלא תפסנו את\nקישור הענינים שבהשיחות דשבת , ובהיות שזה נוגע לכללות נושא\nהענינים שבהשיחות , רשמתי בפרטיות ( כי בקצרה קשה לברר את\nהספיקות ) את הספיקות . ואולי אפשר לענות על זה בקצרה עכ \" פ , כי זה\nנוגע לכללות רשימת השיחה \" ( מצילום כתי \" ק – ריש תו \" מ התועדויות\nחל \" ג ( תשכ \" ב ח \" ב :))\nבקצרה\nלהדיעה דגם נתינת בנ \" י למשכן קודם העגל – לצדיקים ( פסקה\nזוהמתן . חירות מיצהר )\n[ להדיעה דגם ] אמירת הק ' למשה אחרי ותיכף ליוהכ \" פ – בינונים\n( שנאמר – סלחתי . וצדיקים – ראה הק ' שהם מועטין .)\n[ להדיעה ] דציווי הק ' לפני העגל ועמד בתקפו ( שהרי לא נצטווה למשה\nשנית ) גם ביום עשייתו ( ובזה חידוש דיעה זו ) – לרשעים .\nענין הדיחוי שאינו – נלמד מדיעה הא '. אין ללמדו מדיעה הג ' ( שלא\nנדחה \" הציווי )\" – כי אז הציווי במח ' . ובמח ' לא הי ' חטא ( עיין אבן\nעזרא .)"],[9200110112,"112\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nקלד\nכ \" ח אד \" ש , תשכ \" ב ][\nמענה להת ' שמואל פסח באגאמילסקי שכתב – בהמשך להמענה שקיבל\n( לעיל מענה קלב ): \" שאלתי ג ' רבנים וזהו חוו \" ד : הרב דווארקין . . הרב\nיאלעס . . הרב הרליג . .; בכללות נוסח השטר – כולם מסכימים שטוב .\nוהיות שיש בזה חילוקי דעות , הנני לשאול מה לעשות בפועל \" ( קובץ\nשאלות פירושים וביאורים \" חוברת ב ע '\" 24-25 :)\nודעת הרב פיעקארסקי שי ?'\nיעשה כהכרעת הרוב ( כולל [ ודעת הרב פיעקארסקי שי ' ])\n[ הגהות כ \" ק אדמו \" ר שליט \" א על נוסח שטר - ההרשאה – ראה קובץ\nשאלות פירושים וביאורים \" שם ע '\" 26-27 .]\nקלה\nער \" ח ניסן , תשכ \" ב ][\nמענה להת ' שמואל פסח באגאמילסקי שכתב – בהמשך להמענה שקיבל\n( לעיל מענה קלד ) – את דעת הרב ישראל יצחק פיעקארסקי , וכתב :\n\" וכיון שבנוגע לב ' הפרטים הוא מחצה על מחצה , הנני לשאול איך\nלהכריע \" ( קובץ \" שאלות פירושים וביאורים \" חוברת ב ע ' 25 :)\nישאל חמישי שיכריע\nקלו\nחורף , תשכ \" ב ][\nמענה להרב פינחס קארף ( מהעתקה . המענה מתפרסם בזה לראשונה\nבאדיבות משפחת הנמען ע \" ה וזכות הרבים תלוי ' בהם :)\nעל מה שכתב ע \" ד רצונו לצאת בשליחות כ \" ק אדמו \" ר שליט \" א – כתב :\n(1 ) הרי – גם בעניניו עתה – ה \" ז שליחות , באם יהיו במסירה ונתינה\nוכו ' ובשמחה כו ' – כרצון המשלח ."],[9200110113,"113\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nעל מה שכתב ע \" ד סדר הנהגה – כתב :\n(2 ) יברר אצל המשפיעים וזקני אנ \" ש – שיודעים הנוהג מלפנים\nברוסיא פולין וכו '\nעל כללות המכתב – כתב :\n(3) אזכיר עה \" צ\n(4) קבלה\nעל מה שכתב ע \" ד התעסקות בענינים הגשמיים של ישיבת \" אחי\nתמימים \" בנוארק – כתב :\n(5 ) יתייעץ בזה עם הנהלת אח \" ת דנוארק ואנ \" ש דשם – היודעים פרטי\nהמצב וכו .'\nעל מה שכתב ע \" ד מצבו של ילד מסויים בגן - הילדים אותו מנהלת זוגתו\n– כתב :\n(6) ת \" ח על הבשו \" ט\nקלז\n[ לפני חדש ניסן , תשכ \" ב ( 1 ])\nמענה להמזכיר הרי \" ל גראנער על מכתבו – בו כמה שאלות בקשר לס '\nמאמרי אדמו \" ר מהריי \" ץ שנדפסו בקונטרסים ( במשך השנים תרפ \" ח\nואילך ), היו \" ל ע \" י מערכת \" אוצר החסידים \" ( מצילום כתי \" ק – תשורה\nדייטש ט ' סיון תשע \" ב ע ' 13 :)\n[1 במכתבו כתב : \" לברר . . שם הספר .\"]\nמענה כ \" ק אדמו \" ר שליט \" א :\nספר המאמרים\n– קונטרסים –\n[2 ] במכתבו כתב : \" באשר מספר העמודים הוא 832 לערך , אם לעשות שני\nכרכים .\"\nכ \" ק אדמו \" ר שליט \" א מחק תיבת \" אם \" וסימן בחץ ובקו את התיבות\nלעשות שני כרכים .\"\""],[9200110114,"114\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n[3 ] במכתבו כתב : \" ואם בשני כרכים – איך לחלקם .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nלפי ערך בשווה .\n[4 ] במכתבו כתב : \" ההערות שבסוף קונטרס כח – אם להדפיסם על\nמקומם או בסוף הכרך .\"\nכ \" ק אדמו \" ר שליט \" א מחק תיבת \" אם \", וכתב :\nבאם אפשר , כמובן להדפיסם על מקומם ][\n[5 על כללות המכתב , כתב :]\nהנדפס בלקו \" ד – לא להכניס\nמפתח ענינים\nקלח\n[ לפני חדש ניסן , תשכ \" ב ( 2 ])\n\" צעטל \" בכתי \" ק שכתב כ \" ק אדמו \" ר שליט \" א להמתעסקים בהכנת\n\" ספר המאמרים – קונטרסים \" היו \" ל ע \" י מערכת \" אוצר החסידים \"\n( מצילום כתי \" ק – תשורה דייטש ט ' סיון תשע \" ב ע ' 20 :)\nלהדפיס בתור הוספה [ לסַדר מחדש ]\nהמו \" ל מאז\nגדולים מעשה צדיקים – ורשא תרפ \" ה\nביום השני [ ורשא תרפ \" ה ]\nלך אמר לבי תרצו [ מצורף ]\nאחרי ה \" א תלכו תרצ \" ז [ בטח אצל הרי \" ד שי '"],[9200110115,"115\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nקלט\n[ לפני חדש ניסן , תשכ \" ב ( 3 ])\nמענה לשאלה – בצירוף לשער \" קונטרס ב \" בסדרת מאמרי אדמו \" ר\nמהריי \" ץ , הוא \" קונטרס דרושי חתונה – נאמרו על חתונת בתו הרבנית\nחי ' מושקע שתליט \" א כסלו , תרפ \" ט \": \" לייבל שי ' שואל אם להוסיף :\nנאמרו על חתונת כ \" ק אדמו \" ר [. .] שליט \" א ובתו הרבנית כו '\" ( מצילום\nכתי \" ק – תשורה דייטש ט ' סיון תשע \" ב ע ' 21 :)\nלא לשנות\nעל השער המצורף , עליו נכתב השם \" חי ' מושקע \"[ – תיקן ל \" חי '\nמושק א .]\"\nקמ\nר \" ח ניסן , תשכ \" ב ][\nמענה להת ' שמואל פסח באגאמילסקי שכתב – בהמשך להמענה שקיבל\n( לעיל מענה קלה ) – את הכרעת הרב ניסן טעלושקין בנושא ( קובץ\nשאלות פירושים וביאורים \" חוברת ב ע '\" 25 :)\nקראתי\nקמא\nתחלת ניסן , תשכ \" ב ][\nמענה לר ' יוסף הלוי וויינבערג שכתב : \" באם דעת כ \" ק שליט \" א שנלמוד\nהשיעור תניא במוש \" ק הבע \" ל ( מבלי הביט על הטרדות שכולם טרודים\nבהכנות להחג ) – מוסג \" ב עמוד וחצי ממה ששייך להשיעור הזה . ואם כן\nנלמוד , אולי הי ' כדאי למסור שמוש \" ק חוה \" מ לא נלמוד השיעור כי אם\nנמסור משיחות ק ' דימים הראשונים דחג הפסח ?\" ( מצילום כתי \" ק –\nקונטרס ועד הנחות בלה \" ק ש \" פ אחרי תשע \" ד ע ' 22 :)\n[1 סימן בחץ ובעיגול את מה שכתב \" שנלמוד השיעור תניא כו .\"']\n[2 סימן בעיגול את מה שכתב : \" ממה ששייך להשיעור הזה \", וכתב :]\nכן להזכיר – בקיצור – עוה \" פ ע \" ד שילוח שמורה כו '"],[9200110116,"116\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nקמב\nה ' ניסן , תשכ \" ב ][\nמענה לא ' על מכתבו בקשר לחינוך יוצאי - חלציו , בו כתב אשר נאלץ\nלשלחם ללמוד בבית - ספר ממשלתי –\nנדפס באגרות - קודש חכ \" ב ע ' קצט .\nקמג\nי \" ב ניסן , תשכ \" ב ][\nמענה לר ' שניאור זלמן הלוי דוכמאן על מכתבו בו איחולים וברכות לרגל\nיום הבהיר י \" א ניסן ששים שנה להולדת כ \" ק אדמו \" ר שליט \" א ( מצילום\nכתי \" ק – ס ' \" לשמע אוזן \" ( הוצאת תשע \" ו ) ע ' 348 :)\nקראתי בת \" ח\n___\nוכבר מילתי ' אמורה בהתועדות השייכת ליום נשיא לבני אשר כו ' והוא\nיתן מעדני מלך .\nקמד\nו ' אייר , תשכ \" ב ][\nמענה לר ' דובער יוניק על מכתבו בקשר להברית - מילה של בנו שמ שו ן\nאהרן ( מהעתקה . המענה מתפרסם בזה לראשונה באדיבות משפחת\nהנמען ע \" ה וזכות הרבים תלוי ' בהם :)\nאזכיר עה \" צ ויגדלוהו לתחומע \" ט\nקמה\nי \" ב אייר , תשכ \" ב ][\nמענה להנהלת \" צעירי אגודת חב \" ד \" שכתבו : \" מוסג \" פ ידיעות מעניני\nצאגו \" ח שבדעתנו לפרסם במימיאגראף מפעם לפעם , בהתאם לבקשות"],[9200110117,"117\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nאנ \" ש דכאן וביחוד בערי השדה , המתענינים בהענינים הנעשים . משתתפי\nאסיפת צאגו \" ח ( דערי השדה ) בחוהמ \" ס , ביקשו ג \" כ להודיעם לעתים\nתכופות מהפעולות הנעשות כדי שיעזור להם בעבודתם . ידיעות קצרות\nאלו שנערכו ע \" י הת ' י \" ל שי ' אלעווסקי , בנקל לערכם , ובטח יענינו את\nהקוראים כי א פשר להוציאם בזמנם ולהודיע בהם ג \" כ אודות הענינים\nהצריכים להעשות בעתיד הקרוב . מצורף פה הידיעות אודות הביקור\nבבאליטמאר , האורחים מאנגליא ואסיפת צאגו \" ח בטורונטו , ושואלים\nאם נכון הדבר ?\" ( מצילום כתי \" ק – \" בית משיח \" גליון 191 ע ' 31 :)\nאף שבכלל נכון , אבל :\nכמה פרטים נכנסו , שאף אשר כ \" ע ידעי שנוהגים כן , אין מכריזים\nעליהם וכו .'\n___\nכן צריך החלטה לאיזה חוג מתכוונים ובזה תלוי פירוט התוכן\n___\nועוד ועוד\n___\nהבחנו ( עכ \" פ בשטחיות ) המצו \" פ עכ \" פ 2 אנשים קודם שנשלח לי ?\nקמו\nלאחר ל \" ג בעומר , תשכ \" ב ][\nמענה להמניחים על שאלותיהם במאמר ד \" ה שיר המעלות שנאמר\nבהתועדות ל \" ג בעומר ( מצילום כתי \" ק – תשורה בעלינאוו ד ' תמוז\nתשנ \" ח ע ' 30 :)\n[1 ] במכתבם כתבו : \" בתחילת המאמר מביא בשם מאמר של כ \" ק מו \" ח\nאדמו \" ר שמביא את פירוש הזוהר ע \" פ זה , שע \" י האחוה וקישור דנש \" י\nנמשך גם יחד , שגם הקב \" ה מתאחד עמהם , שהו \" ע המשכת כח הא \" ס\nבענין הולדת ילדים .\"\nכ \" ק אדמו \" ר שליט \" א מחק תיבת \" פירוש \", וכתב :\nשמביא את הזוהר ע \" פ זה ][ ומפרש [ שע \" י האחוה וקישור דנש \" י נמשך\nגם יחד ] בנין עדי עד \" \" דור ישרים יבורך \"\" – א \" ס בעולמות [ שגם"],[9200110118,"118\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nהקב \" ה מתאחד עמהם ] וכמפורש בזח \" ג נט , ב [ שהו \" ע המשכת כח\nהא \" ס בענין הולדת ילדים ]\n[2 ] במכתבם כתבו : \" שאלה : אם הכוונה לד \" ה שיר המעלות תרצ \" ב\n( דלכאורה , שם מביא את הפירוש ש \" גם \" מרבה ישראל דלתתא , ולא את\nהפירוש שנעתק במאמר זה ?) .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n( א ) מחק את התיבות : \" שאלה : אם \", וסימן בחץ את התיבות \" הכוונה\nלד \" ה כו .\"'\nב ) על מה שכתבו : \" דלכאורה , שם מביא את הפירוש כו '\", כתב :(\nדלכאורה , שם ][ בתחלתו מביא את הפירוש כו ]'[\n[3 במכתבם כתבו : \" בע ' ג ' שיטה המתחלת דאורייתא , מפרש על הראש ,]\nבחי ' רישא דעתיק . שאלה : ביהל אור להצ \" צ מביא בשם הזוהר , רישא\nדאריך . אם כאן נתפרש באופן אחר , או שזה טעות בההנחה .\"?\nכ \" ק אדמו \" ר שליט \" א מחק את סימן - השאלה , והשאיר את התיבות\nשזה טעות בההנחה \"; סימן קו תחת התיבות \" רישא דאריך \", וכתב :\"\nכצ \" ל\nקמז\nאייר , תשכ \" ב ][\nמענה לר ' אליהו נחום שקליאר על שאלותיו : ( א ) במפתח ענינים לתניא\n– בעריכת כ \" ק אדמו \" ר שליט \" א – בערך \" שבת \" נסמן לפרקים \" אבד גי \"\n( חלק א פרקים ב - ד , חלק ג פרק י ), ולכאורה הלא מדובר ע \" ד שבת גם\nבפרקים : אז , אלט , אמו ; ( ב ) \" בשיעורי תניא בשבוע העברה בפרק מט\nבסופו לא אוכל להבין הנקודה אחרי \" בחי ' הדיבור בד \" ת \". כי הלא אין\nזה סיום הענין . וביותר אינו מובן כי השיע ור תניא מסתיים שם , וגם בכלל\nאינו מובן קישור הענינים בשורות אלו \" –\nנדפס באגרות - קודש חכ \" ב ע ' רכח ."],[9200110119,"119\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nקמח\nכ \" ף סיון , תשכ \" ב ][\nמענה לר ' שניאור זלמן הלוי דוכמאן על מכתבו ( מצילום כתי \" ק – ס '\nלשמע אוזן \" ( הוצאת תשע \" ו ) ע '\" 40 , 363 :)\nת \" ח על הסיפור ( ל ' יחיד )!\nאזכיר זוג ' תי ' עה \" צ\nקמט\nכ \" ה סיון , תשכ \" ב ][\nמענה לר ' שניאור זלמן הלוי דוכמאן על מכתבו ( מצילום כתי \" ק – ס '\nלשמע אוזן \" ( הוצאת תשע \" ו ) ע '\" 40 , 363 :)\nת \" ח על הבשו \" ט מזוג ' תי .'\nות \" ח על הסיפורים שהוסיף ובטח ימשיך והרי הימים ימי סגולה בין\nטו ' סיון ויב - יג תמוז .\n[ וראה לקמן מענה קנ .]\nקנ\nלאחר כ \" ה סיון , תשכ \" ב ][\nמענה לר ' שניאור זלמן הלוי דוכמאן על מכתבו – בהמשך להמענה שקיבל\n( לעיל מענה קמט ) \" ובטח ימשיך והרי הימים ימי סגולה בין טו ' סיון ויב -\nיג תמוז \" – בו שאל במה מתייחדים ימים אלו כ \" ימי סגולה \" ( ס ' \" לשמע\nאוזן \" ( הוצאת תש \" נ ) ע ' טז :)\nע \" פ דברי כ \" ק אדמו \" ר נ \" ע בנוגע לאדמו \" ר הזקן בפעטערבורג , שזהו\nכמו שהזית נותן שמנו על ידי שעוצרין אותו ."],[9200110120,"120\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nקנא\nג ' תמוז , תשכ \" ב ][\nמענה לר ' שניאור זלמן הלוי דוכמאן על מכתבו בו סיפורים וזכרונות\n( מצילום כתי \" ק – ס ' \" לשמע אוזן \" ( הוצאת תשע \" ו ) ע ' 41 :)\nת \" ח על הפנינים – הנהגות ודברי קודש .\nקנב\nלאחר ש \" פ מטו \" מ , כ \" ו תמוז , תשכ \" ב ][\nמענה להמניחים על שאלותיהם במאמר ד \" ה גדול יהי ' כבוד הבית גו '\nשנאמר בהתועדות ש \" פ מטו \" מ ( מצילום כתי \" ק – תשורה פולטורק ג '\nכסלו תשס \" ה ע ' 34 :)\n[1 במכתבם כתבו :]\n\" נתבאר ההפרש בענין ההתהוות שמצד שם הוי ' שהיא בדרך ממילא\nכמ \" ש כי הוא צוה ונבראו , לההתהוות שמצד שם אלקים כמ \" ש בראשית\nברא אלקים , לפי שההתהוות שמשם הוי ' היא באי \" ע ומשם אלקים –\nבקירוב . ואח \" כ נתבאר הדוגמא מעילה ועלול , אור ומאור , שלהיותם\nבקירוב ( עלול בערך העילה ואור עכ \" פ מעין המאור , ולכן משל האור\nמכוון יותר ) הם בדרך ממילא .\nשאלה : הרי הדוגמא דעו \" ע כו ' סותר למה שנתבאר קודם ? אם זה טעות\nבהחזרה , ובתחילת הענין צריך לומר להיפך : שההתהוות שמשם הוי '\nהיא בקירוב ומשם אלקים בריחוק , ולכן משם הוי ' במילא ומשם אלקים\nבהתלבשות . ( וכאן נתבאר לא כהאופן שמבואר בד \" ה ע \" כ יאמרו תרצ \" א .\nואינם סותרים זה לזה , ע \" ד שמתווך בד \" ה אדם כי יהי ' תרס \" ו בענין\nעו \" ע ויש מאין , שלפעמים איתא שעו \" ע בהתלבשות ויש מאין במילא –\nובאופן זה מבואר בד \" ה ע \" כ יאמרו – ולפעמים איתא שעו \" ע במילא כו ',\n– ובאופן זה מבואר כאן ). או שבמאמר זה נתבארו ב ' האופנים : בתחילת\nהענין נתבאר באופן שמצד ריחוק בדרך ממילא , כבד \" ה ע \" כ יאמרו ,\nואח \" כ נתבאר באופן השני . אבל לפי \" ז חסרים כמה תיבות בהחזרה ,\nבכדי לקשר הדוגמא דעו \" ע כו ' למה שנתבאר קודם .\"?\nמענה כ \" ק אדמו \" ר שליט \" א :"],[9200110121,"121\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nא ) על מה שכתבו : \" נתבאר ההפרש בענין ההתהוות שמצד שם הוי ,\"'(\nכתב :\nההפרש בענין ההתהוות שמצד שם הוי ' שהיא בדרך ממילא כמ \" ש ][\nיהללו את שם הוי ' [ כי הוא צוה ונבראו , לההתהוות שמצד שם אלקים\nכמ \" ש בראשית ברא אלקים , לפי ] שאופן [ ש ההתהוות שמשם הוי ' היא\nבאי \" ע ] ( השייכות רק – צווה ) אבל אינה מהווה מהות נפרד והפכי ( ולכן\n– בדרך ממילא – ונבראו ) [ ומשם אלקים – בקירוב ]\nב ) על מה שכתבו : \" ואח \" כ נתבאר הדוגמא מעילה ועלול כו \"'( – מחק את\nהתיבות : \" ולכן משל האור מכוון )( יותר \", וכתב :\nהדוגמא מעילה ועלול , אור ומאור , שלהיותם בקירוב ][ המציאות – לא\nשאופן ההתהוות בקירוב – [( עלול בערך העילה ואור עכ \" פ מעין המאור ]\nו משל האור ][ ג \" כ אינו מכוון ][ לגמרי – שאור אינו מציאות בפ \" ע [) הם\nבדרך ממילא ]\n[2 ] במכתבם כתבו : \" נזכר הענין דכתר אע \" ג דאיהו אור קדמון צח\nומצוחצח אוכם הוא קדם עה \" ע . ונתפרש שזהו \" ע ישת חושך סתרו – מהו\nפירוש ישת חושך סתרו , ולאיזה ענין נאמר זה .\"?\nעל התיבות : \" מהו פירוש ישת חושך סתרו \", כתב כ \" ק אדמו \" ר שליט \" א :\nדעצמות הוא בכתר וקרי לי ' חשך\n[3 על כללות המכתב , כתב כ \" ק אדמו \" ר שליט \" א :]\nיאיר נתיב \" דהמאמר :\"\nבונה ירושלים – תרכ \" ט\nראה קראתי – תרס \" ה . עיי \" ש .\nלקו \" ת מטות ד \" ה ואשה .\nע \" כ יאמרו תרצ \" א .\nדבית האחרון קאי על ביהמ \" ק הג ' – זח \" א כח , א . ת \" ז ת \" ח . וראה ג \" כ\nבפי ' הראב \" ע ."],[9200110122,"122\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nקנג\nב ' מנ \" א , תשכ \" ב ][\nמענה להנהלת \" צעירי אגודת חב \" ד \" שכתבו : \" בקשר עם כרך השני של\nהלקוטי שיחות שהולך ונדפס כעת ( חלק נדפס כבר בפועל , והשאר , לבד\nהמפתח ענינים , מוכן לדפוס ), ויחזיק 175 עמודים לערך . הננו לשאול אם\nנכון לצרף לכרך זה , במדור בפני עצמו , המכתבים כללים ( שבאידיש )\nלר \" ה ולחה \" פ דכל השנים החל משנת השי \" ת \" ( מצילום כתי \" ק – נדפס\nלעיל . המענה מתפרסם בזה לראשונה באדיבות ר ' שניאור זלמן יצחק\nיהושע שי ' חאנין וזכות הרבים תלוי ' בו :)\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות : \" המכתבים כללים\nשבאידיש ) לר \" ה ולחה \" פ דכל השנים החל משנת השי \" ת \", וכתב :(\nאין נכון כי יודפסו בפ \" ע בעז \" ה .\nאבל ישנם כמה מכ ' על פרשיות השבוע\nקנד\nח ' מנ \" א , תשכ \" ב ][\nמענה להנהלת \" צעירי אגודת חב \" ד \" ( מצילום כתי \" ק – נדפס לעיל .\nהמענה מתפרסם בזה לראשונה באדיבות ר ' שניאור זלמן יצחק יהושע\nשי ' חאנין וזכות הרבים תלוי ' בו :)\n[1 ] במכתבם כתבו : \" בנוגע להוספה לליקוטי שיחות חלק ב ', אספנו כמה\nשיחות שהוגהו ויצאו כבר לאור בזמנים שונים , וברובם שייכים לפרשיות\nהשבוע , ולמועדי השנה . אמנם כמה מהם מדובר בהם ענינים שונים שאין\nשייכים להנ \" ל ( כמו שיחה לעסקני הישיבה שנאמרה בפ ' ויצא ומדובר בה\n( במא מר הפתיחה ) ע \" ד תו \" ת ולא אודות פרשת השבוע ( במאמר הסגירה\nמדובר ע \" ד פ ' ויצא – ונדפס כבר בחלק א ' של הלקוטי שיחות ). כן עוד\nשיחות לנשי חב \" ד שנאמרו בזמנים שונים ( והוגהו ) אבל אין מדובר בהם\nאודות הזמן , כ \" א אודות חובת נשי ישראל וכיו \" ב .\")\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את מה שכתבו : \" אמנם כמה מהם\nמדובר בהם ענינים שונים שאין שייכים להנ \" ל . . חובת נשי ישראל\nוכיו \" ב \", וכתב :\nא \" כ אין שייך להנ \" ל"],[9200110123,"123\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n[2 ] במכתבם כתבו : \" ולזה השאלה אם לסדר השיחות לפי סדר ימי השנה\n( היינו על פ ' השבוע ומועדים , כפי הסדר שנדפס בגוף הספר , ולפי סדר ימי\nהשנה שנאמרו בהן ) או לסדרם לפי סדר השנים והזמנים בהם נאמרו\n( כסלו תשי \" ט קודם לתשרי תש \" כ וכיו \" ב ). או לעשות ב ' הוספות : הוספה\nא ' מה ש שייך לפרשיות השבוע ומועדים ולסדרם כפי זמני השנה באופן\nשנדפסו בלקו \" ש , והוספה ב ' שיחות שונות לפי סדר הזמנים שנאמרו .\"\nכ \" ק אדמו \" ר שליט \" א מחק את מה שכתבו : \" או לסדרם . . סדר הזמנים\nשנאמרו \"; מחק את התיבות \" והננו שואלים אם \" וסימן בחץ ובעיגול את\nהתיבות \" לסדר השיחות לפי סדר ימי השנה .\"\n[3 ] במכתבם כתבו : \" כן אנו שואלים , אם כדאי לצרף כאן גם השיחות\nשנעתקו בקובץ ליובאוויטש ובאידישע היים ( ולא נכנסו בהלקו \" ש ) לפי\nסדר הנ \" ל .\"\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול קטע זה , וכתב :\nבאם שייך להנ \" ל\nקנה\nלאחר כ \" ף מנ \" א , תשכ \" ב ][\n\" צעטל \" בכתי \" ק שכתב כ \" ק אדמו \" ר שליט \" א להמניחים בו ציין את\nהמראי - מקומות להמדובר בהתועדות כ \" ף מנ \" א ( מצילום כתי \" ק – תו \" מ\nהתועדויות חל \" ד ( תשכ \" ב ח \" ג :))\nיאיר נתיב לההדרן\nכמות ואיכות – לקח טוב להר \" י ענגעל בסופו .\nחילוקי המשניות – ח \" מ ( בשו \" ע אה \" ע סל \" ח סק \" מ ). תוס ' אנשי שם\nלכלאים ( ז , דה )\nהוצאה ועירוב – לקו \" ת ד \" ה למנצח על השמינית . מצה זו תרם פנ \" ז\nואילך .\nשבות – אם מה \" ת מקור – רמב \" ם רפכ \" א מהל ' שבת ובמפרשיו שם .\nרמב \" ן לויקרא כג , כד .\nחילוק דאיסור תחומין ושאר מלאכות שבת – שו \" ת חת \" ס או \" ח קמט\nובהמצויין \" בהמועדים בהלכה \" ע ' יא ."],[9200110124,"124\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nאיסור תחומין בכלל –\nשו \" ע אדה \" ז ס ש צ \" ו\nנסמן בתו \" ש לפ ' בשלח במילואים\nקנו\nלאחר כ \" ף מנ \" א , תשכ \" ב ][\nמענה להמניחים שכתבו \" כמה שאלות בההדרן דכ ' מנ \" א \" ( מצילום\nכתי \" ק – תו \" מ התועדויות חל \" ד ( תשכ \" ב ח \" ג :))\n[1 במכתבם כתבו :] \" נתבאר טעמו של ר \" ש דס \" ל יכנס , לפי שאם ישאר\nחוץ לתחום משך כל המעל \" ע דשבת , הרי זה ענין של שהיית איסור ולכן\nיכנס , אף שמרבה באיסור , כי ריבוי הכמות מכריע את האיכות . שאלה :\nאם הפירוש \" יכנס ,\" שצריך ליכנס בכדי שלא ישהה את האיסור , או\nשמותר ליכנס ( כפירוש הפשוט ), וגם עי \" ז עצמו שמתירים לו ליכנס\nמונעים את שהיית האיסור , שזה נקרא שאינו נמצא חוץ למקומו , שהרי\nמותר ( ושייך ) למקום התחום . איך הכוונה .\"?\nעל התיבות \" כפירוש הפשוט \", כתב כ \" ק אדמו \" ר שליט \" א :\nאינו פשוט . ואדרבא – למה יתירו להכנס לספק אפי ' דרבנן – באם אין\nכל מעליותא וצורך בזה ?! לע \" ע – לא מצאתי מפורש לאיזה צד שיהי .'\n[2 ] במכתבם כתבו : \" לכאורה , סברא זו בטעמו של ר \" ש , שייכת רק\nברישא דמתניתן , מי שיצא חוץ לתחום , אבל לא בסיפא דמתניתן , מי\nשהחשיך חוץ לתחום , ומהו טעמו של ר \" ש בסיפא דמתניתן ? ( ובפרט\nשלדעת כמה ראשונים – במאירי , ובפירוש רבינו יונתן על הרי \" ף –\nשחולק רק בסיפא ולא ברישא .\")?\nמענה כ \" ק אדמו \" ר שליט \" א :\n( א ) על מה שכתבו : \" ומהו טעמו של ר \" ש בסיפא דמתניתן \", כתב :\nבאם מתירים לעובר במזיד – הרי א \" א להחמיר על הצדיק דוקא !\n( ב ) על מה שכתבו : \" ובפרט שלדעת כמה ראשונים – במאירי , ובפירוש\nרבינו יונתן על הרי \" ף – שחולק רק בסיפא ולא ברישא \"? – מחק את\nסימן - השאלה , וכתב :"],[9200110125,"125\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nמפורש בירוש ' דפליג בשניהם . ואולי לא הי ' לעיני הר \" י [ אבל המאירי\nמזכירו ]\n[3] במכתבם כתבו : \" ממה שנתבאר בהשיחה שאם ישאר חוץ לתחום כל\nהמעל \" ע יהי ' אז ענין של שהיית איסור , מוכח לכאורה שגדר ענין יציאה\nחוץ לתחום , אין האיסור פעולת היציאה עצמה כי אם , האיסור שבזה ,,\nהוא מצד התוצאה של הפעולה , והוא שהאדם יהי ' נמצא חוץ לתחום\nוע \" ד המבואר בלקו \" ת לג \" פ ( יד , א ) שענין איסור יציאה חוץ לתחום ,(\nשבחי ' נה \" י דקדושה לא יהיו במקום הקליפות ). ולכן , כל רגע שנמצא חוץ\nלתחום , הרי זה שהיית איסור . אם נכון ? ואם נכון , מהו האיסור בזה\nשילך חזרה לתוך העיר .\"?\nמענה כ \" ק אדמו \" ר שליט \" א :\nא )( על מה שכתבו : \" וע \" ד המבואר בלקו \" ת לג \" פ ( יד , א )\", כתב :\nעייג \" כ סי ' האריזל ובכ \" מ\nב )( על מה שכתבו : \" אם נכון \"? – מחק תיבת \" אם \" וסימן - השאלה ,\nוהשאיר תיבת \" נכון .\"\nג )( על מה שכתבו : \" ואם נכון , מהו האיסור בזה שילך חזרה לתוך העיר ,\"\nכתב :\nי \" ל שעי \" ז מכניס מהקליפות עמו לעיר . ובכלל – גם ע \" פ נגלה , כל\nעיסקא דשבתא כפול , דבר וגם – היפוכו . ועיין שבת צו , ב .\n[4] במכתבם כתבו : \" נתבאר פירוש מאמרו של ר \" ש \" שלא התירו לך אלא\nמשום שבות \", שמתרץ בזה מה דס \" ל עונבה , אף שאפשר שינתק העניבה\nועי \" ז יצטרך להרבות בעניבות , ריבוי כמות , ולא קושרה , ריבוי איכות ,\nשזה סותר לכאורה למה שס \" ל יכנס , שכמות עדיפא מאיכות , ועל זה\nמתרץ \" שלא התירו לך אלא משום שבו ת \". שאלה : לכאורה , הרי מה\nשס \" ל יכנס , הוא רק עד ט \" ו אמה , אבל ביותר מט \" ו אמה , מודה ר \" ש\nשלא יכנס אף שבזה ישהה את האיסור , ריבוי כמות , לפי שביותר מט \" ו\nאמה הוה ודאי איסור של ריבוי באיכות , ואז אין ריבוי הכמות מכריע\nודאי של איכות ( ורק בספק ס \" ל כן ) וא \" כ בענין קשירה ועניבה ,\nשהקשירה היא ודאי ריבוי באיכות , לא יכריע אותה ריבוי הכמות של\nעניבות , ולמה הוצרך לטעם דשבות .\"?\nמענה כ \" ק אדמו \" ר שליט \" א :"],[9200110126,"126\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nא )( על מה שכתבו : \" לפי שביותר מט \" ו אמה \", כתב :\nע \" ז הי ' קביעות האיסור דתחומין – שהי ' לא רק לכתחילה , אלא גם\nבדיעבד , כשכבר יצא . ואי \" ז שייך לנדו \" ד דכמות ואיכות כלל .\nב )( מחק את מה שכתבו : \" אין ריבוי הכמות מכריע ודאי של איכות ( ורק\nבספק ס \" ל כן ) .\"\nג )( על מה שכתבו : \" שהקשירה היא ודאי ריבוי באיכות \", כתב :\nלכמה מפרשים – רק שבות שמא יבוא לדאורייתא .\n[5] במכתבם כתבו : \" מדוע הוצרך אדה \" ז בשלחנו לעוד טעמים , מכיון\nשבאגה \" ת הכריע בפשיטות שריבוי הכמות מכריע את האיכות ?\n( ולכאורה אפשר לתרץ , שהלשון באגה \" ת \" בריבוי החטאים יכול להיות .\n. כרת או מיתה \". היינו שאם הריבוי הוא גדול ביותר ( וכהלשון : מחיצות\nקלות וקלושות לרוב מאד ) אז הכמות הוא עדיף מהאיכות , אבל בריבוי\nסתם אפשר שהאיכות עדיף . ולכן אפשר , שריבוי הכזיתים של איסור\nנבילה אינו ריבוי גדול כ \" כ שיכריע את איסור שחיטה בשבת . – אך לפי \" ז ,\nשהכלל שריבוי הכמות מכריע את האיכות תלוי בגודל הריבוי , הרי יש\nלחלק בין מי שיצא חוץ לתחום , שכל רגע ורגע של המעל \" ע יהי ' חוץ\nלתחום , לענין הריבוי דעניבה , שלא יצטרך לעונבה בכל רגע , ורק כמה\nפעמים לבד . וא \" כ למה הוצרך ר \" ש לטעם דשבות .\"?\nמענה כ \" ק אדמו \" ר שליט \" א :\nא )( על מה שכתבו : \" מדוע הוצרך אדה \" ז בשלחנו לעוד טעמים , מכיון\nשבאגה \" ת הכריע בפשיטות שריבוי הכמות מכריע את האיכות ?\", כתב :\nעיין שער הכולל בתחילתו\nוסימן תיבות אלו בחץ .\nב )( על מה שכתבו : \" אבל בריבוי סתם אפשר שהאיכות עדיף \", כתב :\nבדיני אדם אין לחלק כן . וכמו שבדין דשחיטה ונבילה – הוא אפילו\nכשאירע בסוף היום\nוע \" ד הענין דתשובה – דעיקרה בלב שרק כלפי שמיא גליא ומועיל .\n[6] על כללות המכתב , כתב כ \" ק אדמו \" ר שליט \" א :\nכנראה מצוה להיות בתוך התחום : עיין ב \" י ופריש א או \" ח ר \" ס שצה ."],[9200110127,"127\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nקנז\nלפני כ \" ג מנ \" א , תשכ \" ב ][\nמענה לר ' שניאור זלמן הלוי דוכמאן על מכתבו בו סיפורים וזכרונות ( ס '\nלשמע אוזן \" ( הוצאת תשע \" ו ) ע '\" 58 :)\nבטח יש להם \" אב \" ( ממי שמעם ) והתקוה שיכתבם גם אלי ואהנה\nקנח\nכ \" ג מנ \" א , תשכ \" ב ][\nמענה לר ' שניאור זלמן הלוי דוכמאן על מכתבו ( מצילום כתי \" ק – ס '\nלשמע אוזן \" ( הוצאת תשע \" ו ) ע '\" 58 :)\n[1 על כללות המכתב , כתב :]\nהרש \" ז שי ' הלוי\nת \" ח על הר \" ד – ונתקיים – שנהניתי .\n[2 בין הסיפורים שבמכתבו כתב ( נדפס אח \" כ בס ' \" לשמע אוזן \"]\n( בהוצאה הישנה – ע ' רל - רלא ; בהוצאה החדשה – ע ' 267 )): \" איך האב\nגעהערט אין ליובאוויטש פון א אידן , אז ביי זיי אין קאלאניע ארום\nניקאלייעוו איז געווען ר ' הלל , און ווי דער סדר האט מען געקליבן געלט\nפאר אים . איינער א איד איז דארט געווען , וואס ביי אים איז געווען אן\nאריינפאר - הויז , און עס פלעגן דארטן איינשטי ין פריצים און פריצטעס\n( מיר זיינען געווען אינגלעך , האט דער איד וואס האט דערציילט די מעשה\nגערעדט פארשטעלטערהייט ). איז יענער בעל אכסניא האט געגעבן 10\nרובל . אז מ ' האט געבראכט די גאנצע געלט וואס מען האט\nצענויפגעקליבן , נעמט ר ' הלל און ווארפט ארויס די מטבע , דעם צע נערל .\"\nבקשר לסיפור זה כתב כ \" ק אדמו \" ר שליט \" א :\nבהסיפור אשר \" אַרויסגעוארפן די מטבע \" – צ \" ע מהענין א ) דלא\nתשחית . ב ) דכאו \" א מבנ \" י מחויב בצדקה . ואדרבא : חטאך בצדקה\nפרוק .\nואולי א ) ידע שזה הכסף מאיסורי הנאה . ב ) אינו מדויק הספור , וצ \" ל\nשהחזיר הכסף ."],[9200110128,"128\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nקנט\n[ שלהי מנ \" א , תשכ \" ב ( 1 ])\nמענה להמזכיר הרח \" י קרינסקי שכתב : \" דברתי הערב עם ר \" צ שי '\nפאגעלמאן ואמר שדיבר עם אחי שי ' אתמול והיום , ובנתיים דיבר אחי\nעם זוגתו תחי ', והתוצאה היתה שכבר החליט לגדל זקן ( וגם זוגתו\nמסכמת לזה ), אבל אין יכולים לפעול על עצמם שיתחיל בזה מיד , אלא\nבמשך הזמן . הערב על ר \" צ שי ' לפגוש עם אחי וזוגתו על חתונה , וישתדל\nלדבר עם שניהם אודות הענין , אבל אומר שכפי הנראה יפעול זה לחזק\nאת ההחלטה הנ \" ל אבל לא שיתחיל בזה מיד \" ( מצילום כתי \" ק – תשורה\nקרינסקי כ \" ח סיון תשע \" ג ע ' 41 :)\nיראהו : ( נזיר כג , סע \" ג ) דע \" י הקדמת לילה אחד – זכתה לארבע דורות\nמלכות\nב ) אגה \" ק לאדה \" ז סכ \" א : ידוע לכל גודל מעלת הזריזות כו ' הנאמר\nונשנה בדרז \" ל כו ' עיי \" ש\nג ) משם מוכח דדוקא זריזות מראה על שמחה וחפץ למלאות רצון קונו\nולעשות נח \" ר ליוצרו\nד ) מסילת ישרים פ \" ו ואילך .\nקס\n[ שלהי מנ \" א , תשכ \" ב ( 2 ])\nמענה להמזכיר הרח \" י קרינסקי שכתב : \" מסרתי הוראת כ \" ק אדמו \" ר\nשליט \" א לר \" צ שי ' פאגעלמאן אתמול בלילה , הי ' עדיין על החתונה\n( שהתקיים בבנין הישיבה ) וגם היו שם עדיין אחי וזוגתו שיחיו . ואמר\nשישתדל עוד בזה . היום בוקר טלפן אלי אחי שי ' וגם זוגתו תחי ' להביע\nאת ברכתם למזל טוב על הבן , ואמר שכהוראת כ \" ק אדמו \" ר שליט \" א\nהחליט כבר להתחיל בגידול הזקן מיד . לפי זה יהי ' הוא המוהל אצל בננו\nשי ' ביום א ' הבע \" ל . אף שענין הגדלת זקן אצלו הי ' קשור בענין הברית\nמילה שלנו , אמר אחי שי ' שעושה זה כי זה הוראת כ \" ק אדמו \" ר שליט \" א ,\nהיינו שאף אם מפני סיב ה לא הי ' יכול להיות המוהל הי ' רצונו לקיים\nההוראה \" ( מצילום כתי \" ק – תשורה קרינסקי כ \" ח סיון תשע \" ג ע ' 42 :)\n[1 על כללות המכתב , כתב :]\nת \" ח ת \" ח על הבשו \" ט . כן יבש \" ט תכה \" י"],[9200110129,"129\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n[2 סימן בעיגול את התיבות \" להיות המוהל \", וכתב :]\nג \" ז מצוה רבה היא .\nהשייכות : גדולה מילה שנכרתו עלי ' יג ' בריתות – יגמה \" ר ( תו \" א ס \" פ\nלך ), שהם יג ' ת \" ד ( הצ \" צ עה \" פ והוא רחום – מילואים לתהלים .)\nקסא\nאדר \" ח אלול , תשכ \" ב ][\nמענה להרב מרדכי דוב אלטיין על שאלותיו : ( א ) בתניא פ \" ט כתוב משכן\nנפש הבהמית בלב בחלל השמאלי שהוא מלא דם , ומקום משכן נפש\nהאלקית הוא במוחין שבראש ומשם מתפשטת לכל האברים וגם בלב\nבחלל הימני שאין בו דם . לכאורה קשה לי על זה דהלא יש דם בכל\nהחללים שבלב ; ( ב ) כאשר אומ רים ג \" ן סדרים דאורייתא איזו סדרה אין\nחושבים בכלל , דלכאורה יש נ \" ד ; ( ג ) מה שכתוב ברז \" ל מהארץ לרקיע\nמהלך ת \" ק שנה וכן בין כל רקיע לרקיע וכן עובי כל רקיע ורקיע , האם\nזה מדה בגשמיות והלא בודאי אין הזמן ומקום דכל הרקיעים בשוה ,\nומהו החשבון דת \" ק –\nנדפס באגרות - קודש חכ \" ב ע ' שי .\nקסב\nד ' אלול , תשכ \" ב ][\nמענה לר ' שניאור זלמן הלוי דוכמאן ( מצילום כתי \" ק – ס ' \" לשמע אוזן \"\nהוצאת תשע \" ו ) ע '( 317 , 336 , 362 :)\n[1] במכתבו כתב ע \" ד דבריו בעת סעודת ברית - מילה של בנו של המזכיר\nהרח \" י קרינסקי , שנקרא על שם הרה \" ג הרה \" ח וכו ' הרב לוי יצחק ז \" ל\nאביו של כ \" ק אדמו \" ר שליט \" א : \" האב איך גיזאגט מי האט דאך גיגעבען\nאנאמען נאך אביו של כ \" ק שליט \" א , מי מיינט אז ער איז ג י ווען נא ר אין\nיעקאט ע רינאסלאוו , זאגין אייף אים אז חד בדרא איז ווייניק . און\nדערציילט אז איך האב אים פערהערט מצד א ענין אין עץ חיים , און\nגיזאגט אז איידער ווערט קלאר אין עץ חיים מוז מען זאגין אז מי איז\nקלאר אין אנדערע ענינים . און דערציילט וואס איך גידיינק פון זיינע\nהייליגע ווערטער דין גרמי דעשיראה ביר , און דער ענין וואס דער כותל"],[9200110130,"130\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nמערבי איז גאנץ גיבליבען ווייל דאס איז דער ה ' אחרונה של שם הוי '\nמלכות , וואס דערפאר זיינען מיר אידען גאנץ עד כי יבוא שילה בב \" א .\"\nכ \" ק אדמו \" ר שליט \" א סימן את התיבות : \" דין גרמי דעשיראה ביר , און\nדער ענין וואס דער כותל מערבי איז גאנץ גיבליבען ווייל דאס איז דער ה '\nאחרונה של שם הוי ' מלכות , וואס דערפאר זיינען מיר אידען גאנץ עד כי\nיבוא שילה בב \" א וכתב :\",\nת \" ח על הודיעו זה\n[2 ] במכתבו כתב – אשר בעת דבריו בסעודת הברית - מילה הקריא את\nמכתב \" ה ' מנחם - אב , הילולא של האריז \" ל החי , ה ' תשכ \" ב \" ( נדפס\nבאגרות - קודש חכ \" ב ע ' רצה - רצו ), בקשר ל \" התעוררות להוספה בפעולות\nלטובת כולל חב \" ד רמבעה \" ן .\"\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול תיבת \" מכתב \", וכתב :\n(2 עם המ \" מ ?)\nוראה גם ליקוט מענות קודש תשכ \" ג מענה קעו .][\n[3 ] במכתבו כתב שבעת האחרונה סובל מחולי ולכן אינו יכול ללכת\nלמקוה , אולם לפני כתיבת מכתבו זה לכ \" ק אדמו \" ר שליט \" א הלך\nלמקוה כהכנה לכך , כי \" כך הם החסידים .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nא ) על כללות הענין , כתב :(\nויה \" ר שזה ירפא הנ \" ל\nב ) על מה שכתב : \" כך הם החסידים \", כתב :(\nלמטרצ ' יקעס"],[9200110131,"131\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nקסג\nכ \" ה אלול , תשכ \" ב ][\nמענה להת ' אברהם יצחק ברוך גערליצקי שכתב : \" הנני רוצה לשאול את\nחוו \" ד של כ \" ק כי היות אשר ישנם כמה דברים אשר כנראה שאינם\nמתאימים כ \" כ בשבילי בנוגע לזה שאני לומד כאן בישיבת תו \" ת\nדמאנטרעאל דהיינו : א ) בכלל אינדערהיים יש כמה העלמות לסדר\nהלימוד , שנראה שחוץ ממאנטרעאל לא יהיו . ב ) פה במאנטריאל לא יש\nמשפיע על גיל שלי שהוא מעניין א \" ע לכאו \" א בפרט , או מתוועד אתנו ,\nאשר משא \" כ בנויארק שמעתי מכמה תלמידים שלומדים שם , שיש\nמשפיע על זה . ג ) פה בהבית המדרש יש רק מספר קטן של תלמידים , כי\nהיות שבמשך ב ' השנים שעברו עזבו הרבה בחורים את הישיבה און עכ \" ז\nניטא פון וועמן זיך אפצולערנען , שמשא \" כ בניוארק ישנם כמה בחורים\nשאפשר ללמוד מהם , גם אבי שי ' מסכים לכל האמור , וע \" כ הנני שואל\nחוו \" ד של כ \" ק אדמו \" ר שליט \" א באיזה ישיבה עלי ללמוד אי \" ה בשנה\nהבעל \" ט \" ( מצילום כתי \" ק – תשורה גולדברג כ \" ה טבת תש \" פ ע ' 20 :)\nיבקש אביו שי ' שידבר בכהנ \" ל עם הנהלת תו \" ת בנויארק ][ ובאם\nיסכימו כהנ \" ל יהא בשטומו \" צ\nקסד\nתשכ \" ב ][\nמענה להמזכיר הרח \" י קרינסקי שכתב – בקשר לתערוכת ספרי קה \" ת\nביריד הספרים הבינלאומי השנתי המתקיים בארצות הברית : \" מצו \" פ\nדו \" ח מההוצאה והכנסה של התערוכה דנויארק תשכ \" ב , ורשימה מאלו\nשעזרו בזה . מצורף ג \" כ הדו \" ח משנות תש \" כ ותשכ \" א , להשוואה . יש\nלציין שהשתא הי ' סך המבקרים בהתערוכה בכלל לכה \" פ בערך 30%\nפח ות מאשתקד , ולפי חשבון זה נמכרו מהוצאות המל \" ח לאחוז יותר\nגדול מהמבקרים \". על הדו \" ח המצורף , כתב כ \" ק אדמו \" ר שליט \" א\n( מצילום כתי \" ק – תשורה ניו כ \" ה אד \" ש תשס \" ח ע ' 22 :)\nהריוח העיקרי – הפרסום בכלל , וברוחניות בפרט .\nובודאי עוד יתקבלו"],[9200110132,"132\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nליקוט מענות קודש\n– תש כ \" ג –\nקסה\nלאחר יום ב ' דראש השנה , תשכ \" ג ][\nמענה להמניחים על שאלתם במאמר ד \" ה יבחר לנו גו ' שנאמר בהתועדות\nיום ב ' דראש השנה ( תשורה אסטער י \" ח מנ \" א תשפ \" א ע ' 35 :)\nהכוונה שבחי ' חפץ חסד רק ענין דהלמעלה ( אין כלל ענין מלתתא )\nומבחי ' זו נמשך הענין במי נמלך . כ \" ז בתחילת הבריאה . החידוש\nדעכשיו דתק \" ש שייך \" ומגלה \" עצם הנשמה המושרשת בעצמות כבי '\nלמע ' ( עצם הנשמה או פעולתה – תק \" ש .) לא מפני הכרעה \" והכרח \"\nשכלי שכר על שמקיים מצוה – כ \" א כשנתגלה עצם ממשיך עצם\nשמושרש בו ( וכדיוק הלשון בסי ' \" עצם \", כו \" כ פעמים ) – בחירה –\nיבחר לנו גו '\" שרצון המוחלט שם יומשך ועד הדרגות רצון במי נמלך ,\"\nושם התקיעת שופר מכריעה מצד היותה פעולת \" צדיקים \" – קיום\nמצוה , ( ומקודם ולמעלה מזה תק \" ש כבקשת מלוך והכתרה \" במה\nבשופר \") וזהו מעין שכר ולא בחירה בטהרתה .\nקסו\nי \" א תשרי , תשכ \" ג ][\nמענה להמזכיר הרי \" ל גראנער שכתב : \" שמעתי אשר בסעודת מוצאי\nיוהכ \" פ הואיל כ \" ק אדמו \" ר שליט \" א לאמר בנוגע לירידת משה עם\nהלוחות ביוהכ \" פ , שהי ' זה במוצאי יוהכ \" פ . ולכאורה במס ' שבת פו , א\nאיתא ( וברש \" י שם ) כל עליותיו וכל ירידותיו בהשכמה הי '. וברש \" י\n( שמות לד , כט ) ד \" ה ויהי ברדת משה : כשהביא לוחות אחרונות ביום\nהכפורים \" ( מצילום כתי \" ק ; ס ' \" היכל מנחם \" ח \" ב ע ' עט - פא :)\n[1 על מה שכתב : \" הואיל כ \" ק אדמו \" ר שליט \" א לאמר \", כתב :]\nלהיפך שלפענ \" ד קושית הבאת הלוחות ביוהכ \" פ ( כי דרפרם בדותא היא\n– כריתות יד , א ) מעיקרא ליתא , כי ע \" י שהביא [ הלוחות ביוהכ \" פ ] נקבע\nהיום ליום איסור הוצאה והובאה"],[9200110133,"133\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n[2 ] על מה שכתב : \" בנוגע לירידת משה עם הלוחות ביוהכ \" פ , שהי ' זה\nבמוצאי יוהכ \" פ \", כתב :\nשיש אחרונים אומרים שהי ' זה במוצאי יוהכ \" פ ][\nובזה מתרצים 1 הבאת הלוחות מההר למחנ \" י ביוהכ \" פ .) 2 ) ויש להוסיף\n– ולא נזכר אמש – שבזה מתורץ ג \" כ בפשטות כמה מקושיות תוד \" ה\nכדי ( בק פב , א .)\n[3 ] על מה שכתב : \" ולכאורה במס ' שבת פו , א איתא ( וברש \" י שם ) כל\nעליותיו וכל ירידותיו בהשכמה הי '\", כתב :\n– שם : 1 ) רק אליבי ' דרע \" ק ( אדה \" ז בסוף הל ' פסח פוסק דלא כרע \" ק )\n2) להנ \" ל במס ' שבת ][ מדובר – כפשוטו בפ ' דמתן תורה וזמנה ( כמובן\nמלבד המפורש בבוקר )\n[4 על תיבת : \" וברש \" י \", כתב :]\nגברא אַגבר א קרמית !?\n[5 על מה שכתב : \" וברש \" י ( שמות לד , כט ) ד \" ה ויהי ברדת משה :]\nכשהביא לוחות אחרונות ביום הכפורים \", כתב :\n( בדוחק יל \" פ למיעוטי \" מוציוהכ \" פ \" דבפרש \" י ( יתרו יח , יג )) אבל הוא\nבפי ' בתוד \" ה כדי ( ב \" ק פב , א ) דבבוקר יוהכ \" פ .\nבחזקוני ( תשא לד , כח ) ועוד .\nוראה בסדה \" ד .\nדבר פלא ברבעה \" ת עקב עה \" פ ואנכי עמדתי : \" ולמחר ( דיוהכ \" פ ) ירד !\"\n[ אלא שבלאה \" כ צ \" ע שם בחשבון הימים . ובתוס ' הראש – ב ' הענינים\nבשינוי . ואכ \" מ .]\nקסז\nי \" א תשרי , תשכ \" ג ][\nמענה להת ' דוד קרץ והת ' יוסף הרטמן שכתבו – בקשר לההשתדלות\nלהארכת זמן שהותם בחצרות קדשנו : \" מוסג \" פ שני המכתבים\nשברצונינו לשלוח ל [ הרב משה צבי ] נרי ' ול [ הרב אפרים ] וולף כפי שכ \" ק\nאדמו \" ר שליט \" א הורה לנו ביחידות . מאחר שאנו מזכירים במכתבים"],[9200110134,"134\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nאת כ \" ק אדמו \" ר שליט \" א ברצוננו להראות את המכתבים לפני שנשלחם .\nואנו מבקשים ברכת כ \" ק אדמו \" ר שליט \" א להצלחה בענין זה \"\n( מהעתקה . המענה מתפרסם בזה לראשונה באדיבות משפחת ר ' דוד קרץ\nע \" ה וזכות הרבים תלוי ' בהם :)\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את מה שכתבו : \" ואנו מבקשים\nברכת כ \" ק אדמו \" ר שליט \" א להצלחה בענין זה \", וכתב :\nאזכיר על הציון\nבטח בינתיים הם במסגרת ת ' תו \" ת כדבעי ואת \" ל – הרי ג \" ז שייך\nלהצלחת ההשתדלות\n[ וראה לקמן מענות : קסח , קסט , קע , קעא .]\nקסח\nלאחר שמחת תורה , תשכ \" ג ][\nמענה להת ' דוד קרץ ( מהעתקה . המענה מתפרסם בזה לראשונה\nבאדיבות משפחת הנמען ע \" ה וזכות הרבים תלוי ' בהם :)\n[1 ] במכתבו כתב : \" בקשה בנוגע לרפואה של דודי . . וברכה לאחותי . .\".\nמענה כ \" ק אדמו \" ר שליט \" א :\nאזכיר עה \" צ\n[2 במכתבו כתב :] \" מה שכ \" ק אדמו \" ר שליט \" א אמר לי בהתוועדות\nשעשינו מה שצריכים לעשות , הבנתי שזה עולה גם על מה שכ \" ק אד \" ש\nאמר לי ביחידות בנוגע שבקשת הארכה ע \" י עו \" ד שאפילו אם העו \" ד פועל\nבדרכים לגליות מ \" מ זה נוגע רק אחרי שמחת תורה . האם זה נכון ולכן\nאין צורך יותר לעו \" ד .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nבאם ע \" ע אין ידיעה מהרב נרי ' שי ' – כדאי לטלגרף לו\nמהיר\n[ נוסח הטלגרף הוכנס לכ \" ק אדמו \" ר שליט \" א והואיל להגיהו : תחלה\nנכתב : \" בהוראת הרבי שליט \" א אנו מטלגרפים מה עם הארכת שהותינו\nקרץ הרטמן \". וכ \" ק אדמו \" ר שליט \" א הגי ' שיהי ' כתוב : \" הרבי שליט \" א"],[9200110135,"135\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nשאלנו לתוצאות השתדלות כת \" ר בנוגע הארכת שהותינו כאן נקודה\nתודה על השתדלותו הנמרצה ונא מענה טלגרפי קרץ הרטמן .]\"\nקסט\nועש \" ק נח , כ \" ח תשרי , תשכ \" ג ][\nמענה להת ' דוד קרץ והת ' יוסף הרטמן שכתבו : \" באור לכ \" ז תשרי יום\nחמישי שלחנו את הטעלעגראמא להרב נרי ' שי '. עדיין אין תשובה מוולף\nומנרי '. האם כדאי לשלוח טעלעגראמא לוולף היום אחה \" צ שתגיע אליו\nאי \" ה במוצש \" ק בתוכן הבא : וולף ישיבה לוד מדוע אין ידיעות בנוגע\nלהארכת שהו תינו כאן תודה על השתדלותו עד עכשיו מחכים לתשובה\nהרטמן קרץ \" ( מהעתקה . המענה מתפרסם בזה לראשונה באדיבות\nמשפחת ר ' דוד קרץ ע \" ה וזכות הרבים תלוי ' בהם :)\n[1 על מה שכתבו : \" שלחנו את הטעלעגראמא \", כתב :]\n1 השלמו בעד המענה לכאן ?.\n[2 סימן בעיגול את התיבות : \" היום אחה \" צ \", וכתב :]\n2 תגיע לשם בש \" ק ויטפלו בה אנשי הדואר וכו '.\n[3 על נוסח המברק , כתב :]\nא ) תיבת \" מחכים \"( – תיקן \" ו מחכים .\"\nב ) מחק תיבת \" לתשובה \", וכתב :( \" למענה .\"\nקע\nאדר \" ח מרחשון , תשכ \" ג ][\nמענה להת ' דוד קרץ והת ' יוסף הרטמן שכתבו : \" ע \" ע לא קבלנו שום\nתשובה מהרב וולף ומהרב נרי '. הרב חדקוב שי ' אמר לדוד שי ' קרץ שוולף\nכתב לו – שלא הצליח להשיג הארכה , כי אמרו במשרד הבטחון שלא\nיסרב בענין זה . כן כתב וולף שמזכירתו של נרי ' אמרה לו ( בטלפון ) שהרב\nנרי ' שלח לנו תשובה . אנו שואלים האם להרשם – להכנס הלילה\nליחידות , כי איננו רוצים לנסוע מבלי להכנס ליחידות , או לחכות למענה\nמהרב נרי '? ( שיתכן שיגיע רק מחר ובו תשובה חיובית – שהצליח בס \" ד"],[9200110136,"136\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nלהשיג הארכה )\" ( מהעתקה . המענה מתפרסם בזה לראשונה באדיבות\nמשפחת ר ' דוד קרץ ע \" ה וזכות הרבים תלוי ' בהם :)\nכ \" ק אדמו \" ר שליט \" א מחק את התיבות \" אנו שואלים האם \", וסימן בחץ\nאת התיבות \" להרשם – להכנס הלילה ליחידות כו .\"'\nקעא\nבדר \" ח מרחשון , תשכ \" ג ][\nמענה להת ' דוד קרץ שכתב : \" בנוגע לאפשרות שהותי כאן יותר זמן , לא\nקיבלתי היום שום מכתב . אחרי ששאלתי אמש ביחידות מה שבקשני . .\nקבלתי ממנו היום מכתב , המצורף כאן , בו כותב פרטים מדויקים אודות\nאחיו ושואל גם בנוגע להוריו ובנוגע לעצמו , אבקש את כ \" ק אדמו \" ר\nשליט \" א מענה בנוגע לשאלותיו . ואבקש את ברכת כ \" ק אדמו \" ר שליט \" א\nשאוכל לבוא ואבוא לכאן עוד פעם בקרוב \" ( מהעתקה . המענה מתפרסם\nבזה לראשונה באדיבות משפחת הנמען ע \" ה וזכות הרבים תלוי ' בהם :)\nסימן בעיגול את מה שכתב : \" בנוגע לאפשרות שהותי כאן יותר זמן , לא\nקיבלתי היום שום מכתב \", כתב :\n1 . א \" כ יסע בשעטומו \" צ\nעל מה שכתב : \" בו כותב פרטים מדויקים אודות אחיו \", כתב :\n2 . כמענתי אתמול לעשת כדעה אחידה של שני רופאים מומחים\nבמקצוע .\nעל מה שכתב : \" ושואל גם בנוגע להוריו \", כתב :\n3 . מקום לחוות דעתי באם הם בעצמם יכתבו כל הפרטים שבענין\nעל מה שכתב : \" ושואל . . בנוגע לעצמו \", כתב :\n4 יתייעץ עם הררש \" ח שי ' ויעשה כהוראתו ..\nעל מה שכתב : \" ואבקש את ברכת כ \" ק אדמו \" ר שליט \" א שאוכל לבוא\nואבוא לכאן עוד פעם בקרוב \", כתב :\n5. אזכירו עה \" צ\nעל כללות המכתב , כתב :\n6. להחזיר המצורף"],[9200110137,"137\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nקעב\nי \" ד מרחשון , תשכ \" ג ][\nמענה לר ' שלום דובער וישצקי שכתב : \" הננו להודיע לכ \" ק אדמו \" ר\nשליט \" א שבנינו שליט \" א נכנס היום בשעה טובה ומוצלחת חצי שעה\nקודם חצי היום בעזרת השי \" ת לבריתו של אברהם אבינו ונקרא שמו\nבישראל יוסף יצחק ות \" ל שהכל כשורה . כן יתן השי \" ת שנודיע לכ \" ק\nאדמו \" ר שליט \" א אך ורק בשו רות טובות . בתוך הסעודה למדנו בתורה\nאור המאמר \" בעצם היום הזה נמול אברהם וגו '\"\" ( מצילום כתי \" ק –\nתשורה וילהלם ו ' תמוז תשפ \" א ע ' 25 :)\n[1 על מה שכתב : \" ונקרא שמו בישראל יוסף יצחק \", כתב :]\n[ יוסף יצחק ] שליט \" א\n[2 על כללות המכתב , כתב :]\nת \" ח על הבשוט ויגדלוהו לתחומע \" ט מתוך הרחבה\nקעג\nכ \" א מרחשון , תשכ \" ג ][\nמענה לא ' על מכתבו בו כמה שאלות בהשיחות ( מצילום כתי \" ק – תשורה\nגרשוביץ ט \" ו אלול תשע \" ז ע ' 13-14 :)\n[1 ] במכתבו כתב : \" על היסוד שהוד כ \" ק אד \" ש העיר כמ \" פ לשום לב\nלהמ \" מ בהמאמרים והשיחות הנני להעיר בזה בשני ענינים והם : . .\".\nמענה כ \" ק אדמו \" ר שליט \" א :\n(1 ת \" ח ת \" ח ביותר על הנ \" ל . ובודאי גם להבא ינהוג ככה .)\n[2 במכתבו כתב :]\n\" בשיחת י \" ט כסלו תשכ \" ב – יצאה לאור בתוכן ענינים פ ' לך דהאי שתא\nתשכ \" ג [ לקו \" ש ח \" ג ע ' 763 ] – ששיטת אדמוה \" ז כדעת בעל מנורת המאור\nמהר \" י אלנקאוה שקטן מאימתי בא לעולם הבא משעה שנימול .\nהנה בשו \" ע או \" ח קכ \" ד סעיף י ' כותב אדמוה \" ז וילמד אדם בניו הקטנים\nויחנכם לענות אמן ומיד שהתינוק עונה אמן יש לו חלק לעוה \" ב ."],[9200110138,"138\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nוזה מביא הרמ \" א בשו \" ע בסימן הנ \" ל , וכמו שמשמע מדרכי משה בטור\nאו \" ח בזה הסימן הנה זה הדין יסודו על הדעה ( בסנהדרין ק \" י ) מאימתי\nזוכה וכו ' משהתחיל לענות אמן .\nואפשר שזהו שמובא בשיחת כ \" ק אד \" ש הוא ממהדו \" ב של שו \" ע\nאדמוה \" ז או באו \" א . וללמוד אני צריך .\"\nזה )(\nכ \" ק אדמו \" ר שליט \" א מחק את התיבות : \" ואפשר ש ו \", \" או באו \" א .\nוללמוד אני צריך \"; וכתב :\n(2) זה שמובא בשיחת כ \" ק אד \" ש הוא ][ להסברת ה [ מהדו \" ב של שו \" ע\nאדמוה \" ז ] כמפורש בשיחה שם . ועוד וג \" ז עיקר – בכדי שלא יקשה\nמרמ \" א הנ \" ל על מ \" ש ברמ \" א ביו \" ד ( כמצויין בתוכן ענינים הנ \" ל ) אולי\nאפ \" ל דמר אמר חדא כו ' ולא פליגי בזה ( אף שנאמר בל ' מחלוקת . וראה\nלקו \" ת ס \" פ קרח וקונ ' ומעין ). ומחלקותם – בדרגתם בעוה \" ב ואכ \" מ .\n[3 ] במכתבו כתב : \" דרך אגב הנה בשו \" ע אדמוה \" ז בסימן קכ \" ד הנ \" ל\nמשנה ממה שמובא ברמ \" א בשו \" ע , בשני ענינים : א ) שמדייק וילמד וכו '\nומוסיף ויחנכם , ב ) ברמ \" א כותב הטעם כי מיד שהתינוק עונה אמן וכו '\nואדמוה \" ז אינו כותב הטעם ע \" ז רק שני ענינים שילמד וכו ' ומיד\nשהתינוק עונה א מן וכו .\"'\nמענה כ \" ק אדמו \" ר שליט \" א :\n(3 כי מיד כו ') – בכלבו ( סו \" ס יא ) אינו בסגנון של טעם ב ) מתורץ בא :'.\nלחינוך – א \" צ בטעם מיוחד דכי מיד כו '. וק \" ל .\n[4 ] במכתבו כתב : \" כן דרך אגב נתעוררתי שלכל הדעות המובא בסנהדרין\nשם משעה שנולד , משעה שסיפר , משעה שנזרע ( ואפשר גם משעה שעונה\nאמן ) אין חילוק בין זכר לנקבה , משא \" כ לדעה של משעה שנימול הלא\nהוא דוקא בזכר , והגם שבסנהדרין הלשון קטן מאימתי בא לעוה \" ב הנה\nבירושלמי שביע ית פ \" ד הלשון קטני ישראל ואפשר לפרש הכונה ג \" כ\nלנקבות ( ושם בירושלמי הלשון ג \" כ משהוא יודע לענות אמן בביהכנ \" ס .\")\nמענה כ \" ק אדמו \" ר שליט \" א :\n(4 גם בנקבה כיון דכמהילא דמיא ועיין לקו \" ת עקב יז , ב וביתר בי ')\nבסי ' שער ברהמ \" ז"],[9200110139,"139\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\n[5 במכתבו כתב :]\n\" במכתב כ \" ק אד \" ש מן ז ' מ \" ח דהאי שתא [ אגרות - קודש חכ \" ב ע ' שמו ,]\nכותב שעפמש \" כ אדה \" ז בשו \" ע או \" ח רסקי \" ז ואף כו ' גם היום כו ' י \" ל\nדמתורצת קושית הש \" ך ( מחו \" מ סימן מ \" ג סקמ \" ז .)\nהנה זה שכותב אדמוה \" ז ברסקי \" ז באו \" ח ( בחצאי עיגול ואינו מצוין\nהמקור לזה ) הנה הלשון הזה ממש מובא בר \" ן על מס ' תענית ומובא בבית\nיוסף טור או \" ח סימן הנ \" ל , וממילא הפליאה יותר על הש \" ך הנ \" ל ( ראיתי\nשהקרבן נתנאל על הרא \" ש בתענית ( ד \" י ) כותב על תירוץ הר \" ן שזהו\nדוחק .\")\nמענה כ \" ק אדמו \" ר שליט \" א :\n(5 ) הל ' כבתראי אדה \" ז ][\nועוד להזכיר זכות אבות ובפרט בשנת קן להסתלקות וכו .'\nועוד : הר \" ן הוא בעיקרו מפרש – אדה \" ז בשו \" ע פוסק .\nקעד\nכ \" א כסלו , תשכ \" ג ][\nמענה להרב יצחק דוב אושפאל שכתב :\n\" ע \" פ הוראת כ \" ק עיינתי בהספרים שנתן לי כ \" ק , לקטתי מהם ענינים\nאחדים , ודיברתי אודותם עם הנאספים בעת סעודת מרעים בשבוע\nהעברה , ובדעתי אי \" ה להוסיפם .\nבדעתי הי ' לגמור עבודתי בהקדם האפשרי , ולקיים ג \" כ רצון המדפיסים\nהמזרזים אותי ביותר , והנני רק לשאול , אם עלי לחכות עד אשר אקבל\nאיזו הערות מכ \" ק , ברצוני להדפיסם בתחילת הספר , בצירוף הערות כ \" ק\nהכתובים בהספר טהרת יו \" ט בתחילתו .\nנעים לי מאוד להזכיר לפני כ \" ק התקופה דשנות תש \" ד – תש \" ה , אשר\nכ \" ק זיכני בעבודתי בקדש , לעשות המראה מקומות ממאמרי שנות ת \" ש\n– תש \" ד ומההמשך מים רבים . הצעות כ \" ק והוראותיו אז בעבודתי , הנה\nתמיד אלי למאור עינים , גם היו לעזרתי המרובה כעת בעבודתי אשר\nעמלתי . מאז נתקשרתי אל כ \" ק בנימי נפשי , ודבריו תמיד אלי למשיב נפש\nלחזקני ולשמחני .\""],[9200110140,"140\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nמענה כ \" ק אדמו \" ר שליט \" א ( מהעתקה . המענה מתפרסם בזה לראשונה\nבאדיבות משפחת הנמען ע \" ה וזכות הרבים תלוי ' ב הם :)\nאין לחכות , כ \" א אדרבה להוסיף בזריזות ע \" פ מ \" ש באגרת הקדש סי '\nכ \" א להראות שמחתו וחפצו וכו .'\nקעה\nימי חנוכה , תשכ \" ג ][\nמענה לר ' שניאור זלמן הלוי דוכמאן שכתב : \" מהענינים אשר אני ממלא\nתפקידו של הגבאי ר ' יוחנן שיחי ' הוא ג \" כ הדלקת נרות חנוכה בעת\nהתפלה . עס איז דאך אין אדם עומד על דבר הלכה אלא א \" כ כו ' האב איך\nגירעכענט אז ביום איז דאך ניט שייך נהנה לאורם ? איז וואס דארף מען\nדעם שמש ? ע \" כ אם אך רק באפשר ירשום כ \" ק הטעם \" ( מצילום כתי \" ק\n– תשורה חאנין כ \" ט כסלו תשס \" ג ע ' 80 . תשורה דוכמאן ט \" ו אלול\nתשע \" ד ע ' 27 :)\nבבקשה למסור להרש \" ז שי ' דוכמאַן\nי \" ל שיש עוד טעמים בענין ה \" שמש \" – וכמו : שלא להכשל בהדלקת נר\nמנר ( ע \" י קיסם ); דוגמת הכהן המדליק הנרות ( שעפ \" ז מבוארת התמי '\n– שהשמש מקומו למעלה מן הנרות . וארז \" ל הסימן : שרפים עומדים\nממעל לו ). ועוד .\nקעו\nז ' טבת , תשכ \" ג ][\n\" צעטל \" בכתי \" ק שכתב כ \" ק אדמו \" ר שליט \" א לר ' שניאור זלמן הלוי\nדוכמאן – בקשר למכתב \" ה ' מנחם - אב , הילולא של האריז \" ל החי ,\nה ' תשכ \" ב \" ( נדפס באגרות - קודש חכ \" ב ע ' רצה - רצו ) בקשר ל \" התעוררות\nלהוספה בפעולות לטובת כולל חב \" ד רמבעה \" ן \" ( מצילום כתי \" ק – ס '\nלשמע אוזן \" ( הוצאת תשע \" ו ) ע '\" 317 :)\nהנוצל המכ ' כדבעי ?\nוהרי השנה קן שנה להסתלקות הילולא של מייסד הכולל – אדה \" ז"],[9200110141,"141\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nקעז\nלאחר יו \" ד שבט , תשכ \" ג ][\n\" צעטל \" בכתי \" ק שכתב כ \" ק אדמו \" ר שליט \" א להמניחים בו ציין את\nהמראי - מקומות להמדובר במאמר ד \" ה באתי לגני דיו \" ד שבט ( מצילום\nכתי \" ק – ריש תו \" מ התועדויות חל \" ו ( תשכ \" ג ח \" ב :))\nתורת הבעשט לקו \" ת לג \" פ סג , ב .\nהה \" מ רמזי תהלים בתחלתו\nאדה \" ז עוד ביאור יונתי אגה \" ק כ ( קלב , א )\nאדהאמ \" צ תו \" ח מקץ פח , ב\nהצ \" צ אוה \" ת תיח , ב .\nמהר \" ש מים רבים בתחלתו\nאדנ \" ע עה \" ח פ \" א ואילך\nלסי \" ג בההמשך\nקעח\nח \" י שבט , תשכ \" ג ][\nמענה להשליח ר ' שבתי אלפערן על מכתבו ( להמזכיר הרחמ \" א חדקוב )\nבו כתב : \" במכתבי ששלחתי לכ \" ק אדמו \" ר שליט \" א כתבתי ( בין השאר )\nשקבלתי ענין הרבנות פה , ובנוגע לפועל , לע \" ע , הענין של סדור קדושין ;\"\nוכתב , שכיון שרואה אשר בנוגע לכמה דברים נוהג א ' הרבנים במקומו ,\nע \" פ מה שנה גו הרבנים שלפניו , אחרת ובמנוגד להנהוג בניו יארק וכו :'\n\" לכן אני רוצה לבקש מכ ' שיברר אצל כ \" ק אדמו \" ר שליט \" א אם עלי\nלנהוג כן ג \" כ או לשנות את זה , אבל אפשר יבוא לידי מחלוקת כי כבר\nהורגלו כן מהרבה שנים . .\" ( קונטרס ועד הנחות בלה \" ק ש \" פ וישלח\nתשע \" ה ע ' 14 :)\n[1 ] במכתבו כתב : \" א ) אין ענין של \" יחוד \" אחר החופה . טעמו – שפשוט\nאין שם חדר נכון בקרוב לאולם הגדול , וגם מפני שרובם ככולם הם בלתי\nטהורים וממילא אינו רוצה לגרום יחוד גמור , ואמר שמצא איזה היתר\nע \" ז שלא לעשות לגמרי במצב כזה , רק בזמן שיש חתונה יותר חרדי הוא\nמצוום שיעשו יחוד בבית בעדים . ב ) כשמדבר אודות \" מקוה \" עם הכלה"],[9200110142,"142\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nהוא מדבר סתם , דהיינו בלי ענין של ספירת ז \" נ מקודם , וא \" כ איני מבין\nאת זה כלל האם יש ענין כזה , כי אפשר שהיא ממש בשעת טבילה בלתי\nטהורה וכו .\"'\nכ \" ק אדמו \" ר שליט \" א הורה ( להמזכירות ) לברר אצל רבני אנ \" ש דכאן .\n[2 במכתבו כתב : \" ג ) אין הכלה מסבבת סביב החתן כלל מקודם החופה .]\nטעמו – שאין נוהגים כן כאן . ד ) אם לא כתבו תנאים לפני החתונה , אינו\nכותב כלום בליל החתונה .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nכשיסביר שזהו ג \" כ ענין של מזל בטח ( ברובא דרובא ) יסכימו בשמחה\nקעט\nלאחר חג הפורים , תשכ \" ג ][\nמענה להמזכיר ר ' אליהו הכהן קווינט על מכתבו בקשר להמדובר\nבהתועדות פורים : \" נהנתי מאד מהמאמר ומהביאור למאמר , אבל לפי\nהשגתי לא הבנתי מה שכ \" ק ביאר אדות שכל האדם . ואמר בתוך דברי\nקדשו כי השכל רק מראה לאדם מה טוב ומה רע ואז אין מתעסק יותר\nולפי השכל לא יחרה לו אם ב וחר ברע . והביא ממורה נבוכים ומעוד\nביאורים . וכ \" ק ביאר מאמר חז \" ל יודע את רבונו ומתכוון למרוד בו ,\nרש \" י מביא מאמר זה על נמרוד ( בשם מדרש ) שעל כל מי שיודע את רבונו\nומתכוון למרוד בו אומרים שזהו כנמרוד . .\" ( מצילום כתי \" ק – תשורה\nפולטורק ג ' כסלו תשס \" ה ע ' 33 :)\n[1 על מה שכתב : \" כי השכל רק מראה לאדם מה טוב ומה רע \"] – מחק\nאת התיבות \" טוב . . רע \", וכתב :\nמה ][ אמת ומה ][ שקר\n[2 על מה שכתב : \" ואז אין מתעסק יותר \"] – מחק את התיבות \" ואז . .\nיותר \", וכתב :\nו אין מתעסק ][ בכל הגדר דטוב ורע"],[9200110143,"143\nליקוט מענות קודש – ה ' תש \" כ - ה ' תש כ \" ג\nקפ\nאדר , תשכ \" ג ][\nמענה להמניחים על שאלתם בהגהות כ \" ק אדמו \" ר שליט \" א בשיחה\nשהוגהה עבור חוברת \" תוכן ענינים לחזרת דא \" ח בבתי כנסיות \" לש \" פ\nויקהל - פקודי ( מצילום כתי \" ק – קונטרס שי \" ל ע \" י מערכת \" פרוייקט\nלקוטי שיחות \" ש \" פ תרומה תש \" פ ע ' 9-10 :)\n[1 במכתבם כתבו :]\n\" בענין מ \" ש בהשיחה סעיף ד ' וה ' שאדנים שייך להעבודה דלשם שמים\n– כחות הגלויים , וכללות המשכן להעבודה של בכ \" ד דעהו – עצם\nהנשמה , שלכן לא השתתפו טף בתרומת האדנים ורק בנדבת כללות\nהמשכן , שאלנו בפיתקא מהמבואר בקצרה בליקוט לפ ' תשא , ובארוכה\nבלקוטי שיחות [ ח \" א ] פ ' תשא ( ע ' 181 , וגם בפ ' תרומה ), שאדנים נוגע\nלעצם הנשמה , שבה כולם שוים , ולכן העשיר לא ירבה כו ', משא \" כ כללות\nהמשכן שייך ל כחות הגלויים , שיש בהם התחלקות , ולכן נדב כל אחד כפי\nנדבת לבו כו .'\nאם במה שנתקן בסעיף ד ' שאדנים היא העבודה דקב \" ע שמזה באים\nלהתחלת העבודה , לשם שמים ( ולא כמו שהי ' כתוב בההנחה שאדנים\nעצמם היא העבודה דלש \" ש ), שבהעבודה דלש \" ש אין מתבטא אמיתית\nעומק ההבנה דאחדות ה ', מתורץ שאלה הנ \" ל . כי העבודה דקב \" ע באה\nמצד העצם , ולכן האדנים שייכים להעצם יותר מכללות המשכן , כמבואר\nבליקוט לפ ' תשא . אלא שהתוצאה המסובבת ממנה – לשם שמים , לא\nמתבטא בה עומק ההבנה של אחדות ה '. היינו שבהבנת השכל שייכים\nהאדנים לכחות הגלויים , וכללות המשכן להעצם . כי בענין בכ \" ד דעהו\nמתבטא יותר ההבנה דאחדות ה ', התקשרות ויחוד עצם הנשמה\nבהעצמות . אלא שכ \" ז הוא רק בנוגע להבנה . משא \" כ באמיתית הענין ,\nהרי העבודה בכ \" ד דעהו היא רק מצד הבנת אחדות ה ', כחות הגלויים\n( אלא שבענין הגילויים קרובה יותר להעצם ), ואדנים שענינם קב \" ע שייך\nלהעצם ממש ( אלא שבגילוי ובהבנה לא מתבטא ( בהמסובב ממנה , לשם\nשמים ) התקשרות ויחוד עצם הנשמה בהעצמות .\")\nמענה כ \" ק אדמו \" ר שליט \" א :\nא ) על מה שכתבו : \" אם במה שנתקן בסעיף ד ' שאדנים היא העבודה כו \"'(\n– מחק את התיבות : \" ד קב \" ע )( \", \" שמזה באים ל התחלת )( \", \" ולא כמו שהי '(\nכתוב בהנחה ) וכתב :\";"]]});
